window.FO_PACKS=window.FO_PACKS||{};window.FO_PACKS["KS3"]={"KS3-001":{"objectives":["Hobi ve ilgi alanlarını İngilizce anlatmak","'Be interested in', 'be keen on' ve 'be into' kalıplarını doğru kullanmak","Bir kulüp için kısa bir açıklama ya da duyuru yazmak"],"dialogues":[{"title":"Club day","setting":"Okulun kulüp gününde Deniz, yeni tanıştığı Ece'ye hobilerini soruyor.","lines":[{"s":"Deniz","en":"Hi, I'm Deniz. What are you into?","tr":"Merhaba, ben Deniz. Neyle ilgilenirsin?"},{"s":"Ece","en":"I'm really into photography. I take photos of animals.","tr":"Fotoğrafçılığa çok meraklıyım. Hayvanların fotoğraflarını çekerim."},{"s":"Deniz","en":"That's cool! Do you use a phone or a camera?","tr":"Harika! Telefonla mı yoksa fotoğraf makinesiyle mi çekiyorsun?"},{"s":"Ece","en":"Mostly my old camera. My dad gave it to me.","tr":"Çoğunlukla eski fotoğraf makinem. Babam bana verdi."},{"s":"Deniz","en":"I'm interested in music. I play the bass guitar.","tr":"Ben müzikle ilgileniyorum. Bas gitar çalıyorum."},{"s":"Ece","en":"Really? We should start a music and photo club!","tr":"Gerçekten mi? Müzik ve fotoğraf kulübü kurmalıyız!"}]},{"title":"Asking the teacher","setting":"Ece, İngilizce öğretmeninden kulüp toplantıları için bir sınıf istiyor.","lines":[{"s":"Ece","en":"Excuse me, could we use the art room on Thursdays?","tr":"Affedersiniz, perşembe günleri sanat odasını kullanabilir miyiz?"},{"s":"Teacher","en":"What is it for?","tr":"Ne için?"},{"s":"Ece","en":"We want to start a club. We're keen on photography and music.","tr":"Bir kulüp kurmak istiyoruz. Fotoğrafçılık ve müzikle ilgileniyoruz."},{"s":"Teacher","en":"That sounds interesting. How many students are in the group?","tr":"Kulağa ilginç geliyor. Grupta kaç öğrenci var?"},{"s":"Ece","en":"Eight so far. Deniz is helping me with the plan.","tr":"Şimdiye kadar sekiz. Deniz planda bana yardım ediyor."},{"s":"Teacher","en":"Good. Bring me a written plan by Monday.","tr":"İyi. Pazartesiye kadar bana yazılı bir plan getir."}]},{"title":"Making a poster","setting":"Ece, kulüp afişi için Deniz'e mesaj atıyor.","lines":[{"s":"Ece","en":"Hey, I made a poster for the club!","tr":"Hey, kulüp için bir afiş yaptım!"},{"s":"Deniz","en":"Nice! Can I add a photo of my bass?","tr":"Harika! Bas gitarımın bir fotoğrafını ekleyebilir miyim?"},{"s":"Ece","en":"Of course. Can you also write a short description?","tr":"Tabii. Kısa bir açıklama da yazabilir misin?"},{"s":"Deniz","en":"Sure. Something like 'Music and photos for every student.'","tr":"Tabii. 'Her öğrenci için müzik ve fotoğraf.' gibi bir şey."},{"s":"Ece","en":"Perfect! I'll print it tomorrow.","tr":"Mükemmel! Yarın yazdıracağım."}]}],"reading":{"title":"My interests","paras":[{"en":"I'm a student who is into many things. In my free time I read comic books, but I'm also keen on cooking. I spend hours trying my grandmother's recipes on Sundays. Next year I'd like to learn to play the guitar, because I'm interested in rock music. My friends say I'm always busy, but I think hobbies make life more interesting.","tr":"Birçok şeyle ilgilenen bir öğrenciyim. Boş zamanlarımda çizgi roman okurum ama yemek yapmaya da meraklıyım. Pazarları saatlerce büyükannemin tariflerini deneyerek geçiririm. Gelecek yıl gitar çalmayı öğrenmek istiyorum, çünkü rock müziğe ilgi duyuyorum. Arkadaşlarım hep meşgul olduğumu söylüyor, ama bence hobiler hayatı daha ilginç hâle getirir."}]},"vocab":[{"w":"interest","ipa":"/ˈɪntrəst/","pos":"🎯","tr":"ilgi, ilgi alanı","ex":"My main interest is music.","exTr":"Ana ilgi alanım müzik."},{"w":"hobby","ipa":"/ˈhɒbi/","pos":"🎨","tr":"hobi","ex":"Painting is my favourite hobby.","exTr":"Resim yapmak en sevdiğim hobi."},{"w":"keen on","ipa":"/kiːn ɒn/","pos":"🔥","tr":"meraklı, ilgili","ex":"She is keen on science.","exTr":"Fen bilimlerine meraklı."},{"w":"photography","ipa":"/fəˈtɒɡrəfi/","pos":"📷","tr":"fotoğrafçılık","ex":"Photography needs patience.","exTr":"Fotoğrafçılık sabır ister."},{"w":"recipe","ipa":"/ˈresəpi/","pos":"📖","tr":"tarif","ex":"This recipe is easy.","exTr":"Bu tarif kolay."},{"w":"poster","ipa":"/ˈpəʊstə/","pos":"🪧","tr":"afiş, poster","ex":"I put a poster on the wall.","exTr":"Duvara bir afiş astım."},{"w":"description","ipa":"/dɪˈskrɪpʃn/","pos":"📝","tr":"açıklama, tanım","ex":"Write a short description.","exTr":"Kısa bir açıklama yaz."},{"w":"spend","ipa":"/spend/","pos":"⏳","tr":"(zaman) harcamak, geçirmek","ex":"I spend an hour on homework.","exTr":"Ödeve bir saat harcıyorum."}],"chunks":[{"en":"I'm really into…","tr":"…ile gerçekten ilgileniyorum."},{"en":"I'm interested in…","tr":"…ile ilgileniyorum."},{"en":"Could we use…?","tr":"…kullanabilir miyiz?"},{"en":"Something like…","tr":"…gibi bir şey."}],"grammar":{"point":"Talking about interests: interested in, keen on, into","tr":"İlgi duyduğumuz şeyleri anlatmak için 'be interested in', 'be keen on' ve 'be into' kalıplarını kullanırız. Bu kalıplardan sonra bir isim ya da -ing hâli gelir. 'Into' daha gündelik ve samimi bir ifadedir.","examples":["I'm interested in photography.","She's keen on learning Spanish.","We're really into rock music.","Are you into sports?"]},"questions":[{"q":"What is Ece really into?","a":"Photography."},{"q":"What does Deniz want to add to the poster?","a":"A photo of his bass."},{"q":"Why does Ece want to use the art room?","a":"To start a club about photography and music."}],"quiz":[{"q":"'I'm ___ photography.' (after 'keen')","o":["keen on","keen to","keen for"],"a":0,"why":"'Keen on' bir şeye ilgi duyduğunu anlatır."},{"q":"A 'recipe' is…","o":["a set of cooking instructions","a type of photo","a member of a club"],"a":0,"why":""},{"q":"Which word means 'hobi'?","o":["hobbit","hobo","hobby"],"a":2,"why":""},{"q":"I'm ___ in rock music.","o":["interesting","interested","interest"],"a":1,"why":"'Interested' kişinin ilgisini, 'interesting' ise şeyin ilginç olduğunu anlatır."}],"drills":[{"type":"Yerine koyma","prompt":"I'm interested in photography.","cue":"music","answer":"I'm interested in music."},{"type":"Dönüştürme","prompt":"We're really into rock music.","cue":"Olumsuz yap","answer":"We're not really into rock music."},{"type":"Soru yap","prompt":"I'm interested in music.","cue":"Are you…?","answer":"Are you interested in music?"}],"sounds":[{"focus":"/ɪ/ – /iː/","tr":"Türkçede uzun ve kısa ünlü ayrımı yok; İngilizcede kısa ve gevşek /ɪ/ ile uzun /iː/ kelimenin anlamını değiştirir. /ɪ/ sesinde dilini gevşek tut ve kısa bitir; /iː/ sesinde dudaklarını yay ve uzat.","pairs":["fill / feel","sit / seat","hit / heat"]}],"mission":{"brief":"Yeni bir kulübe katılmak istiyorsun. Claude, yeni tanıdığın öğrenci Burak olacak; ona ilgi alanlarını anlat ve Burak'ın hangi kulübe katılmak istediğini öğren.","persona":"Burak, a 13-year-old who is quiet at first and speaks in short sentences. Hidden fact: he secretly loves writing short stories and wants to join the school magazine club, but he is embarrassed and only reveals it if you ask good questions about what he enjoys doing quietly in his free time.","goal":"Burak'ın gizli hobisini öğren ve ona uygun bir kulüp önerisinde bulun.","opener":"Hi. Are you new in this club? I'm not really sure what to do here."}},"KS3-002":{"objectives":["Bir arkadaşlık sorununu basit cümlelerle anlatmak","'I feel…' kalıbıyla duygularını söylemek","Özür dileme ve barışma cümlelerini kullanmak"],"dialogues":[{"title":"A fight at school","setting":"Okul bahçesinde Deniz, en yakın arkadaşı Elif'le yaşadığı tartışmayı Mert'e anlatıyor.","lines":[{"s":"Mert","en":"Deniz, you look sad. What's wrong?","tr":"Deniz, üzgün görünüyorsun. Ne oldu?"},{"s":"Deniz","en":"Elif and I had a big fight. She didn't call me last night.","tr":"Elif'le büyük bir kavga ettik. Dün gece beni aramadı."},{"s":"Mert","en":"Oh no. Why did you fight?","tr":"Ah, olamaz. Neden kavga ettiniz?"},{"s":"Deniz","en":"She told our secret to the whole class.","tr":"Sırrımızı bütün sınıfa anlatmış."},{"s":"Mert","en":"That's really hurtful. Are you going to talk to her?","tr":"Bu gerçekten incitici. Onunla konuşacak mısın?"},{"s":"Deniz","en":"I don't know. I'm still angry.","tr":"Bilmiyorum. Hâlâ kızgınım."}]},{"title":"Saying sorry","setting":"Ertesi gün koridorda Elif, Deniz'e yaklaşıp özür diliyor.","lines":[{"s":"Elif","en":"Deniz, can we talk? I'm really sorry.","tr":"Deniz, konuşabilir miyiz? Gerçekten özür dilerim."},{"s":"Deniz","en":"You broke my trust. That was not nice.","tr":"Bana olan güvenimi kırdın. Bu hiç hoş değildi."},{"s":"Elif","en":"I know. I was wrong, and I feel bad about it.","tr":"Biliyorum. Yanlış yaptım ve bu yüzden kendimi kötü hissediyorum."},{"s":"Deniz","en":"Thanks for saying sorry. It means a lot.","tr":"Özür dilediğin için teşekkürler. Bu benim için çok şey ifade ediyor."},{"s":"Elif","en":"Can I make it up to you? Lunch is on me.","tr":"Bunu telafi edebilir miyim? Öğle yemeği benden."},{"s":"Deniz","en":"Okay. But no more secrets, promise?","tr":"Tamam. Ama artık sır yok, söz?"},{"s":"Elif","en":"Promise! Best friends again?","tr":"Söz! Yine en iyi arkadaşlar mıyız?"}]},{"title":"Talking to the counsellor","setting":"Rehberlik odasında Deniz, rehber öğretmen Selin Hanım'la konuşuyor.","lines":[{"s":"Selin","en":"Come in, Deniz. Take a seat.","tr":"Gel Deniz, otur."},{"s":"Deniz","en":"Thanks. I have a problem with my friends. Sometimes I feel left out.","tr":"Teşekkürler. Arkadaşlarımla bir sorunum var. Bazen kendimi dışlanmış hissediyorum."},{"s":"Selin","en":"I understand. Have you told them how you feel?","tr":"Anlıyorum. Onlara nasıl hissettiğini söyledin mi?"},{"s":"Deniz","en":"Not yet. I'm scared they will laugh at me.","tr":"Henüz değil. Benimle dalga geçmelerinden korkuyorum."},{"s":"Selin","en":"Try to speak calmly. A good friend will listen.","tr":"Sakin bir şekilde konuşmaya çalış. İyi bir arkadaş dinler."},{"s":"Deniz","en":"That sounds like a good plan. Thank you!","tr":"Bu iyi bir plan gibi. Teşekkür ederim!"}]}],"reading":{"title":"Every friendship has problems","paras":[{"en":"Every friendship has problems sometimes. Friends can argue, forget things or hurt each other by mistake. The important thing is to talk. Listen to the other person, say how you feel and try to say sorry when you are wrong. A true friend will listen and want to fix the problem together.","tr":"Her arkadaşlıkta bazen sorunlar olur. Arkadaşlar tartışabilir, bir şeyleri unutabilir ya da yanlışlıkla birbirini incitebilir. Önemli olan konuşmaktır. Karşındakini dinle, nasıl hissettiğini söyle ve yanlış yaptığında özür dilemeye çalış. Gerçek bir arkadaş dinler ve sorunu birlikte çözmek ister."}]},"vocab":[{"w":"argue","ipa":"/ˈɑːɡjuː/","pos":"🗣","tr":"tartışmak","ex":"We often argue about games.","exTr":"Oyunlar yüzünden sık sık tartışıyoruz."},{"w":"secret","ipa":"/ˈsiːkrət/","pos":"🤫","tr":"sır","ex":"Keep it a secret.","exTr":"Bunu sır olarak sakla."},{"w":"trust","ipa":"/trʌst/","pos":"🤝","tr":"güven","ex":"I trust my best friend.","exTr":"En iyi arkadaşıma güveniyorum."},{"w":"forgive","ipa":"/fəˈɡɪv/","pos":"🙏","tr":"affetmek","ex":"I forgive you.","exTr":"Seni affediyorum."},{"w":"upset","ipa":"/ʌpˈset/","pos":"😠","tr":"üzgün, kırgın","ex":"She is upset because of the fight.","exTr":"Kavga yüzünden kırgın."},{"w":"hurt","ipa":"/hɜːt/","pos":"😢","tr":"incitmek","ex":"Words can hurt people.","exTr":"Sözler insanları incitebilir."},{"w":"apologise","ipa":"/əˈpɒlədʒaɪz/","pos":"🙇","tr":"özür dilemek","ex":"I want to apologise.","exTr":"Özür dilemek istiyorum."},{"w":"scared","ipa":"/skeəd/","pos":"😱","tr":"korkmuş","ex":"I am scared of the dark.","exTr":"Karanlıktan korkuyorum."}],"chunks":[{"en":"Can we talk?","tr":"Konuşabilir miyiz?"},{"en":"I'm really sorry.","tr":"Gerçekten özür dilerim."},{"en":"Can I make it up to you?","tr":"Bunu telafi edebilir miyim?"},{"en":"Best friends again?","tr":"Yine en iyi arkadaşlar mıyız?"}],"grammar":{"point":"I feel + adjective","tr":"'Feel' fiilinden sonra duygu sıfatı gelir ve bu, nasıl hissettiğimizi anlatır. Türkçedeki 'hissediyorum' ifadesinin karşılığıdır. Sıfat her zaman aynı kalır, değişmez.","examples":["I feel sad.","She feels angry.","We feel happy after lunch.","Do you feel okay?"]},"questions":[{"q":"Why is Deniz sad?","a":"Because Elif told their secret to the whole class."},{"q":"What does Elif offer to do to make things better?","a":"She offers to buy Deniz lunch."},{"q":"What is Deniz scared of?","a":"Being laughed at by her friends."}],"quiz":[{"q":"Elif told their ___ to the whole class.","o":["secret","lunch","photo"],"a":0,"why":""},{"q":"Choose the best way to say sorry: 'I'm ___ sorry.'","o":["bad","really","tired"],"a":1,"why":"'Really sorry' = gerçekten özür dilerim."},{"q":"'Trust' means ___ someone.","o":["to believe","to hit","to forget"],"a":0,"why":"Trust = güvenmek."},{"q":"The best answer to 'Can we talk?' is…","o":["I like pizza.","It's raining.","Yes, let's talk."],"a":2,"why":""}],"drills":[{"type":"Yerine koyma","prompt":"I feel sad.","cue":"angry","answer":"I feel angry."},{"type":"Dönüştürme","prompt":"Elif is sorry.","cue":"We","answer":"We are sorry."},{"type":"Soru yap","prompt":"You feel happy.","cue":"question","answer":"Do you feel happy?"}],"sounds":[{"focus":"/θ/","tr":"Dilin ucunu üst dişlerin arasına koy ve üfle. 'S' ya da 't' gibi söyleme; 'thanks' kelimesinde dili dişler arasında tut.","pairs":["thanks / tanks","think / sink","bath / bass"]}],"mission":{"brief":"Görev: Claude, en yakın arkadaşıyla küsmüş Ece'yi oynayacak. Ona sorular sor, sorunun ne olduğunu öğren ve birlikte barışmak için bir plan yap.","persona":"Ece, a 13-year-old classmate who is upset with her best friend. Uses short, honest sentences and talks slowly. Hidden fact: Ece forgot her friend's birthday last week, and that is the real reason her friend is upset. She only admits it if the learner asks good open questions about the friend's feelings.","goal":"Arkadaşının asıl sorununu öğren ve barışmak için somut bir adım öner.","opener":"Hi. My best friend is upset with me, and I don't really know why."}},"KS3-003":{"objectives":["İnternette güvenli kalmak için kuralları İngilizce söylemek","Emir cümleleriyle uyarı ve tavsiye vermek","Güçlü şifre ve gizlilik kavramlarını açıklamak"],"dialogues":[{"title":"A strange message","setting":"Ödev yaparken Can, tanımadığı birinden mesaj alıyor ve Ada'ya gösteriyor.","lines":[{"s":"Ada","en":"Can, you look worried. What's wrong?","tr":"Can, endişeli görünüyorsun. Ne oldu?"},{"s":"Can","en":"A stranger sent me a message. He wants my photo.","tr":"Yabancı biri bana mesaj attı. Fotoğrafımı istiyor."},{"s":"Ada","en":"Oh no! Don't send it. Do you know him?","tr":"Ah, olmaz! Gönderme. Onu tanıyor musun?"},{"s":"Can","en":"No, I don't. His profile has no name.","tr":"Hayır, tanımıyorum. Profilinde hiç isim yok."},{"s":"Ada","en":"Block him and tell a trusted adult.","tr":"Onu engelle ve güvendiğin bir yetişkine söyle."},{"s":"Can","en":"Good idea. I'll tell my mum right now.","tr":"İyi fikir. Hemen annemize söyleyeceğim."}]},{"title":"Strong passwords","setting":"Bilişim dersinde öğretmen Murat, öğrencilere güçlü şifre nasıl yapılır anlatıyor.","lines":[{"s":"Murat","en":"Today we learn how to make a strong password.","tr":"Bugün güçlü bir şifre nasıl yapılır, onu öğreniyoruz."},{"s":"Ada","en":"What is a strong password?","tr":"Güçlü şifre nedir?"},{"s":"Murat","en":"It has long words, numbers and symbols. Never use your name.","tr":"Uzun kelimeler, sayılar ve simgeler içerir. Asla kendi adını kullanma."},{"s":"Can","en":"So 'Can123' is not good?","tr":"Yani 'Can123' iyi değil mi?"},{"s":"Murat","en":"Right, it's too easy to guess. Try a sentence instead.","tr":"Doğru, tahmin etmesi çok kolay. Bunun yerine bir cümle dene."},{"s":"Ada","en":"And should I share it with my friends?","tr":"Peki şifremi arkadaşlarımla paylaşmalı mıyım?"},{"s":"Murat","en":"Never. Passwords are private, like your toothbrush.","tr":"Asla. Şifreler özeldir, tıpkı diş fırçan gibi."}]},{"title":"Posting a photo","setting":"Akşam, Ada Can'a sınıf gezisinden çektiği bir fotoğrafı paylaşıp paylaşmayacağını soruyor.","lines":[{"s":"Ada","en":"Can, should I post this photo of our class trip?","tr":"Can, sınıf gezimizin bu fotoğrafını paylaşmalı mıyım?"},{"s":"Can","en":"Let me see. Are there other people in it?","tr":"Bir bakayım. İçinde başka insanlar var mı?"},{"s":"Ada","en":"Yes, Elif and Burak. They might not want it online.","tr":"Evet, Elif ve Burak. Onların internette olmasını istemeyebilirler."},{"s":"Can","en":"Good point. Always ask before you share someone's photo.","tr":"Haklısın. Birinin fotoğrafını paylaşmadan önce her zaman izin iste."},{"s":"Ada","en":"Okay. I'll ask them first and post it later.","tr":"Tamam. Önce onlara soracağım, paylaşmayı sonra yaparım."},{"s":"Can","en":"Smart. Your privacy matters too!","tr":"Akıllıca. Senin mahremiyetin de önemli!"}]}],"reading":{"title":"Stay safe online","paras":[{"en":"The internet is fun, but it can be risky. Keep your personal information private, such as your address and school name. Use strong passwords and never share them. If a stranger asks you for photos or secrets, do not reply. Block the person and tell a trusted adult. Think before you post, because pictures stay online for a long time.","tr":"İnternet eğlencelidir ama riskli de olabilir. Adresin ve okulunun adı gibi kişisel bilgilerini gizli tut. Güçlü şifreler kullan ve onları asla paylaşma. Yabancı biri senden fotoğraf ya da sır isterse cevap verme. Kişiyi engelle ve güvendiğin bir yetişkine söyle. Paylaşmadan önce düşün, çünkü resimler internette uzun süre kalır."}]},"vocab":[{"w":"stranger","ipa":"/ˈstreɪndʒə/","pos":"🧑","tr":"yabancı","ex":"Don't talk to a stranger online.","exTr":"İnternette bir yabancıyla konuşma."},{"w":"password","ipa":"/ˈpɑːswɜːd/","pos":"🔑","tr":"şifre","ex":"My password is private.","exTr":"Şifrem özeldir."},{"w":"private","ipa":"/ˈpraɪvət/","pos":"🔒","tr":"özel, gizli","ex":"Keep your address private.","exTr":"Adresini gizli tut."},{"w":"block","ipa":"/blɒk/","pos":"🚫","tr":"engellemek","ex":"Block that account.","exTr":"O hesabı engelle."},{"w":"trusted","ipa":"/ˈtrʌstɪd/","pos":"🤝","tr":"güvenilir","ex":"Talk to a trusted adult.","exTr":"Güvenilir bir yetişkinle konuş."},{"w":"post","ipa":"/pəʊst/","pos":"📤","tr":"paylaşmak (internette)","ex":"Don't post your photo.","exTr":"Fotoğrafını paylaşma."},{"w":"address","ipa":"/əˈdres/","pos":"🏠","tr":"adres","ex":"Never share your home address.","exTr":"Ev adresini asla paylaşma."},{"w":"personal","ipa":"/ˈpɜːsənl/","pos":"🙋","tr":"kişisel","ex":"Personal information is important.","exTr":"Kişisel bilgiler önemlidir."}],"chunks":[{"en":"Block him!","tr":"Onu engelle!"},{"en":"Tell a trusted adult.","tr":"Güvendiğin bir yetişkine söyle."},{"en":"Ask before you share.","tr":"Paylaşmadan önce izin iste."},{"en":"Think before you post.","tr":"Paylaşmadan önce düşün."}],"grammar":{"point":"Imperatives (commands)","tr":"Emir cümleleri birine bir şeyi yapmasını ya da yapmamasını söyler. Fiil, başında özne olmadan doğrudan kullanılır. Olumsuz emirde fiilin başına 'Don't' gelir.","examples":["Block him.","Don't share your password.","Ask before you post.","Tell a trusted adult."]},"questions":[{"q":"What should Can do with the stranger?","a":"Block him and tell his mum."},{"q":"Should you share your password with friends?","a":"No, never."},{"q":"Why should Ada ask Elif and Burak first?","a":"Because the photo shows them too, and they may not want it online."}],"quiz":[{"q":"A stranger asks for your photo. What do you do?","o":["Send it","Block him","Share it"],"a":1,"why":""},{"q":"Which is a strong password?","o":["1234","can","Blue!Sky7"],"a":2,"why":"Uzun ve karışık: harf, sayı ve simge içerir."},{"q":"'Tell a ___ adult.'","o":["trusted","stranger","private"],"a":0,"why":""},{"q":"Before you post a photo, you should…","o":["share it quickly","hide your phone","ask the people in it"],"a":2,"why":""}],"drills":[{"type":"Yerine koyma","prompt":"Block him.","cue":"her","answer":"Block her."},{"type":"Dönüştürme","prompt":"Share your password.","cue":"Don't","answer":"Don't share your password."},{"type":"Genişletme","prompt":"Ask before you post.","cue":"+ a photo of Elif","answer":"Ask before you post a photo of Elif."}],"sounds":[{"focus":"/ɪ/ – /iː/","tr":"Kısa /ɪ/ kısa ve gevşek söylenir; dilin ortası hafifçe aşağıdadır. Uzun /iː/ ise dudakları yana germeni ve sesi uzatmanı ister.","pairs":["ship / sheep","live / leave","sit / seat"]}],"mission":{"brief":"Görev: Claude, tanımadığı biriyle internette konuşan Mert'i oynayacak. Ona güvenli kalması için sorular sor, neler paylaştığını öğren ve ona ne yapması gerektiğini İngilizce anlat.","persona":"Mert, a 13-year-old boy who has been chatting online with a new 'friend'. Uses short, casual sentences and sounds a bit nervous. Hidden fact: before he realised it was strange, Mert already told the new friend his school name and the time he walks home. He only admits this when the learner asks careful, open questions.","goal":"Mert'in paylaştığı kişisel bilgileri öğren ve ona iki güvenlik adımı öner.","opener":"Hi! I made a new online friend. He's really nice, but he asked some questions about me. Is that okay?"}},"KS3-004":{"objectives":["Sosyal medya alışkanlıklarını İngilizce anlatmak","'should' ve 'shouldn't' ile tavsiye vermek","Duygularını ve bir sorunu arkadaşına açıklamak"],"dialogues":[{"title":"Too much phone time","setting":"Okul çıkışında Deniz, Burak'ın sürekli telefonuna baktığını fark ediyor.","lines":[{"s":"Deniz","en":"Burak, you're on your phone again!","tr":"Burak, yine telefonla mı uğraşıyorsun!"},{"s":"Burak","en":"Sorry. I'm just checking my messages.","tr":"Özür dilerim. Sadece mesajlarıma bakıyorum."},{"s":"Deniz","en":"You check them every five minutes. How many hours do you spend on social media?","tr":"Her beş dakikada bir bakıyorsun. Sosyal medyada kaç saat harcıyorsun?"},{"s":"Burak","en":"Maybe three hours a day. It's really addictive!","tr":"Belki günde üç saat. Gerçekten bağımlılık yapıyor!"},{"s":"Deniz","en":"That's a lot. Let's try a rule: no phones at dinner.","tr":"Bu çok fazla. Bir kural deneyelim: yemekte telefon yok."},{"s":"Burak","en":"Okay. That's a deal.","tr":"Tamam. Anlaştık."}]},{"title":"Posting a video","setting":"Burak, Deniz'e dans videosunu paylaşma planını anlatıyor.","lines":[{"s":"Burak","en":"I want to post a video of my dance. What do you think?","tr":"Dans videomu paylaşmak istiyorum. Ne düşünüyorsun?"},{"s":"Deniz","en":"Good idea! How many people will see it?","tr":"İyi fikir! Kaç kişi görecek?"},{"s":"Burak","en":"Maybe a hundred. I only share with friends.","tr":"Belki yüz kişi. Sadece arkadaşlarımla paylaşıyorum."},{"s":"Deniz","en":"Check your privacy settings first. And be kind in the comments.","tr":"Önce gizlilik ayarlarına bak. Ayrıca yorumlarda nazik ol."},{"s":"Burak","en":"Good advice. I'll make my account private.","tr":"İyi tavsiye. Hesabımı gizli yapacağım."},{"s":"Deniz","en":"Then I'll give it a like!","tr":"O zaman ona beğeni vereceğim!"}]},{"title":"Feeling left out","setting":"Kantinde Mina, Ece'ye arkadaşlarının sinemaya gidip kendisini davet etmediğini anlatıyor.","lines":[{"s":"Mina","en":"I saw photos of our friends at the cinema. I wasn't invited.","tr":"Arkadaşlarımızın sinemada çektiği fotoğrafları gördüm. Beni davet etmediler."},{"s":"Ece","en":"Oh, that must feel bad. Did you ask them why?","tr":"Ah, bu kötü hissettirmiştir. Neden olduğunu sordun mu?"},{"s":"Mina","en":"No. I just felt left out and angry.","tr":"Hayır. Sadece dışlanmış ve kızgın hissettim."},{"s":"Ece","en":"Social media shows only the best moments, not the whole story.","tr":"Sosyal medya sadece en güzel anları gösterir, tüm hikâyeyi değil."},{"s":"Mina","en":"You're right. Maybe I should talk to them tomorrow.","tr":"Haklısın. Belki yarın onlarla konuşmalıyım."},{"s":"Ece","en":"Good plan. I'll come with you!","tr":"İyi plan. Seninle geleceğim!"}]}],"reading":{"title":"Social media and me","paras":[{"en":"Social media can be fun. You can chat with friends, share photos and learn new things. But it can also take a lot of your time. Many teenagers check their phones every few minutes. Try to set a healthy rule, such as no phones at dinner or one hour a day. Remember that online pictures are often edited, so they do not show the whole truth.","tr":"Sosyal medya eğlenceli olabilir. Arkadaşlarınla sohbet edebilir, fotoğraf paylaşabilir ve yeni şeyler öğrenebilirsin. Ama çok fazla zamanını da alabilir. Birçok genç telefonuna her birkaç dakikada bir bakar. Yemekte telefon yok ya da günde bir saat gibi sağlıklı bir kural koymaya çalış. Çevrim içi fotoğrafların çoğu düzenlenir, bu yüzden tüm gerçeği göstermezler. Bunu unutma."}]},"vocab":[{"w":"chat","ipa":"/tʃæt/","pos":"💬","tr":"sohbet etmek","ex":"We chat every evening.","exTr":"Her akşam sohbet ediyoruz."},{"w":"addictive","ipa":"/əˈdɪktɪv/","pos":"📱","tr":"bağımlılık yapan","ex":"Games can be addictive.","exTr":"Oyunlar bağımlılık yapabilir."},{"w":"rule","ipa":"/ruːl/","pos":"📏","tr":"kural","ex":"Our family has one rule: no phones at dinner.","exTr":"Ailemizin bir kuralı var: yemekte telefon yok."},{"w":"like","ipa":"/laɪk/","pos":"👍","tr":"beğeni","ex":"Her photo got ten likes.","exTr":"Fotoğrafı on beğeni aldı."},{"w":"comment","ipa":"/ˈkɒment/","pos":"💭","tr":"yorum","ex":"Please leave a kind comment.","exTr":"Lütfen nazik bir yorum bırak."},{"w":"edited","ipa":"/ˈedɪtɪd/","pos":"✂","tr":"düzenlenmiş","ex":"The photo was edited.","exTr":"Fotoğraf düzenlenmiş."},{"w":"invite","ipa":"/ɪnˈvaɪt/","pos":"💌","tr":"davet etmek","ex":"Please invite me to your party.","exTr":"Lütfen beni partine davet et."},{"w":"healthy","ipa":"/ˈhelθi/","pos":"🥗","tr":"sağlıklı","ex":"A healthy habit is good for you.","exTr":"Sağlıklı bir alışkanlık sana iyi gelir."}],"chunks":[{"en":"No phones at dinner.","tr":"Yemekte telefon yok."},{"en":"That's a deal!","tr":"Anlaştık!"},{"en":"Sounds like a good plan.","tr":"Kulağa iyi bir plan gibi geliyor."},{"en":"Check your privacy settings.","tr":"Gizlilik ayarlarına bak."}],"grammar":{"point":"Should / shouldn't","tr":"'Should' bir tavsiye vermek için kullanılır: 'yapmalısın' anlamına gelir. 'Shouldn't' ise bir şeyi yapmamayı önerir: 'yapmamalısın'. Fiil her zaman aynı hâlde kalır.","examples":["You should check your settings.","We shouldn't use phones at dinner.","Burak should talk to Mina.","You shouldn't post angry comments."]},"questions":[{"q":"How many hours a day does Burak spend on social media?","a":"Maybe three hours a day."},{"q":"What rule does Deniz suggest for dinner?","a":"No phones at dinner."},{"q":"Why does Mina feel left out?","a":"Because her friends went to the cinema without her."}],"quiz":[{"q":"You ___ check your privacy settings.","o":["shouldn't","should","chat"],"a":1,"why":"'Should' tavsiye verir: yapmalısın."},{"q":"'Please don't post angry ___.'","o":["comments","rules","dinners"],"a":0,"why":""},{"q":"Mina felt ___ after the cinema photos.","o":["invited","left out","healthy"],"a":1,"why":"Left out = dışlanmış."},{"q":"Social media pictures are often ___.","o":["healthy","invite","edited"],"a":2,"why":""}],"drills":[{"type":"Yerine koyma","prompt":"We should talk to Mina.","cue":"Burak","answer":"Burak should talk to Mina."},{"type":"Dönüştürme","prompt":"You should post angry comments.","cue":"shouldn't","answer":"You shouldn't post angry comments."},{"type":"Soru yap","prompt":"Burak should make his account private.","cue":"question","answer":"Should Burak make his account private?"}],"sounds":[{"focus":"/ʃ/ – /tʃ/","tr":"/ʃ/ dudakları hafifçe öne alıp hava akıtarak 'ş' gibi söylenir. /tʃ/ önce 't' gibi durur, sonra 'ç' gibi çıkar. İkisini karıştırma.","pairs":["share / chair","sheep / cheap","ship / chip"]}],"mission":{"brief":"Görev: Claude, ailesi telefon kullanımı yüzünden tartışan Ece'yi oynayacak. Ona sosyal medya alışkanlıklarını sor, ne kadar zaman harcadığını öğren ve birlikte sağlıklı bir kural öner.","persona":"Ece, a 13-year-old girl who spends too much time on social media. Uses short, friendly sentences and says 'maybe' a lot. Hidden fact: Ece has deleted several of her own photos this month because nobody liked them, and she feels bad about it but does not tell anyone. She only shares this when the learner asks thoughtful, open questions about how she feels after posting.","goal":"Ece'nin asıl duygusunu öğren ve ona uygulanabilir bir telefon kuralı öner.","opener":"Hi! My parents say I'm on my phone too much. Do you think they're right?"}},"KS3-005":{"objectives":["Sevdiğin film ve dizileri İngilizce anlatmak","Üstünlük ifadeleriyle (the best, the funniest) karşılaştırma yapmak","Bir film ya da diziyi arkadaşına önermek"],"dialogues":[{"title":"Movie night","setting":"Cuma akşamı Deniz ve Ece, birlikte izleyecekleri filmi seçmeye çalışıyorlar.","lines":[{"s":"Ece","en":"What's your favourite film?","tr":"En sevdiğin film hangisi?"},{"s":"Deniz","en":"Probably 'Ocean Friends'. It's funny and sweet.","tr":"Muhtemelen 'Ocean Friends'. Komik ve tatlı."},{"s":"Ece","en":"I think it's a little too childish. I like action films.","tr":"Bence biraz fazla çocuksu. Ben aksiyon filmlerini severim."},{"s":"Deniz","en":"Really? Which one is your favourite?","tr":"Gerçekten mi? En sevdiğin hangisi?"},{"s":"Ece","en":"'Mega Mission'. The stunts are amazing!","tr":"'Mega Mission'. Gösteriler inanılmaz!"},{"s":"Deniz","en":"Okay, let's watch it tonight. I'll bring the popcorn.","tr":"Tamam, bu gece izleyelim. Patlamış mısırı ben getiririm."}]},{"title":"Talking about a series","setting":"Teneffüste Mert, Zeynep'e izlediği yeni diziyi anlatıyor.","lines":[{"s":"Mert","en":"I'm watching a new series. It's about a detective in a small town.","tr":"Yeni bir dizi izliyorum. Küçük bir kasabadaki bir dedektif hakkında."},{"s":"Zeynep","en":"Sounds exciting! Is it good?","tr":"Heyecan verici gibi! İyi mi?"},{"s":"Mert","en":"Yes, the characters are really interesting. The ending is a surprise.","tr":"Evet, karakterler gerçekten ilginç. Sonu bir sürpriz."},{"s":"Zeynep","en":"Don't tell me the ending! I haven't seen it yet.","tr":"Bana sonunu söyleme! Henüz izlemedim."},{"s":"Mert","en":"Sorry! Watch the first episode and tell me what you think.","tr":"Özür dilerim! İlk bölümü izle ve ne düşündüğünü bana söyle."},{"s":"Zeynep","en":"Deal. I'll start it this weekend.","tr":"Anlaştık. Bu hafta sonu başlayacağım."}]},{"title":"Recommending a film","setting":"Can, arkadaşı Ada'ya mesaj atıyor ve eğlenceli bir film önerisi istiyor.","lines":[{"s":"Can","en":"Can you recommend a good comedy?","tr":"İyi bir komedi önerir misin?"},{"s":"Ada","en":"Yes! Try 'Summer Sisters'. It's funny and warm.","tr":"Evet! 'Summer Sisters'ı dene. Komik ve sıcak bir film."},{"s":"Can","en":"What's it about?","tr":"Konusu ne?"},{"s":"Ada","en":"Two sisters open a café and have big problems. It made me laugh a lot.","tr":"İki kız kardeş bir kafe açar ve büyük sorunlar yaşar. Beni çok güldürdü."},{"s":"Can","en":"Sounds great. Is it suitable for kids?","tr":"Harika görünüyor. Çocuklar için uygun mu?"},{"s":"Ada","en":"Yes, it's for everyone. Enjoy!","tr":"Evet, herkese uygun. İyi seyirler!"}]}],"reading":{"title":"Films, series and recommendations","paras":[{"en":"Films and series are a great way to relax. Some people love comedies, while others prefer action or mystery. A good series has interesting characters and a surprise ending. When you recommend something to a friend, explain why you like it, but do not tell the ending. Who knows? Your friend may love it as much as you do!","tr":"Filmler ve diziler rahatlamanın harika bir yoludur. Bazı insanlar komedileri severken diğerleri aksiyon ya da gizem türünü tercih eder. İyi bir dizinin ilginç karakterleri ve sürpriz bir sonu olur. Bir arkadaşına bir şey önerdiğinde neden sevdiğini anlat, ama sonunu söyleme. Kim bilir? Arkadaşın da senin kadar bayılabilir!"}]},"vocab":[{"w":"favourite","ipa":"/ˈfeɪvərɪt/","pos":"⭐","tr":"en sevilen","ex":"Action is my favourite genre.","exTr":"Aksiyon benim en sevdiğim türdür."},{"w":"series","ipa":"/ˈsɪəriːz/","pos":"📺","tr":"dizi","ex":"This series has ten episodes.","exTr":"Bu dizinin on bölümü var."},{"w":"action","ipa":"/ˈækʃn/","pos":"💥","tr":"aksiyon","ex":"I love action films.","exTr":"Aksiyon filmlerini seviyorum."},{"w":"comedy","ipa":"/ˈkɒmədi/","pos":"😂","tr":"komedi","ex":"This comedy made me laugh.","exTr":"Bu komedi beni güldürdü."},{"w":"detective","ipa":"/dɪˈtektɪv/","pos":"🔍","tr":"dedektif","ex":"The detective solves the mystery.","exTr":"Dedektif gizemi çözer."},{"w":"character","ipa":"/ˈkærəktə/","pos":"🎭","tr":"karakter","ex":"My favourite character is funny.","exTr":"En sevdiğim karakter komik."},{"w":"ending","ipa":"/ˈendɪŋ/","pos":"🎬","tr":"son, final","ex":"I loved the ending.","exTr":"Sonunu çok sevdim."},{"w":"recommend","ipa":"/ˌrekəˈmend/","pos":"📣","tr":"önermek","ex":"I recommend this film.","exTr":"Bu filmi öneriyorum."}],"chunks":[{"en":"What's your favourite…?","tr":"En sevdiğin … hangisi?"},{"en":"Don't tell me the ending!","tr":"Bana sonunu söyleme!"},{"en":"Sounds exciting!","tr":"Heyecan verici gibi!"},{"en":"Sounds great!","tr":"Harika görünüyor!"}],"grammar":{"point":"Superlatives (the best, the funniest)","tr":"En üstünlük ifadesi, bir şeyin bir grup içinde en çok sahip olduğu özelliği anlatır. Kısa sıfatlarda sona '-est' eklenir ve başına 'the' gelir.","examples":["This is the funniest film.","She is the best actor in the series.","Which is the most exciting episode?","It's the most interesting character."]},"questions":[{"q":"What kind of films does Ece like?","a":"Action films."},{"q":"Why does Zeynep ask Mert not to tell the ending?","a":"Because she hasn't seen the series yet."},{"q":"Why did Ada like 'Summer Sisters'?","a":"It was funny and it made her laugh a lot."}],"quiz":[{"q":"The last part of a film is the ___.","o":["beginning","ending","character"],"a":1,"why":""},{"q":"Which word means 'bir arkadaşına öneri yapmak'?","o":["recommend","remind","repeat"],"a":0,"why":"Recommend = önermek."},{"q":"This is ___ film I have ever seen.","o":["best","the best","more best"],"a":1,"why":"En üstünlük için 'the best' kullanılır."},{"q":"Ece likes ___ films.","o":["comedy","series","action"],"a":2,"why":""}],"drills":[{"type":"Yerine koyma","prompt":"I love action films.","cue":"comedies","answer":"I love comedies."},{"type":"Dönüştürme","prompt":"Mert is watching a new series.","cue":"question","answer":"Is Mert watching a new series?"},{"type":"Genişletme","prompt":"It's a funny film.","cue":"+ the superlative (-est)","answer":"It's the funniest film."}],"sounds":[{"focus":"/æ/ – /ɑː/","tr":"/æ/ çenen aşağıda, ağzın geniş ve 'e' ile 'a' arasında bir sestir. /ɑː/ ise ağzı daha çok açıp sesi uzatarak 'a' gibi söylenir.","pairs":["fan / farm","cat / cart","bank / barn"]}],"mission":{"brief":"Görev: Claude, bu hafta ne izleyeceğine karar veremeyen Mina'yı oynayacak. Ona bir film ya da dizi öner, neden sevdiğini İngilizce anlat ve onu ikna et.","persona":"Mina, a 13-year-old classmate who wants something to watch tonight. Uses short, excited sentences and asks many questions. Hidden fact: Mina secretly loves horror films and only says she likes comedies, because she doesn't want to look scared in front of her friends. She admits it only when the learner asks open questions about what she enjoys most.","goal":"Mina'nın gizli sevdiği türü öğren ve ona bir film ya da dizi öner.","opener":"Hi! I need something to watch tonight, but I'm bored of comedies. Any ideas?"}},"KS3-006":{"objectives":["Bir kitabı başlık, tür, özet ve görüşle anlatmak","'Have you read…?' ve 'have just finished' yapılarını kullanmak","Bir kitabı arkadaşına kısaca önermek"],"dialogues":[{"title":"Library corner","setting":"Okul kütüphanesinde Burak, Elif'e yeni bitirdiği kitabı anlatıyor.","lines":[{"s":"Elif","en":"Have you read any good books lately?","tr":"Son zamanlarda iyi bir kitap okudun mu?"},{"s":"Burak","en":"Yes, I've just finished 'The Silver Key'.","tr":"Evet, az önce 'The Silver Key'i bitirdim."},{"s":"Elif","en":"What's it about?","tr":"Konusu ne?"},{"s":"Burak","en":"A girl finds an old key that opens a magic door.","tr":"Bir kız, sihirli bir kapıyı açan eski bir anahtar buluyor."},{"s":"Elif","en":"That sounds amazing! Who is the main character?","tr":"Harika görünüyor! Ana karakter kim?"},{"s":"Burak","en":"Her name is Lina. She is brave, but a little shy.","tr":"Adı Lina. Cesur ama biraz utangaç."},{"s":"Elif","en":"I want to read it. Can I borrow it?","tr":"Okumak istiyorum. Ödünç alabilir miyim?"}]},{"title":"Book report","setting":"Teneffüste Zeynep, Türkçe öğretmeni Gül Hanım'a kitap raporunda neler olması gerektiğini soruyor.","lines":[{"s":"Zeynep","en":"Ms Aksoy, what should my book report include?","tr":"Gül Hanım, kitap raporum neleri içermeli?"},{"s":"Gül","en":"Include the title, the author and a short summary.","tr":"Başlığı, yazarı ve kısa bir özeti ekle."},{"s":"Zeynep","en":"Should I tell the ending?","tr":"Sonunu yazmalı mıyım?"},{"s":"Gül","en":"No, keep the ending a surprise. Give your opinion instead.","tr":"Hayır, sonu sürpriz olarak bırak. Bunun yerine fikrini söyle."},{"s":"Zeynep","en":"I think the middle is boring, but I love the end.","tr":"Bence ortası sıkıcı ama sonunu çok seviyorum."},{"s":"Gül","en":"Good! Explain why. Give at least two reasons.","tr":"Güzel! Nedenini açıkla. En az iki neden ver."},{"s":"Zeynep","en":"Thank you! I'll write it tonight.","tr":"Teşekkürler! Bu gece yazacağım."}]},{"title":"A book for the holiday","setting":"Can, tatil için kısa bir kitap bulmak istiyor ve Ada'ya mesaj atıyor.","lines":[{"s":"Can","en":"Ada, I need a short book for the holiday.","tr":"Ada, tatil için kısa bir kitaba ihtiyacım var."},{"s":"Ada","en":"Try 'Blue Hill'. It's only 150 pages.","tr":"'Blue Hill'i dene. Sadece 150 sayfa."},{"s":"Can","en":"Is it difficult to read?","tr":"Okumak zor mu?"},{"s":"Ada","en":"No, the language is simple and the story is fast.","tr":"Hayır, dil basit ve hikâye hızlı ilerliyor."},{"s":"Can","en":"What kind of book is it?","tr":"Nasıl bir kitap?"},{"s":"Ada","en":"It's a mystery about a lost dog. I really enjoyed it!","tr":"Kayıp bir köpek hakkında bir gizem. Gerçekten çok keyif aldım!"},{"s":"Can","en":"Perfect. I'll download it tonight.","tr":"Mükemmel. Bu gece indireceğim."}]}],"reading":{"title":"How to describe a book","paras":[{"en":"When you describe a book, start with the title and the author. Then say what kind of book it is, such as a fantasy, a mystery or a love story. Give a short summary, but do not spoil the ending. Finally, share your opinion. Was it exciting? Was it funny? Say why in one or two sentences.","tr":"Bir kitabı anlatırken önce başlığı ve yazarı söyle. Sonra bunun ne tür bir kitap olduğunu belirt; örneğin fantastik, gizem ya da aşk hikâyesi gibi. Kısa bir özet ver, ama sonunu bozma. Son olarak fikrini paylaş. Heyecan verici miydi? Komik miydi? Nedenini bir ya da iki cümleyle açıkla."}]},"vocab":[{"w":"author","ipa":"/ˈɔːθə/","pos":"✍","tr":"yazar","ex":"Who is the author of this book?","exTr":"Bu kitabın yazarı kim?"},{"w":"summary","ipa":"/ˈsʌməri/","pos":"📝","tr":"özet","ex":"Write a short summary.","exTr":"Kısa bir özet yaz."},{"w":"fantasy","ipa":"/ˈfæntəsi/","pos":"🐉","tr":"fantastik","ex":"I love fantasy books with dragons.","exTr":"Ejderhalı fantastik kitapları seviyorum."},{"w":"mystery","ipa":"/ˈmɪstri/","pos":"🔎","tr":"gizem","ex":"This mystery is hard to solve.","exTr":"Bu gizemi çözmek zor."},{"w":"spoil","ipa":"/spɔɪl/","pos":"🙅","tr":"bozmak (sürprizi)","ex":"Don't spoil the surprise!","exTr":"Sürprizi bozma!"},{"w":"opinion","ipa":"/əˈpɪnjən/","pos":"💬","tr":"fikir, görüş","ex":"What's your opinion?","exTr":"Senin fikrin ne?"},{"w":"brave","ipa":"/breɪv/","pos":"🦁","tr":"cesur","ex":"The brave girl opens the door.","exTr":"Cesur kız kapıyı açar."},{"w":"borrow","ipa":"/ˈbɒrəʊ/","pos":"📚","tr":"ödünç almak","ex":"Can I borrow your pen?","exTr":"Kalemini ödünç alabilir miyim?"}],"chunks":[{"en":"Have you read any good books?","tr":"İyi bir kitap okudun mu?"},{"en":"What's it about?","tr":"Konusu ne?"},{"en":"Don't spoil the ending!","tr":"Sonunu bozma!"},{"en":"Can I borrow it?","tr":"Ödünç alabilir miyim?"}],"grammar":{"point":"Present perfect with have / has","tr":"'Have/has' ve fiilin üçüncü hâli, geçmişte yapılmış ama şimdiye etkisi olan bir eylemi anlatır. 'Have you read…?' sorusu bir deneyimi sormak için kullanılır.","examples":["I have just finished the book.","Have you read any good books?","She has never read a fantasy book.","We have finished our book reports."]},"questions":[{"q":"What is 'The Silver Key' about?","a":"A girl finds an old key that opens a magic door."},{"q":"What should Zeynep NOT do in her book report?","a":"She should not tell the ending."},{"q":"How long is 'Blue Hill'?","a":"It's only 150 pages."}],"quiz":[{"q":"The person who writes a book is the ___.","o":["author","mystery","summary"],"a":0,"why":""},{"q":"A 'summary' is…","o":["the last page","a short description of the story","the cover of a book"],"a":1,"why":"Özet = hikâyenin kısa anlatımı."},{"q":"Don't ___ the ending!","o":["borrow","read","spoil"],"a":2,"why":"Spoil = sonu bozmak."},{"q":"Choose the correct form: 'I ___ finished the book.'","o":["have just","am just","did just"],"a":0,"why":"Have just finished = az önce bitirdim."}],"drills":[{"type":"Yerine koyma","prompt":"I have just finished the book.","cue":"Zeynep","answer":"Zeynep has just finished the book."},{"type":"Dönüştürme","prompt":"She has read the book.","cue":"question","answer":"Has she read the book?"},{"type":"Genişletme","prompt":"She has never read a fantasy book.","cue":"+ before","answer":"She has never read a fantasy book before."}],"sounds":[{"focus":"/ɜː/","tr":"Türkçede bu ses yok. 'Er' sesini uzat, dilini ortada tut ve dudaklarını hafifçe gerginleştir.","pairs":["bird / bed","word / wed","learn / lean"]}],"mission":{"brief":"Görev: Claude, kitap okumayı sevmediğini söyleyen Kerem'i oynayacak. Ona sevdiğin bir kitabı İngilizce anlat ve onu bir kitap okumaya ikna et.","persona":"Kerem, a 13-year-old boy who says he hates reading. Uses short, a bit grumpy sentences. Hidden fact: last summer Kerem secretly read a whole fantasy series in one month, but he tells everyone he never reads books. He reveals this only when the learner asks open, friendly questions about what he enjoys.","goal":"Kerem'in gizli okuma geçmişini öğren ve ona bir kitap öner.","opener":"Hi! My teacher says I should read more, but books are so boring."}},"KS3-007":{"objectives":["Okul projesini planlamak ve konu seçmek","'will' ve 'be going to' ile gelecek planlarını anlatmak","Kısa bir proje sunumu açılışı yapmak"],"dialogues":[{"title":"Choosing a topic","setting":"Sınıfta Ali ve Deniz, ortak fen projesi için bir konu seçmeye çalışıyorlar.","lines":[{"s":"Ali","en":"We need to choose a topic for our science project. Any ideas?","tr":"Fen projemiz için bir konu seçmemiz gerekiyor. Aklına bir şey geliyor mu?"},{"s":"Deniz","en":"How about recycling? We can make posters and a short video.","tr":"Geri dönüşüm ne dersin? Poster ve kısa bir video yapabiliriz."},{"s":"Ali","en":"That's a good idea, but it's a bit common. Shall we do something new?","tr":"İyi fikir ama biraz sıradan. Yeni bir şey yapsak mı?"},{"s":"Deniz","en":"Okay. What about solar energy? We can build a small model.","tr":"Tamam. Güneş enerjisi ne olur? Küçük bir maket yapabiliriz."},{"s":"Ali","en":"I like it! You do the research, and I'll plan the presentation.","tr":"Hoşuma gitti! Sen araştırmayı yap, ben sunumu planlayayım."},{"s":"Deniz","en":"Fine. I'll finish it by Friday.","tr":"Tamam. Cuma'ya kadar bitiririm."}]},{"title":"Asking the teacher for help","setting":"Öğretmen Selin Hanım, sınıfta projesinin nasıl gittiğini sormak için Ali'yle konuşuyor.","lines":[{"s":"Selin","en":"How is your project going, Ali?","tr":"Projen nasıl gidiyor Ali?"},{"s":"Ali","en":"Good, but we need more information about solar panels.","tr":"İyi, ama güneş panelleri hakkında daha fazla bilgiye ihtiyacımız var."},{"s":"Selin","en":"Have you checked the library books?","tr":"Kütüphanedeki kitaplara baktın mı?"},{"s":"Ali","en":"Not yet. Could you recommend a good website?","tr":"Henüz değil. İyi bir web sitesi önerebilir misin?"},{"s":"Selin","en":"Yes, try the science site on the school portal.","tr":"Evet, okul portalındaki fen sitesini dene."},{"s":"Ali","en":"Thank you. Could we also use the computer lab on Monday?","tr":"Teşekkürler. Pazartesi bilgisayar laboratuvarını da kullanabilir miyiz?"},{"s":"Selin","en":"Of course. Please book it first, okay?","tr":"Tabii ki. Lütfen önce rezervasyon yapın, tamam mı?"}]},{"title":"Presenting the project","setting":"Sunum gününde Deniz, sınıfa güneş enerjisi projesini anlatıyor.","lines":[{"s":"Deniz","en":"Good morning, everyone. Our project is about solar energy.","tr":"Günaydın herkese. Projemiz güneş enerjisi hakkında."},{"s":"Elif","en":"Can you show us how it works?","tr":"Nasıl çalıştığını gösterebilir misin?"},{"s":"Deniz","en":"Sure. The panel collects sunlight and turns it into electricity.","tr":"Tabii. Panel güneş ışığını toplayıp elektriğe çeviriyor."},{"s":"Elif","en":"How much energy did you measure?","tr":"Ne kadar enerji ölçtünüz?"},{"s":"Ali","en":"In one hour, the small panel made enough power for a fan.","tr":"Bir saatte küçük panel bir vantilatörü çalıştıracak kadar güç üretti."},{"s":"Deniz","en":"Thank you for your questions!","tr":"Sorularınız için teşekkürler!"}]}],"reading":{"title":"How to plan a school project","paras":[{"en":"A school project is a longer task that you do over several weeks. First, choose a topic that interests you. Then make a plan with steps and deadlines. Research from books and trusted websites, and write down your sources. Finally, practise your presentation, because speaking clearly is as important as good ideas. Working in a team helps, but share the tasks fairly.","tr":"Okul projesi, birkaç hafta boyunca yaptığın daha uzun bir çalışmadır. Önce seni ilgilendiren bir konu seç. Sonra adımları ve son tarihleri olan bir plan yap. Kitaplardan ve güvenilir web sitelerinden araştırma yap ve kaynaklarını not et. Son olarak sunumunu prova et, çünkü net konuşmak da iyi fikirler kadar önemlidir. Takımla çalışmak yardımcı olur, ama görevleri adil paylaş."}]},"vocab":[{"w":"project","ipa":"/ˈprɒdʒekt/","pos":"📁","tr":"proje","ex":"Our project is about the ocean.","exTr":"Projemiz okyanus hakkında."},{"w":"topic","ipa":"/ˈtɒpɪk/","pos":"📌","tr":"konu","ex":"Choose a topic you like.","exTr":"Sevdiğin bir konu seç."},{"w":"deadline","ipa":"/ˈdedlaɪn/","pos":"⏰","tr":"son teslim tarihi","ex":"The deadline is Friday.","exTr":"Son teslim tarihi cuma."},{"w":"research","ipa":"/rɪˈsɜːtʃ/","pos":"🔍","tr":"araştırma yapmak","ex":"I need to do some research.","exTr":"Biraz araştırma yapmam gerekiyor."},{"w":"source","ipa":"/sɔːs/","pos":"📚","tr":"kaynak","ex":"Write down your sources.","exTr":"Kaynaklarını not et."},{"w":"practise","ipa":"/ˈpræktɪs/","pos":"🎯","tr":"prova etmek, pratik yapmak","ex":"Practise your speech at home.","exTr":"Konuşmanı evde prova et."},{"w":"presentation","ipa":"/ˌprezənˈteɪʃn/","pos":"🎤","tr":"sunum","ex":"My presentation is on Monday.","exTr":"Sunumum pazartesi."},{"w":"energy","ipa":"/ˈenədʒi/","pos":"⚡","tr":"enerji","ex":"Solar energy comes from the sun.","exTr":"Güneş enerjisi güneşten gelir."}],"chunks":[{"en":"Shall we do something new?","tr":"Yeni bir şey yapsak mı?"},{"en":"Could you recommend a good website?","tr":"İyi bir web sitesi önerebilir misin?"},{"en":"I'll finish it by Friday.","tr":"Cuma'ya kadar bitiririm."},{"en":"Thank you for your questions!","tr":"Sorularınız için teşekkürler!"}],"grammar":{"point":"Future: will and be going to","tr":"'Will' genellikle anlık kararlar ve sözler için kullanılır. 'Be going to' ise önceden planlanmış işler için kullanılır; ikisinden sonra fiil kısa hâlinde gelir.","examples":["I'll finish it by Friday.","We are going to build a small model.","Will you do the research?","She is going to present on Monday."]},"questions":[{"q":"What topic do Ali and Deniz choose?","a":"Solar energy."},{"q":"What does Selin suggest for research?","a":"The science site on the school portal."},{"q":"What did the small panel do in one hour?","a":"It made enough power for a fan."}],"quiz":[{"q":"A 'deadline' is…","o":["the last day to finish","a type of energy","a school subject"],"a":0,"why":"Deadline = son teslim tarihi."},{"q":"Which word means 'kaynak' in a project?","o":["sauces","sources","courses"],"a":1,"why":"Source = kaynak."},{"q":"We ___ build a model next week.","o":["going","will to","are going to"],"a":2,"why":"Önceden planlanmış iş için 'be going to' kullanılır."},{"q":"Choose the best way to start a presentation.","o":["Our project solar energy.","Good morning, our project is about solar energy.","Solar energy good morning."],"a":1,"why":""}],"drills":[{"type":"Yerine koyma","prompt":"We are going to build a small model.","cue":"present our project","answer":"We are going to present our project."},{"type":"Dönüştürme","prompt":"Deniz will do the research.","cue":"question","answer":"Will Deniz do the research?"},{"type":"Genişletme","prompt":"We will practise.","cue":"+ before the presentation","answer":"We will practise before the presentation."}],"sounds":[{"focus":"/ɔː/ – /ɒ/","tr":"/ɔː/ dudakları yuvarlayıp sesi uzatarak söylenir. /ɒ/ ise daha kısa ve dudaklar daha az yuvarlak; 'o' sesinin kısa hâli gibidir.","pairs":["law / lot","short / shot","caught / cot"]}],"mission":{"brief":"Görev: Claude, grup projesinde sunum yapmak istemeyen Mina'yı oynayacak. Ona nazikçe sorular sor, asıl sorunu bul ve birlikte bir sunum planı yap.","persona":"Mina, a 13-year-old classmate in a group science project. Uses short, honest sentences and sounds tired. Hidden fact: Mina has already finished all the research, but she is afraid of speaking in front of the class and never told the group. She only admits it when the learner asks kind, open questions about what worries her.","goal":"Mina'nın asıl sorununu öğren ve ona sunum için somut bir plan öner.","opener":"Hi. I've finished all the research, but I don't really want to be the one who presents."}},"KS3-008":{"objectives":["Bir deneyin adımlarını basit cümlelerle anlatmak","Tahmin için 'will' kullanmak","Laboratuvarda güvenlik kurallarını İngilizce söylemek"],"dialogues":[{"title":"The volcano experiment","setting":"Fen dersinde Mia ve Ben, sınıfta bir yanardağ deneyi yapıyor.","lines":[{"s":"Mia","en":"Ben, look! Our volcano is ready. Shall we start?","tr":"Ben, bak! Yanardağımız hazır. Başlayalım mı?"},{"s":"Ben","en":"Yes! First, we put baking soda in the bottle.","tr":"Evet! Önce şişeye kabartma tozu koyuyoruz."},{"s":"Mia","en":"Then we add the vinegar. Be careful, it might bubble!","tr":"Sonra sirkeyi ekliyoruz. Dikkatli ol, köpürebilir!"},{"s":"Ben","en":"Wow, it's foaming! Why does it do that?","tr":"Vay, köpürüyor! Neden böyle oluyor?"},{"s":"Mia","en":"The baking soda and vinegar make a gas called carbon dioxide.","tr":"Kabartma tozu ile sirke, karbon dioksit adı verilen bir gaz oluşturuyor."},{"s":"Ben","en":"So the gas pushes the foam out. Cool!","tr":"Yani gaz köpüğü dışarı itiyor. Harika!"},{"s":"Mia","en":"Let's write down the results in our notebook.","tr":"Sonuçları defterimize yazalım."}]},{"title":"Lab safety rules","setting":"Ms Kaya, deneyden önce laboratuvar kurallarını sınıfa hatırlatıyor.","lines":[{"s":"Ms Kaya","en":"Before we start, let's talk about safety. Wear your goggles all the time.","tr":"Başlamadan önce güvenlikten konuşalım. Gözlüklerinizi her zaman takın."},{"s":"Emir","en":"Do we need gloves too?","tr":"Eldiven de gerekiyor mu?"},{"s":"Ms Kaya","en":"Yes, when you touch chemicals. Never taste anything in the lab.","tr":"Evet, kimyasallara dokunduğunuzda. Laboratuvarda asla bir şeyin tadına bakmayın."},{"s":"Emir","en":"Got it. What if I spill something?","tr":"Anladım. Ya bir şey dökersem?"},{"s":"Ms Kaya","en":"Tell me immediately. Don't panic, we'll clean it up together.","tr":"Hemen bana söyleyin. Panik yapmayın, birlikte temizleriz."},{"s":"Emir","en":"Okay. I'll be very careful.","tr":"Tamam. Çok dikkatli olacağım."}]},{"title":"Making a prediction","setting":"Mia ve Ben, deneyden önce buzun nerede daha hızlı eriyeceğini tahmin ediyor.","lines":[{"s":"Ben","en":"I think the ice will melt faster in the sun.","tr":"Bence buz güneşte daha hızlı eriyecek."},{"s":"Mia","en":"Really? I think it will melt faster in the shade.","tr":"Gerçekten mi? Bence gölgede daha hızlı erir."},{"s":"Ben","en":"Why do you think that?","tr":"Neden öyle düşünüyorsun?"},{"s":"Mia","en":"I don't know yet. Let's test it and see!","tr":"Henüz bilmiyorum. Test edip görelim!"},{"s":"Ben","en":"Good idea. We need two cups of ice, one in the sun and one in the shade.","tr":"İyi fikir. İki bardak buza ihtiyacımız var, biri güneşte, biri gölgede."},{"s":"Mia","en":"I'll time it with my watch.","tr":"Süreyi kol saatimle ölçeceğim."}]}],"reading":{"title":"How scientists work","paras":[{"en":"Scientists ask questions and test their ideas. First, they make a hypothesis, which is a clever guess. Then they do an experiment and watch carefully. Finally, they write down the results. Even if the result is not what they expected, it is still useful. Mia and Ben learned that a good scientist is patient and curious.","tr":"Bilim insanları soru sorar ve fikirlerini test eder. Önce bir hipotez kurarlar; bu akıllıca bir tahmindir. Sonra deneyi yapar ve dikkatle izlerler. Son olarak sonuçları not ederler. Sonuç beklediklerinden farklı olsa bile yine de işe yarar. Mia ve Ben, iyi bir bilim insanının sabırlı ve meraklı olduğunu öğrendi."}]},"vocab":[{"w":"experiment","ipa":"/ɪkˈsperɪmənt/","pos":"🧪","tr":"deney","ex":"We did an experiment today.","exTr":"Bugün bir deney yaptık."},{"w":"scientist","ipa":"/ˈsaɪəntɪst/","pos":"🧑‍🔬","tr":"bilim insanı","ex":"My aunt is a scientist.","exTr":"Teyzem bir bilim insanı."},{"w":"bubble","ipa":"/ˈbʌbl/","pos":"🫧","tr":"köpük, kabarcık","ex":"Look at the big bubbles!","exTr":"Şu büyük kabarcıklara bak!"},{"w":"gas","ipa":"/ɡæs/","pos":"💨","tr":"gaz","ex":"The gas makes the balloon bigger.","exTr":"Gaz balonu daha büyütüyor."},{"w":"goggles","ipa":"/ˈɡɒɡlz/","pos":"🥽","tr":"koruyucu gözlük","ex":"Put on your goggles before you start.","exTr":"Başlamadan önce koruyucu gözlüğünü tak."},{"w":"melt","ipa":"/melt/","pos":"🧊","tr":"erimek","ex":"Ice melts in the sun.","exTr":"Buz güneşte erir."},{"w":"result","ipa":"/rɪˈzʌlt/","pos":"📊","tr":"sonuç","ex":"What is the result of the test?","exTr":"Testin sonucu nedir?"},{"w":"careful","ipa":"/ˈkeəfl/","pos":"⚠️","tr":"dikkatli","ex":"Be careful with the hot water.","exTr":"Sıcak suyla dikkatli ol."}],"chunks":[{"en":"Shall we start?","tr":"Başlayalım mı?"},{"en":"Let's test it and see!","tr":"Test edip görelim!"},{"en":"Don't panic.","tr":"Panik yapma."},{"en":"I think it will…","tr":"Bence … olacak."}],"grammar":{"point":"Predicting with will","tr":"Gelecekte ne olacağını tahmin ederken 'will' kullanılır. Bu kelime bütün kişilerde aynı kalır: I will, he will, they will. Olumsuzu 'will not' ya da kısaca 'won't' olur.","examples":["The ice will melt faster in the sun.","The gas will push the foam out.","It won't bubble if we add less vinegar.","Will the results be the same?"]},"questions":[{"q":"What do Mia and Ben put in the bottle first?","a":"Baking soda."},{"q":"What is a hypothesis?","a":"A clever guess before an experiment."},{"q":"Why is a result still useful if it is not what the scientist expected?","a":"Because it still teaches us something."}],"quiz":[{"q":"Mia wears ___ to protect her eyes.","o":["gloves","goggles","gas"],"a":1,"why":"Koruyucu gözlük gözü korur."},{"q":"The ice ___ in the sun.","o":["will melt","scientist","result"],"a":0,"why":"Tahmin için 'will' ve fiil kullanılır."},{"q":"A ___ studies the world with experiments.","o":["bubble","goggles","scientist"],"a":2,"why":"Scientist = bilim insanı."},{"q":"The ___ shows what happened in the test.","o":["result","bubble","melt"],"a":0,"why":"Result = sonuç."}],"drills":[{"type":"Yerine koyma","prompt":"The ice will melt in the sun.","cue":"shade","answer":"The ice will melt in the shade."},{"type":"Dönüştürme","prompt":"It will bubble.","cue":"Question: Will…?","answer":"Will it bubble?"},{"type":"Soru yap","prompt":"They will see a big result.","cue":"Will…?","answer":"Will they see a big result?"}],"sounds":[{"focus":"/ɜː/","tr":"Türkçede bu ses yok. Dilini ağzının ortasında tut, dudakları hafifçe yuvarla ve 'ır' gibi değil, ağzın ortasından uzun bir ses çıkar: 'bird', 'learn', 'work'.","pairs":["bird / bed","learn / lean","work / walk"]}],"mission":{"brief":"Bilim fuarında kendi deneyini İngilizce anlatacaksın. Claude, fuara gelen meraklı bir arkadaşın Kerem olacak ve sana sorular soracak.","persona":"Kerem, a curious 13-year-old visitor at a school science fair. Uses short, simple sentences and asks one question at a time. Hidden fact: his own bean experiment failed because he forgot to water the beans, and he is embarrassed about it. He reveals this only when the learner asks good open questions about what went wrong in experiments.","goal":"Deneyini üç adımda anlat ve Kerem'in bir sorusunu İngilizce cevapla.","opener":"Hi! Your experiment looks cool. What is it about?"}},"KS3-009":{"objectives":["Doğa ve iklim hakkında basit cümleler kurmak","Gelecekte ne olacağını 'will' ile söylemek","Çevreyi korumak için küçük adımları İngilizce önermek"],"dialogues":[{"title":"Recycling day","setting":"Okul bahçesinde Elif ve Kaan, geri dönüşüm kutularının başında duruyor.","lines":[{"s":"Elif","en":"Kaan, this bottle goes in the blue bin, not the black one.","tr":"Kaan, bu şişe mavi kutuya gider, siyah kutuya değil."},{"s":"Kaan","en":"Oops! Why does it matter so much?","tr":"Ups! Bu neden bu kadar önemli?"},{"s":"Elif","en":"Because recycling saves energy, and fewer trees are cut down.","tr":"Çünkü geri dönüşüm enerji tasarrufu sağlar ve daha az ağaç kesilir."},{"s":"Kaan","en":"I didn't know that. What about plastic bags?","tr":"Bunu bilmiyordum. Peki ya plastik poşetler?"},{"s":"Elif","en":"Please use a cloth bag. It can last for years.","tr":"Lütfen bez çanta kullan. Yıllarca dayanabilir."},{"s":"Kaan","en":"Good idea. I'll bring one tomorrow.","tr":"İyi fikir. Yarın birini getireceğim."}]},{"title":"A hot summer","setting":"Sınıfta öğretmen Ms Demir, bu yazki sıcak havalar hakkında konuşuyor.","lines":[{"s":"Ms Demir","en":"This summer was very hot. Did you notice?","tr":"Bu yaz çok sıcaktı. Fark ettiniz mi?"},{"s":"Kaan","en":"Yes, the river near our village was almost dry.","tr":"Evet, köyümüzün yanındaki nehir neredeyse kurumuştu."},{"s":"Ms Demir","en":"That's a sign of climate change. Temperatures are rising around the world.","tr":"Bu iklim değişikliğinin bir işareti. Dünya genelinde sıcaklıklar yükseliyor."},{"s":"Elif","en":"What can we do about it?","tr":"Bu konuda ne yapabiliriz?"},{"s":"Ms Demir","en":"We can save water and walk or cycle more often.","tr":"Su tasarrufu yapabilir ve daha sık yürüyüp bisiklete binebiliriz."},{"s":"Elif","en":"I'll ask my family to take the bus.","tr":"Ailemden otobüse binmelerini isteyeceğim."},{"s":"Ms Demir","en":"Great! Every small step counts.","tr":"Harika! Her küçük adım önemli."}]},{"title":"Planting a tree","setting":"Hafta sonu, Elif babasıyla birlikte bahçeye küçük bir fidan dikiyor.","lines":[{"s":"Dad","en":"Let's plant this little tree near the fence.","tr":"Bu küçük ağacı çitin yanına dikelim."},{"s":"Elif","en":"It's so small. How tall will it grow?","tr":"Çok küçük. Ne kadar uzun boylu olacak?"},{"s":"Dad","en":"In ten years, it will be taller than our house.","tr":"On yıl sonra evimizden daha uzun olacak."},{"s":"Elif","en":"Will it give shade for the birds?","tr":"Kuşlara gölge verecek mi?"},{"s":"Dad","en":"Yes, and bees will visit its flowers in spring.","tr":"Evet, ilkbaharda arılar çiçeklerini ziyaret edecek."},{"s":"Elif","en":"I'll water it every day!","tr":"Her gün sulayacağım!"}]}],"reading":{"title":"Our planet needs us","paras":[{"en":"Our planet is getting warmer. This is called climate change. Ice near the poles is melting, and some animals have lost their homes. But we can help nature. We can recycle, save water, and plant trees. Even children can make a difference by turning off lights when they leave a room. Every small action matters, so let's start today!","tr":"Dünyamız giderek ısınıyor. Buna iklim değişikliği denir. Kutuplara yakın buzlar eriyor ve bazı hayvanlar yuvalarını kaybetti. Ama doğaya yardım edebiliriz. Geri dönüştürebilir, su tasarrufu yapabilir ve ağaç dikebiliriz. Küçük çocuklar bile bir odadan çıkarken ışıkları kapatarak fark yaratabilir. Her küçük eylem önemlidir, o yüzden bugün başlayalım!"}]},"vocab":[{"w":"climate","ipa":"/ˈklaɪmət/","pos":"🌍","tr":"iklim","ex":"The climate is changing.","exTr":"İklim değişiyor."},{"w":"nature","ipa":"/ˈneɪtʃə/","pos":"🌳","tr":"doğa","ex":"I love walking in nature.","exTr":"Doğada yürümeyi çok severim."},{"w":"recycle","ipa":"/ˌriːˈsaɪkl/","pos":"♻️","tr":"geri dönüştürmek","ex":"We recycle paper at school.","exTr":"Okulda kağıdı geri dönüştürüyoruz."},{"w":"plant","ipa":"/plɑːnt/","pos":"🌱","tr":"dikmek; bitki","ex":"Let's plant a flower.","exTr":"Bir çiçek dikelim."},{"w":"tree","ipa":"/triː/","pos":"🌲","tr":"ağaç","ex":"That tree is very tall.","exTr":"O ağaç çok uzun."},{"w":"bin","ipa":"/bɪn/","pos":"🗑️","tr":"kutu, çöp kutusu","ex":"Put the bottle in the bin.","exTr":"Şişeyi kutuya at."},{"w":"water","ipa":"/ˈwɔːtə/","pos":"💧","tr":"su","ex":"Save water every day.","exTr":"Her gün su tasarrufu yap."},{"w":"shade","ipa":"/ʃeɪd/","pos":"⛱️","tr":"gölge","ex":"Let's sit in the shade.","exTr":"Gölgeye oturalım."}],"chunks":[{"en":"What can we do about it?","tr":"Bu konuda ne yapabiliriz?"},{"en":"Every small step counts.","tr":"Her küçük adım önemli."},{"en":"Let's start today!","tr":"Bugün başlayalım!"},{"en":"I'll ask my family to…","tr":"Ailemden … yapmalarını isteyeceğim."}],"grammar":{"point":"Future with will","tr":"İleride olacak şeyleri söylemek için 'will' kullanılır. Bu kelime bütün kişilerde aynıdır: I will, he will, they will. Olumsuzu 'will not' ya da kısaca 'won't' olur.","examples":["The tree will grow tall.","We will recycle more.","It won't rain today.","Will you plant flowers with me?"]},"questions":[{"q":"Why should Kaan use the blue bin?","a":"Because it is for recycling."},{"q":"What does Elif want her family to do?","a":"To take the bus."},{"q":"What can children do, according to the reading?","a":"They can turn off lights when they leave a room."}],"quiz":[{"q":"Which word means 'doğa'?","o":["nature","climate","shade"],"a":0,"why":"Nature = doğa."},{"q":"We ___ paper at school.","o":["plant","recycle","water"],"a":1,"why":"Geri dönüştürmek için 'recycle' kullanılır."},{"q":"The tree ___ grow tall next year.","o":["will","bin","shade"],"a":0,"why":"Gelecek için 'will' kullanılır."},{"q":"Let's sit in the ___.","o":["bin","water","shade"],"a":2,"why":"Shade = gölge."}],"drills":[{"type":"Yerine koyma","prompt":"This bottle goes in the blue bin.","cue":"black","answer":"This bottle goes in the black bin."},{"type":"Dönüştürme","prompt":"We will save water.","cue":"negative","answer":"We won't save water."},{"type":"Genişletme","prompt":"We will plant a tree.","cue":"+ near the school, next spring","answer":"We will plant a tree near the school next spring."}],"sounds":[{"focus":"/ɪ/ – /iː/","tr":"Kısa /ɪ/ gevşek ve kısa çıkar; uzun /iː/ ise dudakları gererek uzatılır. Türkçedeki 'i' çoğu zaman bu iki sesin arasında kalır.","pairs":["bin / been","sit / seat","live / leave"]}],"mission":{"brief":"Okul kulübünde bir çevre projesi var ve sen bir öneri anlatacaksın. Claude, kulübe yeni katılan arkadaşın Leo olacak ve projen hakkında sorular soracak.","persona":"Leo, a friendly 12-year-old who just joined the eco club. Uses short sentences and asks one question at a time. Hidden fact: he wants to start a school garden but thinks nobody will help him. He only admits this if the learner asks open questions about his ideas and feelings.","goal":"Projeni anlat ve Leo'ya en az iki somut adım öner.","opener":"Hi! I'm new in the eco club. What are we going to do this year?"}},"KS3-010":{"objectives":["Teknoloji araçlarını ve günlük kullanımlarını anlatmak","'Can' ile yetenek ve izin ifade etmek","Online derste basit bir sorunu İngilizce bildirmek"],"dialogues":[{"title":"My new tablet","setting":"Ayla, doğum gününde aldığı yeni tableti arkadaşı Deniz'e gösteriyor.","lines":[{"s":"Ayla","en":"Look at my new tablet! I got it for my birthday.","tr":"Yeni tabletime bak! Doğum günüm için aldım."},{"s":"Deniz","en":"Wow, the screen is huge! Does it have a camera?","tr":"Vay, ekran çok büyük! Kamerası var mı?"},{"s":"Ayla","en":"Yes, a good one. I use it to take photos of my cat.","tr":"Evet, iyi bir tane. Kedimin fotoğraflarını çekmek için kullanıyorum."},{"s":"Deniz","en":"Can I try the games?","tr":"Oyunları deneyebilir miyim?"},{"s":"Ayla","en":"Sure, but first, let me show you how to set a password.","tr":"Tabii, ama önce sana şifre nasıl belirlenir göstereyim."},{"s":"Deniz","en":"Good thinking. My phone doesn't have one yet.","tr":"Akıllıca. Benim telefonumda henüz bir şifre yok."}]},{"title":"Video lesson trouble","setting":"Online derste Can'ın sesi kesiliyor ve öğretmen Ms Yıldız durumu düzeltmesi için yardım ediyor.","lines":[{"s":"Ms Yıldız","en":"Can, I can't hear you. Is your microphone working?","tr":"Can, seni duyamıyorum. Mikrofonun çalışıyor mu?"},{"s":"Can","en":"Sorry, I think the Wi-Fi connection is slow.","tr":"Üzgünüm, sanırım Wi-Fi bağlantısı yavaş."},{"s":"Ms Yıldız","en":"Try to move closer to the router.","tr":"Modeme biraz daha yaklaşmayı dene."},{"s":"Can","en":"Okay. Can you hear me now?","tr":"Tamam. Şimdi beni duyabiliyor musunuz?"},{"s":"Ms Yıldız","en":"Yes, perfect! Next time, turn off the video if the connection is weak.","tr":"Evet, mükemmel! Bir dahaki sefere bağlantı zayıfsa videoyu kapat."},{"s":"Can","en":"I will. Thank you, Ms Yıldız.","tr":"Kapatacağım. Teşekkürler, Ms Yıldız."}]},{"title":"Phone at dinner","setting":"Akşam yemeğinde anne, Deniz'in telefonu masadan kaldırmasını istiyor.","lines":[{"s":"Mum","en":"Deniz, put your phone on the table, please. We are eating dinner.","tr":"Deniz, lütfen telefonunu masaya koy. Akşam yemeği yiyoruz."},{"s":"Deniz","en":"Just one more minute. I'm watching a science video.","tr":"Sadece bir dakika daha. Bir bilim videosu izliyorum."},{"s":"Mum","en":"How long have you been on it today?","tr":"Bugün ne kadar süredir telefondasın?"},{"s":"Deniz","en":"Maybe two hours. But it's for school!","tr":"Belki iki saat. Ama okul için!"},{"s":"Mum","en":"Let's set a timer. Thirty minutes each evening, and no phone at dinner.","tr":"Bir zamanlayıcı kuralım. Her akşam otuz dakika, yemekte de telefon yok."},{"s":"Deniz","en":"Fine. That's fair.","tr":"Tamam. Bu adil."}]}],"reading":{"title":"Technology in our lives","paras":[{"en":"Technology is part of our daily life. We use phones to talk to friends, tablets to read books, and computers to do homework. Technology can be very useful, but it can also be distracting. Experts say we should take breaks from screens every hour. We should also protect our passwords and never share them. Smart use of technology helps us learn and stay safe.","tr":"Teknoloji günlük hayatımızın bir parçası. Arkadaşlarımızla konuşmak için telefonları, kitap okumak için tabletleri ve ödev yapmak için bilgisayarları kullanıyoruz. Teknoloji çok faydalı olabilir ama dikkatimizi de dağıtabilir. Uzmanlar, her saat başı ekrandan ara vermemiz gerektiğini söylüyor. Şifrelerimizi de korumalı ve asla paylaşmamalıyız. Teknolojiyi akıllıca kullanmak, öğrenmemize ve güvende kalmamıza yardım eder."}]},"vocab":[{"w":"tablet","ipa":"/ˈtæblət/","pos":"📱","tr":"tablet","ex":"I read a book on my tablet.","exTr":"Tabletimde bir kitap okuyorum."},{"w":"screen","ipa":"/skriːn/","pos":"🖥️","tr":"ekran","ex":"The screen is very bright.","exTr":"Ekran çok parlak."},{"w":"password","ipa":"/ˈpɑːswɜːd/","pos":"🔑","tr":"şifre","ex":"Never tell your password to a friend.","exTr":"Şifreni asla bir arkadaşına söyleme."},{"w":"camera","ipa":"/ˈkæmrə/","pos":"📷","tr":"kamera","ex":"This camera takes great photos.","exTr":"Bu kamera harika fotoğraflar çekiyor."},{"w":"microphone","ipa":"/ˈmaɪkrəfəʊn/","pos":"🎤","tr":"mikrofon","ex":"Check your microphone before the call.","exTr":"Görüşmeden önce mikrofonunu kontrol et."},{"w":"connection","ipa":"/kəˈnekʃn/","pos":"📶","tr":"bağlantı","ex":"The internet connection is slow today.","exTr":"İnternet bağlantısı bugün yavaş."},{"w":"break","ipa":"/breɪk/","pos":"☕","tr":"mola, ara","ex":"Let's take a break for five minutes.","exTr":"Beş dakika ara verelim."},{"w":"share","ipa":"/ʃeə/","pos":"🤝","tr":"paylaşmak","ex":"Can you share your notes with me?","exTr":"Notlarını benimle paylaşabilir misin?"}],"chunks":[{"en":"Is your microphone working?","tr":"Mikrofonun çalışıyor mu?"},{"en":"Let's set a timer.","tr":"Bir zamanlayıcı kuralım."},{"en":"That's fair.","tr":"Bu adil."},{"en":"Can you hear me now?","tr":"Şimdi beni duyabiliyor musunuz?"}],"grammar":{"point":"Can and can't","tr":"'Can' bir şeyi yapabildiğimizi ya da izin istediğimizi söylemek için kullanılır. Olumsuzu 'can't' olur ve fiil her zaman aynı hâlde kalır. Soru yaparken 'can' cümlenin başına geçer.","examples":["I can use the tablet.","Can I try the games?","You can't share your password.","She can hear you now."]},"questions":[{"q":"What does Ayla use her tablet camera for?","a":"To take photos of her cat."},{"q":"What does Ms Yıldız tell Can to do?","a":"To move closer to the router."},{"q":"What does Mum want Deniz to do at dinner?","a":"Put the phone on the table."}],"quiz":[{"q":"Which word means 'şifre'?","o":["camera","password","connection"],"a":1,"why":"Password = şifre."},{"q":"Which sentence asks for permission?","o":["Can I try the games?","I can hear you.","You can't share it."],"a":0,"why":"'Can I…?' izin ister."},{"q":"We should take a ___ from the screen every hour.","o":["password","connection","break"],"a":2,"why":"Ekrandan saatte bir mola ver."},{"q":"The Wi-Fi ___ is weak.","o":["share","connection","camera"],"a":1,"why":"Connection = bağlantı."}],"drills":[{"type":"Yerine koyma","prompt":"I can use the tablet.","cue":"phone","answer":"I can use the phone."},{"type":"Dönüştürme","prompt":"She can hear you.","cue":"negative","answer":"She can't hear you."},{"type":"Soru yap","prompt":"I can take photos.","cue":"Can…?","answer":"Can I take photos?"}],"sounds":[{"focus":"/ɪ/ – /iː/","tr":"Kısa /ɪ/ gevşek ve kısa çıkar; uzun /iː/ ise dudakları gererek uzatılır. Türkçedeki 'i' çoğu zaman bu iki sesin arasında kalır.","pairs":["bit / beat","sit / seat","fill / feel"]}],"mission":{"brief":"Okulunuz için yeni bir tablet almak istiyorsun. Claude, tablet satan bir mağazanın satış danışmanı olacak; ona ihtiyaçlarını İngilizce anlatıp uygun bir model seçmelisin.","persona":"Mr Kaan, a friendly and patient shop assistant at a technology store. Speaks clearly and asks one question at a time. Hidden fact: the store has a discount on a tablet with a longer battery, but he only mentions it if the learner asks about budget or what the tablet is needed for.","goal":"Tabletin kullanım amacını ve bütçeni İngilizce söyle, bir model seç.","opener":"Hello! Welcome to our store. What kind of tablet are you looking for?"}},"KS3-011":{"objectives":["Spor ve takım çalışmasıyla ilgili kelimeleri kullanmak","'Let's' ile öneri yapmak","Maç sonrası duyguları ve önerileri İngilizce ifade etmek"],"dialogues":[{"title":"Before the final","setting":"Final maçından önce antrenör Arda, takımı toplayıp son talimatları veriyor.","lines":[{"s":"Coach Arda","en":"Team, gather round! We play the final match tomorrow.","tr":"Takım, toplanın! Yarın final maçını oynuyoruz."},{"s":"Yusuf","en":"Are we ready? I feel a bit nervous.","tr":"Hazır mıyız? Biraz gerginim."},{"s":"Coach Arda","en":"Nervous is normal. Breathe and trust your team.","tr":"Gerginlik normal. Nefes al ve takımına güven."},{"s":"Ece","en":"Coach, should I play in defence or in attack?","tr":"Hocam, savunmada mı yoksa hücumda mı oynayayım?"},{"s":"Coach Arda","en":"Defence today, Ece. Please protect the goal.","tr":"Bugün savunma, Ece. Lütfen kaleyi koru."},{"s":"Yusuf","en":"We can do it together!","tr":"Birlikte başarabiliriz!"}]},{"title":"After the defeat","setting":"Maçtan sonra soyunma odasında Ece ve Yusuf, kaybettikleri maçı konuşuyor.","lines":[{"s":"Ece","en":"We lost by one goal. I'm so disappointed.","tr":"Bir golle kaybettik. Çok hayal kırıklığına uğradım."},{"s":"Yusuf","en":"Me too. But we played well in the second half.","tr":"Ben de. Ama ikinci yarıda iyi oynadık."},{"s":"Ece","en":"You're right. You passed the ball really well.","tr":"Haklısın. Topu gerçekten çok iyi pasladın."},{"s":"Yusuf","en":"Thanks! Next time, I'll shoot more often.","tr":"Teşekkürler! Bir dahaki sefere daha sık şut atacağım."},{"s":"Ece","en":"Let's practise together on Saturday?","tr":"Cumartesi birlikte antrenman yapalım mı?"},{"s":"Yusuf","en":"Sure! Bring your water bottle, it's hot.","tr":"Tabii! Su şişeni getir, hava sıcak."}]},{"title":"Club rules","setting":"Spor kulübünde antrenör Arda, yeni katılan Mina'ya kulübün kurallarını anlatıyor.","lines":[{"s":"Coach Arda","en":"Welcome to the club! Our rule number one is respect.","tr":"Kulübe hoş geldin! Birinci kuralımız saygı."},{"s":"Mina","en":"What does respect mean here?","tr":"Burada saygı ne anlama geliyor?"},{"s":"Coach Arda","en":"It means listening to others and never shouting at your teammates.","tr":"Başkalarını dinlemek ve takım arkadaşlarına asla bağırmamak demek."},{"s":"Mina","en":"And what about rule number two?","tr":"Peki ikinci kural ne?"},{"s":"Coach Arda","en":"Arrive on time and help clean the equipment after training.","tr":"Zamanında gel ve antrenmandan sonra malzemeleri temizlemeye yardım et."},{"s":"Mina","en":"Got it. I'll be on time every day.","tr":"Anladım. Her gün zamanında olacağım."}]}],"reading":{"title":"Playing as a team","paras":[{"en":"Sports teach us more than skills. When a team works together, everyone has a role. The goalkeeper protects the goal, the defenders stop the other team, and the strikers try to score. A good player also helps others. Win or lose, a team should celebrate effort and learn from mistakes. Remember, the best team is the one that supports each other.","tr":"Spor bize beceriden daha fazlasını öğretir. Bir takım birlikte çalıştığında herkesin bir görevi vardır. Kaleci golü korur, savunmacılar rakip takımı durdurur ve forvetler gol atmaya çalışır. İyi bir oyuncu başkalarına da yardım eder. Kazansak da kaybetsek de bir takım çabayı kutlamalı ve hatalarından ders almalıdır. Unutma, en iyi takım birbirini destekleyen takımdır."}]},"vocab":[{"w":"team","ipa":"/tiːm/","pos":"👥","tr":"takım","ex":"Our team won the match.","exTr":"Takımımız maçı kazandı."},{"w":"goal","ipa":"/ɡəʊl/","pos":"⚽","tr":"kale; gol","ex":"He scored a goal in the first half.","exTr":"İlk yarıda bir gol attı."},{"w":"defence","ipa":"/dɪˈfens/","pos":"🛡️","tr":"savunma","ex":"Our defence is very strong.","exTr":"Savunmamız çok güçlü."},{"w":"pass","ipa":"/pɑːs/","pos":"➡️","tr":"pas vermek","ex":"Pass the ball to me!","exTr":"Topu bana pasla!"},{"w":"score","ipa":"/skɔː/","pos":"🎯","tr":"gol atmak, skor yapmak","ex":"Who will score first?","exTr":"İlk kim gol atacak?"},{"w":"nervous","ipa":"/ˈnɜːvəs/","pos":"😬","tr":"gergin, endişeli","ex":"I am nervous before every game.","exTr":"Her maçtan önce gergin oluyorum."},{"w":"respect","ipa":"/rɪˈspekt/","pos":"🙏","tr":"saygı","ex":"We show respect to the referee.","exTr":"Hakeme saygı gösteriyoruz."},{"w":"mistake","ipa":"/mɪˈsteɪk/","pos":"❌","tr":"hata","ex":"Everyone makes a mistake sometimes.","exTr":"Herkes bazen hata yapar."}],"chunks":[{"en":"We can do it together!","tr":"Birlikte başarabiliriz!"},{"en":"Let's practise together.","tr":"Birlikte antrenman yapalım."},{"en":"Win or lose…","tr":"Kazansak da kaybetsek de…"},{"en":"Nervous is normal.","tr":"Gerginlik normal."}],"grammar":{"point":"Suggestions with Let's","tr":"'Let's' 'hadi … yapalım' anlamına gelir ve birlikte bir şey yapmayı önermek için kullanılır. Olumsuzu 'Let's not' olur. Bu öneriye cevap verirken 'Sure' ya da 'Good idea' diyebilirsin.","examples":["Let's practise on Saturday.","Let's go to the field now.","Let's not give up.","Let's celebrate our effort!"]},"questions":[{"q":"Which player protects the goal?","a":"The goalkeeper."},{"q":"What will Yusuf do next time?","a":"He will shoot more often."},{"q":"What is rule number one in the club?","a":"Respect."}],"quiz":[{"q":"In football, to 'pass' means…","o":["kick the ball to a teammate","stop the ball","run away"],"a":0,"why":"Pas vermek, topu takım arkadaşına atmaktır."},{"q":"I'm ___. I have a big match tomorrow.","o":["respect","score","nervous"],"a":2,"why":"Nervous = gergin."},{"q":"Which word means 'hata'?","o":["goal","mistake","defence"],"a":1,"why":"Mistake = hata."},{"q":"Let's ___ together on Saturday.","o":["practised","practise","practising"],"a":1,"why":"'Let's' sonrasında fiilin yalın hâli gelir."}],"drills":[{"type":"Yerine koyma","prompt":"Let's practise on Saturday.","cue":"play","answer":"Let's play on Saturday."},{"type":"Dönüştürme","prompt":"We won the match.","cue":"Question: Did…?","answer":"Did we win the match?"},{"type":"Genişletme","prompt":"Yusuf passed the ball.","cue":"+ to Ece, quickly","answer":"Yusuf passed the ball to Ece quickly."}],"sounds":[{"focus":"/ɔː/","tr":"Türkçede uzun 'o' sesi yoktur. Dudaklarını yuvarlayıp sesi uzat, 'a' ya da 'o' gibi kısa bırakma: 'sport', 'score', 'short'.","pairs":["short / shot","score / scare","sport / spot"]}],"mission":{"brief":"Spor kulübüne yeni katıldın ve takım kurallarını bir arkadaşına anlatacaksın. Claude, kulübe yeni gelen utangaç bir çocuk olan Ali olacak ve sana sorular soracak.","persona":"Ali, a shy 12-year-old who just joined the football club. Uses short sentences and asks one question at a time. Hidden fact: he is afraid of making mistakes in front of others, and he really wants to play as a goalkeeper but is too nervous to say so. He reveals this only when the learner asks open questions about his feelings and goals.","goal":"Takım kurallarından en az ikisini anlat ve Ali'ye bir pozisyon önerisi yap.","opener":"Hi, I'm new here. Is it hard to join the team?"}},"KS3-012":{"objectives":["Gelecek planlarını ve hayallerini İngilizce anlatmak","'Be going to' ile planları ifade etmek","Bir hedefi küçük adımlara bölerek söylemek"],"dialogues":[{"title":"What do you want to be?","setting":"Okul kantininde Derin ve Burak, büyüdüklerinde ne olmak istediklerini konuşuyor.","lines":[{"s":"Derin","en":"What do you want to be when you grow up?","tr":"Büyüyünce ne olmak istiyorsun?"},{"s":"Burak","en":"I'm going to be a pilot. I'll fly to many countries!","tr":"Pilot olacağım. Birçok ülkeye uçacağım!"},{"s":"Derin","en":"Wow, that's amazing. What are you going to study?","tr":"Vay, bu harika. Ne okuyacaksın?"},{"s":"Burak","en":"Maths and physics, I think. I'll need good grades.","tr":"Sanırım matematik ve fizik. İyi notlara ihtiyacım olacak."},{"s":"Derin","en":"I want to be a vet. I'll look after animals every day.","tr":"Ben veteriner olmak istiyorum. Her gün hayvanlara bakacağım."},{"s":"Burak","en":"That's lovely. Animals need people like you!","tr":"Bu çok güzel. Hayvanların senin gibi insanlara ihtiyacı var!"}]},{"title":"Summer holiday plans","setting":"Akşam yemeğinde baba, Derin'in yaz tatili planlarını soruyor.","lines":[{"s":"Dad","en":"Where do you want to go this summer?","tr":"Bu yaz nereye gitmek istiyorsun?"},{"s":"Derin","en":"I'm going to visit my cousins in Izmir.","tr":"Kuzenlerimi görmek için İzmir'e gideceğim."},{"s":"Dad","en":"Good plan! When are you going to leave?","tr":"Güzel plan! Ne zaman yola çıkacaksın?"},{"s":"Derin","en":"We are going to leave on the first of July.","tr":"Temmuzun birinde yola çıkacağız."},{"s":"Dad","en":"Are you going to take your swimming gear?","tr":"Yüzme malzemelerini almayı düşünüyor musun?"},{"s":"Derin","en":"Yes! We are going to swim at the beach every day.","tr":"Evet! Her gün sahilde yüzmeye gideceğiz."}]},{"title":"A science project plan","setting":"Öğretmen Ms Ersoy, Burak'a fen projesi için bir hedef belirlemesinde yardım ediyor.","lines":[{"s":"Ms Ersoy","en":"Let's set a goal for your science project. What is your plan?","tr":"Fen projen için bir hedef belirleyelim. Planın ne?"},{"s":"Burak","en":"I'm going to build a small solar car.","tr":"Küçük bir güneş arabası yapmayı planlıyorum."},{"s":"Ms Ersoy","en":"Excellent! When are you going to finish it?","tr":"Harika! Ne zaman bitirmeyi düşünüyorsun?"},{"s":"Burak","en":"I hope to finish it before the end of May.","tr":"Mayıs sonundan önce bitirmeyi umuyorum."},{"s":"Ms Ersoy","en":"Good. First, make a list of the things you need.","tr":"İyi. Önce ihtiyacın olan şeylerin bir listesini yap."},{"s":"Burak","en":"I will do it tonight. Thank you!","tr":"Bu gece yapacağım. Teşekkürler!"}]}],"reading":{"title":"Dreams and plans","paras":[{"en":"Everyone has dreams about the future. To reach a dream, you need a plan. First, set a goal. Then, break it into small steps. For example, if you want to be a writer, you can read a book every month and write a short story each week. Your plan can change, and that is fine. What matters is that you keep trying.","tr":"Herkesin geleceğe dair hayalleri vardır. Bir hayale ulaşmak için bir plana ihtiyacın var. Önce bir hedef belirle. Sonra onu küçük adımlara böl. Örneğin yazar olmak istiyorsan her ay bir kitap okuyabilir ve her hafta kısa bir hikâye yazabilirsin. Planın değişebilir, bu da normaldir. Önemli olan denemeye devam etmektir."}]},"vocab":[{"w":"future","ipa":"/ˈfjuːtʃə/","pos":"🔮","tr":"gelecek","ex":"What is your plan for the future?","exTr":"Gelecek için planın ne?"},{"w":"dream","ipa":"/driːm/","pos":"💭","tr":"hayal, düş","ex":"My dream is to fly a plane.","exTr":"Hayalim uçak uçurmak."},{"w":"goal","ipa":"/ɡəʊl/","pos":"🎯","tr":"hedef","ex":"Our goal is to finish by June.","exTr":"Hedefimiz haziran ayında bitirmek."},{"w":"plan","ipa":"/plæn/","pos":"🗓️","tr":"plan","ex":"I have a plan for the weekend.","exTr":"Hafta sonu için bir planım var."},{"w":"step","ipa":"/step/","pos":"👣","tr":"adım","ex":"Take one step at a time.","exTr":"Bir seferde bir adım at."},{"w":"story","ipa":"/ˈstɔːri/","pos":"📖","tr":"hikâye","ex":"She writes a short story every week.","exTr":"Her hafta kısa bir hikâye yazıyor."},{"w":"try","ipa":"/traɪ/","pos":"💪","tr":"denemek","ex":"Don't give up. Try again!","exTr":"Pes etme. Tekrar dene!"},{"w":"change","ipa":"/tʃeɪndʒ/","pos":"🔄","tr":"değişmek, değiştirmek","ex":"The weather can change fast.","exTr":"Hava çok çabuk değişebilir."}],"chunks":[{"en":"What do you want to be?","tr":"Ne olmak istiyorsun?"},{"en":"I'm going to…","tr":"… yapmayı planlıyorum."},{"en":"I hope to…","tr":"… umuyorum."},{"en":"What matters is that you keep trying.","tr":"Önemli olan denemeye devam etmek."}],"grammar":{"point":"Plans with be going to","tr":"Önceden düşünülmüş planları anlatmak için 'be going to' kullanılır. 'I am going to', 'he is going to', 'they are going to' gibi kişiye göre 'be' hâli değişir. Soru yaparken 'be' fiili başa geçer.","examples":["I'm going to visit my cousins.","We are going to swim every day.","Are you going to take your gear?","She isn't going to be late."]},"questions":[{"q":"What does Burak want to be?","a":"A pilot."},{"q":"When is Derin's family going to leave for Izmir?","a":"On the first of July."},{"q":"According to the reading, what do you need to reach a dream?","a":"A plan."}],"quiz":[{"q":"Which word means 'hayal'?","o":["dream","goal","step"],"a":0,"why":"Dream = hayal."},{"q":"I'm ___ build a solar car.","o":["goes to","going to","go to"],"a":1,"why":"Plan için 'be going to' kullanılır."},{"q":"Which word means 'adım'?","o":["plan","story","step"],"a":2,"why":"Step = adım."},{"q":"Which word means 'değiştirmek'?","o":["try","change","dream"],"a":1,"why":"Change = değiştirmek."}],"drills":[{"type":"Yerine koyma","prompt":"I'm going to be a pilot.","cue":"vet","answer":"I'm going to be a vet."},{"type":"Dönüştürme","prompt":"She is going to visit Izmir.","cue":"Question: Is…?","answer":"Is she going to visit Izmir?"},{"type":"Genişletme","prompt":"We are going to swim.","cue":"+ at the beach every day","answer":"We are going to swim at the beach every day."}],"sounds":[{"focus":"/ŋ/","tr":"Türkçede 'ng' harfleri kelime sonunda 'n' ve 'g' olarak ayrılmadan, tek bir burun sesi olarak çıkar. 'g' sesini ekleme: 'sing' 'sin' gibi değil, 'siŋ' gibi bitir.","pairs":["sing / sin","wing / win","song / son"]}],"mission":{"brief":"Okul için 'Gelecek Planım' adlı bir poster hazırlıyorsun. Claude, sınıf arkadaşın Kerem olacak ve senin hedeflerini ve planlarını soracak; sen de kendi hayallerini İngilizce anlatacaksın.","persona":"Kerem, a curious 13-year-old classmate preparing a poster about his future. Uses short, simple sentences and asks one question at a time. Hidden fact: he really wants to become a chef, but he has not told his parents yet. He reveals this only when the learner asks good open questions about what he enjoys doing.","goal":"Kendi hayalini ve bir planını anlat, Kerem'in hayalini öğren.","opener":"Hi! Our teacher says we have to talk about future plans. What do you want to be?"}},"KS3-013":{"objectives":["Havalimanı, yol ve otel durumlarında basit İngilizce kullanmak","'Can I' ve 'Could I' ile kibarca istek ifade etmek","Bir sorunu kısa ve net şekilde bildirmek"],"dialogues":[{"title":"At the check-in desk","setting":"Londra Havalimanı'nda Selin, check-in masasında görevliyle konuşuyor.","lines":[{"s":"Staff","en":"Good morning. Passport and ticket, please.","tr":"Günaydın. Pasaport ve biletinizi alabilir miyim, lütfen?"},{"s":"Selin","en":"Here you are. Is our flight on time?","tr":"Buyurun. Uçuşumuz zamanında mı?"},{"s":"Staff","en":"Yes, it departs at ten thirty from gate twelve.","tr":"Evet, saat on otuzda on iki numaralı kapıdan kalkıyor."},{"s":"Selin","en":"Can I have a window seat, please?","tr":"Pencere kenarında bir koltuk alabilir miyim, lütfen?"},{"s":"Staff","en":"Of course. Here is your boarding pass.","tr":"Tabii. Buyurun, binme kartınız."},{"s":"Selin","en":"Thank you! Where is the nearest café?","tr":"Teşekkürler! En yakın kafe nerede?"}]},{"title":"Lost in London","setting":"Selin, Londra'da metro istasyonunu bulamayınca yoldan geçen Tom'a soruyor.","lines":[{"s":"Selin","en":"Excuse me, how do I get to the British Museum?","tr":"Affedersiniz, British Museum'a nasıl giderim?"},{"s":"Tom","en":"Take the Central line and get off at Holborn.","tr":"Central hattına binin ve Holborn'da inin."},{"s":"Selin","en":"Is it far from here?","tr":"Buradan uzak mı?"},{"s":"Tom","en":"No, it's about ten minutes on the train.","tr":"Hayır, trenle yaklaşık on dakika."},{"s":"Selin","en":"Do I need a ticket for the underground?","tr":"Metro için bilet almam gerekiyor mu?"},{"s":"Tom","en":"Yes, use your card at the gate. Enjoy your visit!","tr":"Evet, kartını turnikede okut. İyi geziler!"}]},{"title":"Hotel problem","setting":"Otelin resepsiyonunda Selin, odasındaki Wi-Fi sorununu bildiriyor.","lines":[{"s":"Selin","en":"Hi, I have a reservation under Selin Acar.","tr":"Merhaba, Selin Acar adına bir rezervasyonum var."},{"s":"Anna","en":"Welcome! Your room is on the third floor.","tr":"Hoş geldiniz! Odanız üçüncü katta."},{"s":"Selin","en":"Great. Is breakfast included?","tr":"Harika. Kahvaltı dahil mi?"},{"s":"Anna","en":"Yes, it's served from seven to ten.","tr":"Evet, yedi ile on arasında servis ediliyor."},{"s":"Selin","en":"Also, the Wi-Fi in my room doesn't work.","tr":"Ayrıca odamdaki Wi-Fi çalışmıyor."},{"s":"Anna","en":"I'm sorry about that. I'll send a technician right away.","tr":"Bunun için üzgünüm. Hemen bir teknisyen göndereceğim."}]}],"reading":{"title":"Before you travel","paras":[{"en":"Travelling abroad is exciting, but it needs preparation. Check your passport at least six months before your trip. Some countries need a visa, so read the rules early. Pack light clothes and a warm jacket, because the weather can change fast. Learn a few useful phrases, such as 'Excuse me' and 'Thank you'. Most people in cities speak English, but a smile always helps.","tr":"Yurt dışına seyahat etmek heyecan verici ama hazırlık gerektirir. Seyahatinizden en az altı ay önce pasaportunuzu kontrol edin. Bazı ülkeler vize ister, bu yüzden kuralları erken okuyun. Hava çabuk değişebileceği için hafif kıyafetler ve sıcak bir mont paketleyin. 'Excuse me' ve 'Thank you' gibi birkaç faydalı ifade öğrenin. Şehirlerde çoğu insan İngilizce konuşur, ama gülümsemek her zaman yardımcı olur."}]},"vocab":[{"w":"passport","ipa":"/ˈpɑːspɔːt/","pos":"🛂","tr":"pasaport","ex":"Don't forget your passport.","exTr":"Pasaportunu unutma."},{"w":"ticket","ipa":"/ˈtɪkɪt/","pos":"🎫","tr":"bilet","ex":"Here is my ticket.","exTr":"Biletim burada."},{"w":"flight","ipa":"/flaɪt/","pos":"✈️","tr":"uçuş","ex":"Our flight leaves at noon.","exTr":"Uçuşumuz öğlen kalkıyor."},{"w":"gate","ipa":"/ɡeɪt/","pos":"🚪","tr":"kapı (havalimanı)","ex":"Go to gate twelve.","exTr":"On iki numaralı kapıya git."},{"w":"reservation","ipa":"/ˌrezəˈveɪʃn/","pos":"🏨","tr":"rezervasyon","ex":"I have a hotel reservation.","exTr":"Bir otel rezervasyonum var."},{"w":"visa","ipa":"/ˈviːzə/","pos":"📄","tr":"vize","ex":"Do I need a visa for this country?","exTr":"Bu ülke için vize gerekiyor mu?"},{"w":"pack","ipa":"/pæk/","pos":"🧳","tr":"valizi hazırlamak, paketlemek","ex":"I still need to pack my bag.","exTr":"Hâlâ çantamı hazırlamam gerekiyor."},{"w":"underground","ipa":"/ˈʌndəɡraʊnd/","pos":"🚇","tr":"metro","ex":"The underground is fast in London.","exTr":"Londra'da metro çok hızlı."}],"chunks":[{"en":"Excuse me, how do I get to…?","tr":"Affedersiniz, … nasıl giderim?"},{"en":"Can I have a window seat?","tr":"Pencere kenarında bir koltuk alabilir miyim?"},{"en":"Enjoy your visit!","tr":"İyi geziler!"},{"en":"I have a reservation under…","tr":"… adına bir rezervasyonum var."}],"grammar":{"point":"Polite requests with Can I and Could I","tr":"Bir şey istemek ya da izin istemek için 'Can I…?' kullanılır. 'Could I…?' ise daha kibar bir ton verir ve resmi yerlerde tercih edilir. Cevap verirken 'Of course' ya da 'Sure' diyebilirsin.","examples":["Can I have a window seat, please?","Could I see the menu, please?","Do I need a visa for this country?","Could you tell me which line to take?"]},"questions":[{"q":"What does Selin ask for at the check-in desk?","a":"A window seat."},{"q":"How long does it take to get to the British Museum by train?","a":"About ten minutes."},{"q":"What should you check at least six months before your trip?","a":"Your passport."}],"quiz":[{"q":"Which word means 'bilet'?","o":["ticket","passport","flight"],"a":0,"why":"Ticket = bilet."},{"q":"Excuse me, ___ I get to the station?","o":["what do","how do","where do"],"a":1,"why":"Yol sormak için 'How do I get to…?' kalıbı kullanılır."},{"q":"Which document do you need to travel abroad?","o":["pack","gate","passport"],"a":2,"why":"Pasaport seyahat için gerekli bir belgedir."},{"q":"The hotel ___ breakfast from seven to ten.","o":["serve","serves","served"],"a":1,"why":"Hotel tekil olduğu için fiile -s gelir."}],"drills":[{"type":"Yerine koyma","prompt":"Can I have a window seat?","cue":"aisle seat","answer":"Can I have an aisle seat?"},{"type":"Dönüştürme","prompt":"Tell me which line to take.","cue":"Could you…?","answer":"Could you tell me which line to take?"},{"type":"Soru yap","prompt":"The Wi-Fi works in my room.","cue":"Does…?","answer":"Does the Wi-Fi work in my room?"}],"sounds":[{"focus":"/æ/","tr":"Türkçede bu ses yok. Ağzını 'e' ile 'a' arasında, geniş aç ve dilini aşağıda tut: 'pack', 'passport', 'map'. 'Pack' kelimesini 'pek' gibi okumamaya dikkat et.","pairs":["pack / peck","bad / bed","man / men"]}],"mission":{"brief":"Londra'daki bir otelde kalacaksın ve rezervasyonunda bir sorun var. Claude, otelin resepsiyon görevlisi Anna olacak; ona rezervasyonunu İngilizce doğrulayıp sorununu anlatmalısın.","persona":"Anna, a friendly and patient hotel receptionist in London. Speaks clearly and kindly, with one question at a time. Hidden fact: your room will not be ready until 3 pm, but she can store your luggage and give you a free breakfast voucher. She offers these only if the learner asks what the hotel can do to help.","goal":"Rezervasyonunu doğrula, sorunu bildir ve bir çözüm iste.","opener":"Good afternoon! Welcome to Riverside Hotel. How can I help you?"}},"KS3-014":{"objectives":["Sağlıklı alışkanlıkları İngilizce anlatmak","'Let's…' kalıbıyla öneride bulunmak","Kısa bir tavsiye cümlesi kurmak"],"dialogues":[{"title":"Breakfast choice","setting":"Sabah kahvaltısında Mert ile Ece sağlıklı yiyecekleri konuşuyor.","lines":[{"s":"Mert","en":"I want chocolate cereal!","tr":"Çikolatalı gevrek istiyorum!"},{"s":"Ece","en":"Chocolate is sweet. Let's eat eggs and fruit!","tr":"Çikolata tatlı. Hadi yumurta ve meyve yiyelim!"},{"s":"Mert","en":"Are eggs healthy?","tr":"Yumurta sağlıklı mı?"},{"s":"Ece","en":"Yes! They give us energy.","tr":"Evet! Bize enerji verirler."},{"s":"Mert","en":"OK. I'll eat an apple too.","tr":"Tamam. Ben de bir elma yiyeceğim."},{"s":"Ece","en":"Great choice! Apples are fresh and healthy.","tr":"Harika seçim! Elmalar taze ve sağlıklı."},{"s":"Mert","en":"Thanks, Ece! I feel strong now.","tr":"Teşekkürler Ece! Şimdi kendimi güçlü hissediyorum."}]},{"title":"After school sport","setting":"Okul çıkışında Ali ile Deniz parkta buluşuyor.","lines":[{"s":"Ali","en":"You look tired, Deniz. Let's go for a run!","tr":"Yorgun görünüyorsun Deniz. Hadi koşmaya gidelim!"},{"s":"Deniz","en":"I play on my phone all day. I don't move much.","tr":"Bütün gün telefonumla oynuyorum. Pek hareket etmiyorum."},{"s":"Ali","en":"Move more! Walk, dance or ride a bike.","tr":"Daha çok hareket et! Yürü, dans et ya da bisiklete bin."},{"s":"Deniz","en":"Is it good for my body?","tr":"Vücudum için iyi mi?"},{"s":"Ali","en":"Yes! Exercise makes your heart strong.","tr":"Evet! Egzersiz kalbini güçlendirir."},{"s":"Deniz","en":"OK. Ten minutes of running?","tr":"Tamam. On dakika koşu mu?"},{"s":"Ali","en":"Perfect! Let's start now!","tr":"Mükemmel! Hemen başlayalım!"}]},{"title":"Water in class","setting":"Öğretmen Selin, sınıftaki öğrencilere su içmeyi hatırlatıyor.","lines":[{"s":"Teacher","en":"Class, drink water every hour.","tr":"Sınıf, her saat başı su için."},{"s":"Eren","en":"I forget to drink water!","tr":"Su içmeyi unutuyorum!"},{"s":"Teacher","en":"Keep a water bottle on your desk.","tr":"Masanızın üstünde bir su şişesi bulundurun."},{"s":"Zeynep","en":"Good idea. Water helps us think.","tr":"İyi fikir. Su düşünmemize yardım eder."},{"s":"Teacher","en":"Right, Zeynep! And no sugary drinks at lunch.","tr":"Doğru Zeynep! Öğle yemeğinde de şekerli içecek yok."},{"s":"Eren","en":"Oh no! My juice is sweet!","tr":"Ah olmaz! Meyve suyum tatlı!"},{"s":"Teacher","en":"Choose water or milk. Well done!","tr":"Su ya da süt seç. Aferin!"}]}],"reading":{"title":"Ece's healthy day","paras":[{"en":"Ece wakes up early. She eats eggs, fruit and bread for breakfast. She drinks water all day. After school she plays football with her friends for one hour. Her mum says sleep is important too, so Ece goes to bed at nine. She feels happy and strong every day. She says healthy habits are fun!","tr":"Ece erken uyanır. Kahvaltıda yumurta, meyve ve ekmek yer. Bütün gün su içer. Okuldan sonra arkadaşlarıyla bir saat futbol oynar. Annesi uykunun da önemli olduğunu söyler, bu yüzden Ece saat dokuzda yatağa gider. Her gün mutlu ve güçlü hisseder. Sağlıklı alışkanlıkların eğlenceli olduğunu söyler!"}]},"vocab":[{"w":"healthy","ipa":"/ˈhelθi/","pos":"🥗","tr":"sağlıklı","ex":"Eggs are healthy.","exTr":"Yumurta sağlıklıdır."},{"w":"water","ipa":"/ˈwɔːtə/","pos":"💧","tr":"su","ex":"I drink water every day.","exTr":"Her gün su içiyorum."},{"w":"exercise","ipa":"/ˈeksəsaɪz/","pos":"🏃","tr":"egzersiz, spor","ex":"Exercise makes you strong.","exTr":"Egzersiz seni güçlü yapar."},{"w":"sleep","ipa":"/sliːp/","pos":"😴","tr":"uyku","ex":"Sleep is important.","exTr":"Uyku önemlidir."},{"w":"fruit","ipa":"/fruːt/","pos":"🍎","tr":"meyve","ex":"I eat fruit after school.","exTr":"Okuldan sonra meyve yiyorum."},{"w":"breakfast","ipa":"/ˈbrekfəst/","pos":"🥣","tr":"kahvaltı","ex":"Breakfast gives us energy.","exTr":"Kahvaltı bize enerji verir."},{"w":"tired","ipa":"/ˈtaɪəd/","pos":"🥱","tr":"yorgun","ex":"You look tired today.","exTr":"Bugün yorgun görünüyorsun."},{"w":"strong","ipa":"/strɒŋ/","pos":"💪","tr":"güçlü","ex":"I feel strong now.","exTr":"Şimdi kendimi güçlü hissediyorum."}],"chunks":[{"en":"Let's go for a run!","tr":"Hadi koşmaya gidelim!"},{"en":"Good idea!","tr":"İyi fikir!"},{"en":"I feel strong.","tr":"Kendimi güçlü hissediyorum."},{"en":"Well done!","tr":"Aferin!"}],"grammar":{"point":"Let's + verb","tr":"Let's, 'let us' anlamına gelir ve birlikte bir şey yapmayı önerir. Let's'den sonra fiil her zaman yalın halde gelir. Türkçedeki 'hadi … yapalım' kalıbıyla aynı işi görür.","examples":["Let's eat eggs and fruit!","Let's go for a run.","Let's start now!","Let's drink water together."]},"questions":[{"q":"What does Ece eat for breakfast?","a":"Eggs, fruit and bread."},{"q":"What time does Ece go to bed?","a":"At nine o'clock."},{"q":"Which drinks are not allowed at lunch?","a":"Sugary drinks."}],"quiz":[{"q":"Which word means 'su'?","o":["water","sleep","strong"],"a":0,"why":""},{"q":"After exercise, I feel ___. (💪)","o":["tired","strong","fruit"],"a":1,"why":"Egzersiz seni güçlü hissettirir."},{"q":"Let's ___ for a run!","o":["goes","going","go"],"a":2,"why":"Let's'den sonra fiil yalın gelir."},{"q":"Which is NOT a healthy choice?","o":["fruit","sugary drinks","water"],"a":1,"why":"Şekerli içecekler sağlıklı değildir."}],"drills":[{"type":"Yerine koyma","prompt":"Let's eat eggs.","cue":"fruit","answer":"Let's eat fruit."},{"type":"Soru yap","prompt":"Ece eats eggs for breakfast.","cue":"Does…?","answer":"Does Ece eat eggs for breakfast?"},{"type":"Genişletme","prompt":"I drink water.","cue":"+ every hour","answer":"I drink water every hour."}],"sounds":[{"focus":"/θ/","tr":"Dilinin ucunu üst ve alt dişlerin arasına koy, hafifçe üfle. Türkçede bu ses yok, bu yüzden çoğu kişi 's' ya da 't' diye söyler.","pairs":["thin / tin","thank / tank","three / tree"]}],"mission":{"brief":"Arkadaşın Max bugün çok yorgun ve nedenini bilmiyor. Claude, Max olarak konuşacak; asıl sorununu bulmak için iyi sorular sor. Sonra ona 'Let's…' ile en az üç sağlıklı öneride bulun.","persona":"Max, a 13-year-old friend who says he is always tired and eats mostly pizza and crisps. Hidden fact: he plays video games until 3 a.m. every night, and he only admits this if the learner asks good open questions about his sleep. Speaks in short, casual sentences.","goal":"Max'in asıl sorununu bul ve ona en az üç öneride bulun.","opener":"Hey! I'm so tired today. I don't know why."}},"KS3-015":{"objectives":["Sınav stresini İngilizce anlatmak","Emir kipiyle tavsiye vermek","Birine sakinleştirici bir öneride bulunmak"],"dialogues":[{"title":"Night before the test","setting":"Sınavdan önceki akşam Lina annesiyle konuşuyor.","lines":[{"s":"Lina","en":"I'm so nervous about the test tomorrow.","tr":"Yarınki sınav yüzünden çok gerginim."},{"s":"Mum","en":"Take a deep breath. You're ready.","tr":"Derin bir nefes al. Hazırsın."},{"s":"Lina","en":"I can't remember the words!","tr":"Kelimeleri hatırlayamıyorum!"},{"s":"Mum","en":"Let's read them together, slowly.","tr":"Hadi birlikte, yavaş yavaş okuyalım."},{"s":"Lina","en":"Thanks, Mum. I feel a bit better.","tr":"Teşekkürler anne. Biraz daha iyi hissediyorum."},{"s":"Mum","en":"Good! Now, go to bed early tonight.","tr":"Güzel! Şimdi bu gece erken yat."},{"s":"Lina","en":"OK. Good night, Mum!","tr":"Tamam. İyi geceler anne!"}]},{"title":"Study break","setting":"Kütüphanede Burak ve Kerem sınav için mola veriyor.","lines":[{"s":"Burak","en":"I've studied for five hours. My head hurts!","tr":"Beş saattir çalışıyorum. Kafam ağrıyor!"},{"s":"Kerem","en":"You need a break. Stand up and stretch.","tr":"Mola vermelisin. Kalk ve esne."},{"s":"Burak","en":"Good idea. Then I'll listen to some music.","tr":"İyi fikir. Sonra biraz müzik dinleyeceğim."},{"s":"Kerem","en":"Don't worry too much. Small steps help.","tr":"Çok endişelenme. Küçük adımlar yardımcı olur."},{"s":"Burak","en":"You're right. I'll study for twenty minutes now.","tr":"Haklısın. Şimdi yirmi dakika çalışacağım."},{"s":"Kerem","en":"Let's do it together! Ready?","tr":"Birlikte yapalım! Hazır mısın?"},{"s":"Burak","en":"Ready!","tr":"Hazırım!"}]},{"title":"Talking to the teacher","setting":"Öğretmen Ayşe Hanım, endişeli öğrenci Defne ile konuşuyor.","lines":[{"s":"Defne","en":"Can I talk to you? I'm worried about the exam.","tr":"Sizinle konuşabilir miyim? Sınav yüzünden endişeliyim."},{"s":"Teacher","en":"Of course, Defne. What's the problem?","tr":"Tabii Defne. Sorun nedir?"},{"s":"Defne","en":"I don't sleep well. I think about the test all night.","tr":"İyi uyuyamıyorum. Bütün gece sınavı düşünüyorum."},{"s":"Teacher","en":"That's normal. Let's make a study plan.","tr":"Bu normal. Hadi bir çalışma planı yapalım."},{"s":"Defne","en":"Can we make it small and simple?","tr":"Küçük ve basit yapabilir miyiz?"},{"s":"Teacher","en":"Yes! Three topics a day, then rest.","tr":"Evet! Günde üç konu, sonra dinlenme."},{"s":"Defne","en":"Thank you. That makes me feel calmer.","tr":"Teşekkürler. Bu beni daha sakin hissettiriyor."}]}],"reading":{"title":"Calm before the exam","paras":[{"en":"Many students feel stressed before an exam. Stress can make your heart beat fast and your hands shake. Try these simple tips: breathe slowly for one minute, study in short blocks, and take a walk after each block. Sleep well the night before. Your brain needs rest to remember things. Remember, one test does not decide your whole future!","tr":"Birçok öğrenci sınavdan önce stresli hisseder. Stres kalbinizin hızlı atmasına ve ellerinizin titremesine neden olabilir. Şu basit ipuçlarını deneyin: bir dakika yavaş nefes alın, kısa bloklar hâlinde çalışın ve her bloktan sonra biraz yürüyün. Sınavdan önceki gece iyi uyuyun. Beyniniz şeyleri hatırlamak için dinlenmeye ihtiyaç duyar. Unutmayın, tek bir sınav bütün geleceğinize karar vermez!"}]},"vocab":[{"w":"nervous","ipa":"/ˈnɜːvəs/","pos":"😬","tr":"gergin","ex":"I'm nervous before the test.","exTr":"Sınavdan önce gerginim."},{"w":"exam","ipa":"/ɪɡˈzæm/","pos":"📝","tr":"sınav","ex":"The exam is on Monday.","exTr":"Sınav pazartesi."},{"w":"stressed","ipa":"/strest/","pos":"😫","tr":"stresli","ex":"Don't feel stressed!","exTr":"Stresli hissetme!"},{"w":"breathe","ipa":"/briːð/","pos":"🫁","tr":"nefes almak","ex":"Breathe slowly and relax.","exTr":"Yavaşça nefes al ve rahatla."},{"w":"break","ipa":"/breɪk/","pos":"☕","tr":"mola","ex":"Let's take a short break.","exTr":"Kısa bir mola verelim."},{"w":"worried","ipa":"/ˈwʌrid/","pos":"😟","tr":"endişeli","ex":"Don't be worried.","exTr":"Endişelenme."},{"w":"calm","ipa":"/kɑːm/","pos":"😌","tr":"sakin","ex":"I feel calm now.","exTr":"Şimdi kendimi sakin hissediyorum."},{"w":"remember","ipa":"/rɪˈmembə/","pos":"🧠","tr":"hatırlamak","ex":"I can't remember the word.","exTr":"Kelimeyi hatırlayamıyorum."}],"chunks":[{"en":"Take a deep breath.","tr":"Derin bir nefes al."},{"en":"Don't worry too much.","tr":"Çok endişelenme."},{"en":"You're ready.","tr":"Hazırsın."},{"en":"That makes me feel calmer.","tr":"Bu beni daha sakin hissettiriyor."}],"grammar":{"point":"Imperatives (commands and advice)","tr":"Emir kipi, birine bir şey yapmasını söylemek ya da tavsiye vermek için kullanılır. Cümle doğrudan fiille başlar. Olumsuz emir 'Don't' ile kurulur ve fiil yine yalın halde gelir.","examples":["Take a deep breath.","Don't worry too much.","Study in short blocks.","Sleep well tonight."]},"questions":[{"q":"Why is Lina nervous?","a":"Because of the test tomorrow."},{"q":"What does Kerem tell Burak to do?","a":"Stand up and stretch."},{"q":"How long should you breathe slowly, according to the reading?","a":"For one minute."}],"quiz":[{"q":"Which word means 'sınav'?","o":["break","exam","calm"],"a":1,"why":""},{"q":"Take a deep ___.","o":["breath","breathe","breathing"],"a":0,"why":"'Deep breath' sabit bir kalıptır: derin bir nefes."},{"q":"Don't ___ too much.","o":["worrying","worried","worry"],"a":2,"why":"Don't'tan sonra fiil yalın gelir."},{"q":"Which word means 'sakin'?","o":["nervous","calm","stressed"],"a":1,"why":""}],"drills":[{"type":"Yerine koyma","prompt":"Take a deep breath.","cue":"slow","answer":"Take a slow breath."},{"type":"Dönüştürme","prompt":"Worry too much.","cue":"Negative command: Don't…","answer":"Don't worry too much."},{"type":"Genişletme","prompt":"Take a break.","cue":"+ after each block","answer":"Take a break after each block."}],"sounds":[{"focus":"/ɜː/","tr":"Dilini ağzının ortasında tut, sesi uzun ve dengeli çıkar. Türkçedeki kısa ve kesik 'ö' gibi söyleme.","pairs":["shirt / short","bird / bored","work / walk"]}],"mission":{"brief":"Arkadaşın Ece gelecek hafta matematik sınavı olduğu için çok stresli. Claude, Ece olarak konuşacak; onun asıl endişesini bulmak için açık ve şefkatli sorular sor. Sonra ona en az üç rahatlatıcı öneride bulun.","persona":"Ece, a 13-year-old who is stressed about her maths exam next week. She says she is fine and changes the subject often. Hidden fact: she is afraid of failing because her older brother always gets top marks, and she only admits this if the learner asks open, caring questions. Uses short sentences and says 'I don't know' a lot.","goal":"Ece'nin asıl endişesini bul ve ona en az üç öneride bulun.","opener":"Hi. I'm fine, really. Can we talk about something else?"}},"KS3-016":{"objectives":["Görüşünü İngilizce ifade etmek","'I think' ve 'In my opinion' kalıplarını kullanmak","Katılıp katılmadığını nedenleriyle söylemek"],"dialogues":[{"title":"Favourite film","setting":"Teneffüste Selin ile Oğuz yeni filmi konuşuyor.","lines":[{"s":"Selin","en":"Did you watch the new animation film?","tr":"Yeni animasyon filmini izledin mi?"},{"s":"Oğuz","en":"Yes! I think it's really funny.","tr":"Evet! Bence gerçekten çok komik."},{"s":"Selin","en":"Really? I think it's too long.","tr":"Gerçekten mi? Bence çok uzun."},{"s":"Oğuz","en":"In my opinion, the music is amazing.","tr":"Bana göre müzik harika."},{"s":"Selin","en":"I agree. The music is great.","tr":"Katılıyorum. Müzik çok iyi."},{"s":"Oğuz","en":"Why don't you like the ending?","tr":"Sonunu neden beğenmedin?"},{"s":"Selin","en":"Because it's too sad for me.","tr":"Çünkü benim için çok üzücü."}]},{"title":"Phones in class","setting":"Sınıfta öğretmen, öğrencilerin telefonlar hakkındaki görüşünü soruyor.","lines":[{"s":"Teacher","en":"What do you think about phones in class?","tr":"Sınıfta telefonlar hakkında ne düşünüyorsunuz?"},{"s":"Arda","en":"I believe phones are useful for research.","tr":"Bence telefonlar araştırma için faydalı."},{"s":"Ceren","en":"I disagree. They distract us.","tr":"Katılmıyorum. Bizi dikkatimizden uzaklaştırıyorlar."},{"s":"Teacher","en":"Good point, Ceren. Why do you think that?","tr":"İyi bir nokta Ceren. Neden öyle düşünüyorsun?"},{"s":"Ceren","en":"Because I always check messages during lessons.","tr":"Çünkü derslerde her zaman mesajlarıma bakıyorum."},{"s":"Arda","en":"Maybe we need rules, not a ban.","tr":"Belki yasak değil, kurallara ihtiyacımız var."},{"s":"Teacher","en":"Interesting. Write your opinion in two sentences.","tr":"İlginç. Görüşünüzü iki cümleyle yazın."}]},{"title":"Weekend plans","setting":"Cumartesi sabahı Ali ile annesi hafta sonu planını konuşuyor.","lines":[{"s":"Ali","en":"Can we go to the park on Saturday?","tr":"Cumartesi parka gidebilir miyiz?"},{"s":"Mum","en":"What do you think? Should we go to the museum?","tr":"Sence? Müzeye mi gitsek?"},{"s":"Ali","en":"In my view, the park is better. It's sunny!","tr":"Bence park daha iyi. Hava güneşli!"},{"s":"Mum","en":"I see your point. OK, the park it is.","tr":"Haklısın. Tamam, park olsun."},{"s":"Ali","en":"Thanks, Mum! I think we'll have fun.","tr":"Teşekkürler anne! Bence çok eğleneceğiz."}]}],"reading":{"title":"Zeynep's big opinion","paras":[{"en":"Zeynep has an opinion about everything. In her view, school should start later. She thinks students need more sleep. Her friend Kaan disagrees. He believes that longer holidays are more important. They talk about it for hours! Zeynep says that good opinions need good reasons. So she always says 'because'. Do you agree with her?","tr":"Zeynep'in her konuda bir fikri var. Ona göre okul daha geç başlamalı. Öğrencilerin daha fazla uykuya ihtiyacı olduğunu düşünüyor. Arkadaşı Kaan buna katılmıyor. O, daha uzun tatillerin daha önemli olduğuna inanıyor. Saatlerce bunu konuşuyorlar! Zeynep iyi fikirlerin iyi nedenlere ihtiyacı olduğunu söyler. Bu yüzden her zaman 'çünkü' der. Sen onunla aynı fikirde misin?"}]},"vocab":[{"w":"opinion","ipa":"/əˈpɪnjən/","pos":"💭","tr":"görüş, fikir","ex":"What's your opinion?","exTr":"Senin görüşün nedir?"},{"w":"think","ipa":"/θɪŋk/","pos":"🤔","tr":"düşünmek","ex":"I think it's funny.","exTr":"Bence komik."},{"w":"agree","ipa":"/əˈɡriː/","pos":"👍","tr":"katılmak, aynı fikirde olmak","ex":"I agree with you.","exTr":"Seninle aynı fikirdeyim."},{"w":"disagree","ipa":"/ˌdɪsəˈɡriː/","pos":"👎","tr":"katılmamak","ex":"I disagree with that idea.","exTr":"Bu fikre katılmıyorum."},{"w":"useful","ipa":"/ˈjuːsfəl/","pos":"🔧","tr":"faydalı","ex":"This app is useful.","exTr":"Bu uygulama faydalı."},{"w":"distract","ipa":"/dɪˈstrækt/","pos":"📱","tr":"dikkatini dağıtmak","ex":"Phones can distract us.","exTr":"Telefonlar bizim dikkatimizi dağıtabilir."},{"w":"believe","ipa":"/bɪˈliːv/","pos":"💡","tr":"inanmak","ex":"I believe you can do it.","exTr":"Bunu yapabileceğine inanıyorum."},{"w":"reason","ipa":"/ˈriːzən/","pos":"❓","tr":"neden, sebep","ex":"Give me a good reason.","exTr":"Bana iyi bir neden ver."}],"chunks":[{"en":"In my opinion, …","tr":"Bana göre, …"},{"en":"I agree.","tr":"Katılıyorum."},{"en":"I disagree.","tr":"Katılmıyorum."},{"en":"Why do you think that?","tr":"Neden öyle düşünüyorsun?"}],"grammar":{"point":"Giving opinions: I think / In my opinion","tr":"Bir fikri belirtmek için 'I think', 'I believe' ya da 'In my opinion' kullanılır. Bu kalıplardan sonra tam bir cümle gelir. Fikrini desteklemek için 'because' ile bir neden eklemek iyi olur.","examples":["I think it's funny.","In my opinion, the music is great.","I believe school should start later.","I agree, because it is useful."]},"questions":[{"q":"What is Zeynep's opinion about school?","a":"School should start later."},{"q":"Why does Ceren disagree about phones?","a":"Because they distract us."},{"q":"What do good opinions need, according to Zeynep?","a":"Good reasons."}],"quiz":[{"q":"Which phrase means 'Katılıyorum'?","o":["I disagree.","I agree.","I think."],"a":1,"why":""},{"q":"'___, the music is great.' (Bana göre)","o":["In my opinion","Because","Good idea"],"a":0,"why":"'In my opinion' bir fikir başlatır."},{"q":"Phones can ___ us in class.","o":["useful","believe","distract"],"a":2,"why":"Distract = dikkatini dağıtmak."},{"q":"Which word means 'neden'?","o":["agree","reason","opinion"],"a":1,"why":"Reason = neden, sebep."}],"drills":[{"type":"Yerine koyma","prompt":"I think it's funny.","cue":"sad","answer":"I think it's sad."},{"type":"Dönüştürme","prompt":"It is useful.","cue":"In my opinion…","answer":"In my opinion, it is useful."},{"type":"Soru yap","prompt":"You agree with me.","cue":"Do…?","answer":"Do you agree with me?"}],"sounds":[{"focus":"/æ/","tr":"Ağzını geniş aç ve dilini aşağıda tut. Türkçedeki 'e' sesine kaçma; 'bad' ile 'bed' birbirinden ayrılmalı.","pairs":["bad / bed","man / men","hat / hut"]}],"mission":{"brief":"Arkadaşın Berk, telefonların sınıfta serbest olması gerektiğini düşünüyor. Claude, Berk olarak konuşacak; sen kendi görüşünü 'I think' ya da 'In my opinion' ile söyle ve nedenini açıkla. Berk'in asıl düşüncesini öğrenmek için sorular sor.","persona":"Berk, a 13-year-old who thinks phones should be allowed in class for learning. He sounds confident and sometimes disagrees. Hidden fact: he is secretly worried about being left out of the group chat, and he only admits this if the learner asks good 'why' questions. Speaks briefly.","goal":"Berk'in asıl nedenini öğren ve ona kendi görüşünü iki nedenle açıkla.","opener":"I think phones should be allowed in class. What do you think?"}},"KS3-017":{"objectives":["Bir tartışmada görüşünü ve nedenlerini sıralamak","'First', 'Also', 'However' gibi bağlaçlarla fikirleri bağlamak","Karşı argümana kibarca cevap vermek"],"dialogues":[{"title":"Preparing the motion","setting":"Okul tartışma kulübünde Deniz ile Emir konuyu hazırlıyor.","lines":[{"s":"Deniz","en":"Our motion is: 'Schools should have shorter lessons.'","tr":"Konumuz: 'Okullar daha kısa dersler yapmalı.'"},{"s":"Emir","en":"Great. Which side are we on?","tr":"Harika. Hangi tarafta olacağız?"},{"s":"Deniz","en":"We're on the 'for' side. Let's argue for it.","tr":"'Lehte' tarafındayız. Lehinde savunalım."},{"s":"Emir","en":"First, students get tired after long lessons.","tr":"Birincisi, öğrenciler uzun derslerden sonra yoruluyor."},{"s":"Deniz","en":"Also, shorter lessons give us more time for sport.","tr":"Ayrıca, daha kısa dersler bize spor için daha fazla zaman verir."},{"s":"Emir","en":"Nice! Let's write these points down.","tr":"Güzel! Bu noktaları yazalım."},{"s":"Deniz","en":"Good. We'll win with clear reasons.","tr":"İyi. Net nedenlerle kazanacağız."}]},{"title":"The rebuttal","setting":"Tartışmada karşı takımdan Ayşe, Deniz'in argümanına cevap veriyor.","lines":[{"s":"Ayşe","en":"Deniz, I disagree. Shorter lessons mean less learning.","tr":"Deniz, katılmıyorum. Daha kısa dersler daha az öğrenme demek."},{"s":"Deniz","en":"However, we can learn faster with breaks.","tr":"Ancak molalarla daha hızlı öğrenebiliriz."},{"s":"Ayşe","en":"That's true, but we also lose important topics.","tr":"Bu doğru, ama önemli konuları da kaçırırız."},{"s":"Deniz","en":"Fair point. But we can add extra clubs after school.","tr":"Haklısın. Ama okuldan sonra ek kulüpler açabiliriz."},{"s":"Ayşe","en":"Hmm. I'm not convinced, but it's a good idea.","tr":"Hmm. İkna olmadım ama iyi bir fikir."},{"s":"Deniz","en":"Thanks! That's the best compliment I've had today.","tr":"Teşekkürler! Bugün aldığım en güzel iltifat bu."}]},{"title":"The final round","setting":"Tartışmanın sonunda öğretmen oylara bakıyor.","lines":[{"s":"Teacher","en":"Finally, let's hear the votes. Who won?","tr":"Son olarak oylara bakalım. Kim kazandı?"},{"s":"Kerem","en":"I think Deniz's team had the best arguments.","tr":"Bence Deniz'in takımı en iyi argümanlara sahipti."},{"s":"Ayşe","en":"I agree. They had clear reasons.","tr":"Katılıyorum. Net nedenleri vardı."},{"s":"Teacher","en":"The winner is Deniz's team! Well done, everyone.","tr":"Kazanan Deniz'in takımı! Herkese tebrikler."},{"s":"Kerem","en":"Next time, we'll do even better!","tr":"Bir dahaki sefere daha da iyi yapacağız!"}]}],"reading":{"title":"How to win a debate","paras":[{"en":"A school debate has two teams. The 'for' team supports the motion, and the 'against' team argues the opposite. Each speaker has two minutes. First, state your point clearly. Then give a reason and an example. Listen carefully, because you can rebut the other team's points. Finally, be polite, even when you disagree. Good speakers win respect, not only votes.","tr":"Okul tartışmasında iki takım vardır. 'Lehte' takım konuyu destekler, 'aleyhte' takım ise tersini savunur. Her konuşmacının iki dakikası vardır. Birincisi, görüşünüzü net bir şekilde söyleyin. Sonra bir neden ve bir örnek verin. Dikkatle dinleyin, çünkü diğer takımın noktalarına cevap verebilirsiniz. Son olarak, katılmadığınızda bile kibar olun. İyi konuşmacılar sadece oy değil, saygı kazanır."}]},"vocab":[{"w":"debate","ipa":"/dɪˈbeɪt/","pos":"🎤","tr":"tartışma (münazara)","ex":"Our school debate is on Friday.","exTr":"Okul tartışmamız cuma günü."},{"w":"motion","ipa":"/ˈməʊʃn/","pos":"📜","tr":"tartışma konusu, öneri","ex":"The motion is about homework.","exTr":"Konu ödevle ilgili."},{"w":"argue","ipa":"/ˈɑːɡjuː/","pos":"💬","tr":"savunmak, tartışmak","ex":"We will argue for shorter lessons.","exTr":"Daha kısa dersler için savunacağız."},{"w":"rebut","ipa":"/rɪˈbʌt/","pos":"🥊","tr":"karşı argümanla cevap vermek","ex":"I can rebut that point easily.","exTr":"Bu noktaya kolayca cevap verebilirim."},{"w":"team","ipa":"/tiːm/","pos":"👥","tr":"takım","ex":"Our team has three speakers.","exTr":"Takımımızda üç konuşmacı var."},{"w":"point","ipa":"/pɔɪnt/","pos":"📌","tr":"nokta, argüman","ex":"That's a good point.","exTr":"Bu iyi bir nokta."},{"w":"vote","ipa":"/vəʊt/","pos":"✋","tr":"oy (vermek)","ex":"Everyone can vote.","exTr":"Herkes oy verebilir."},{"w":"convinced","ipa":"/kənˈvɪnst/","pos":"🤝","tr":"ikna olmuş","ex":"I'm not convinced yet.","exTr":"Henüz ikna olmadım."}],"chunks":[{"en":"Let's argue for it.","tr":"Lehinde savunalım."},{"en":"That's a fair point.","tr":"Haklısın."},{"en":"I'm not convinced.","tr":"İkna olmadım."},{"en":"Well done, everyone!","tr":"Herkese tebrikler!"}],"grammar":{"point":"Linking words: first, also, however, finally","tr":"Fikirlerin sırasını göstermek için 'First', 'Also', 'However' ve 'Finally' gibi bağlaçlar kullanılır. Bunlar genellikle cümlenin başında gelir ve virgülle ayrılır. 'However' karşıt bir fikir getirir ve 'ama, ancak' anlamına gelir.","examples":["First, students get tired.","Also, sport needs time.","However, we can learn with breaks.","Finally, be polite."]},"questions":[{"q":"How long does each speaker have?","a":"Two minutes."},{"q":"What does the 'against' team do?","a":"They argue the opposite."},{"q":"What does Ayşe say about shorter lessons?","a":"They mean less learning."}],"quiz":[{"q":"Which word means 'konu' in a debate?","o":["motion","vote","team"],"a":0,"why":"Motion = tartışılan öneri, konu."},{"q":"'However' means…","o":["sonunda","ama, ancak","ayrıca"],"a":1,"why":""},{"q":"We can ___ the other team's point with an example.","o":["vote","point","rebut"],"a":2,"why":"Rebut = karşı argüman sunmak."},{"q":"Which word means 'takım'?","o":["vote","team","point"],"a":1,"why":""}],"drills":[{"type":"Yerine koyma","prompt":"First, sport is important.","cue":"Finally","answer":"Finally, sport is important."},{"type":"Soru yap","prompt":"We can learn faster with breaks.","cue":"Can…?","answer":"Can we learn faster with breaks?"},{"type":"Genişletme","prompt":"Our team wins.","cue":"+ with clear reasons","answer":"Our team wins with clear reasons."}],"sounds":[{"focus":"/əʊ/","tr":"Türkçede 'o' tek bir ses, ama İngilizcede /əʊ/ iki parçalıdır: önce yumuşak bir 'ə', sonra dudaklar 'ʊ' yönünde kapanır. Tek ve sabit 'o' gibi söyleme.","pairs":["vote / vet","note / net","coat / cot"]}],"mission":{"brief":"Okul tartışma kulübünde 'Okullarda ödev kaldırılmalı' konusu tartışılacak. Claude, karşı takımdan Ayşe olarak konuşacak; sen lehte savunmasını yap ve argümanlarını 'First', 'Also' ve 'Finally' ile sırala. Ayşe'nin asıl itirazını bulmak için sorular sor.","persona":"Ayşe, a confident 14-year-old debater arguing against the motion that homework should be banned. She speaks politely but pushes back on weak points. Hidden fact: her real concern is that she practises piano every evening and has no time for homework, and she only reveals this if the learner asks thoughtful questions about her own schedule. Uses short, precise sentences.","goal":"Ayşe'nin asıl itirazını öğren ve ona üç nedenle cevap ver.","opener":"I disagree with your motion. Homework helps us learn. What's your first reason?"}},"KS3-018":{"objectives":["Ünlü mucitleri ve icatlarını İngilizce anlatmak","Geçmiş zamanda (Past Simple) olayları anlatmak","Bir kişinin hayatı hakkında soru sormak"],"dialogues":[{"title":"At the science museum","setting":"Bilim müzesinde Ela ile babası bir mucidin resmine bakıyor.","lines":[{"s":"Ela","en":"Look, Dad! Who is this man?","tr":"Bak baba! Bu adam kim?"},{"s":"Dad","en":"That's Thomas Edison. He invented the light bulb.","tr":"O Thomas Edison. Ampulü icat etti."},{"s":"Ela","en":"Wow! When did he live?","tr":"Vay! Ne zaman yaşadı?"},{"s":"Dad","en":"He lived in the 1800s. He worked very hard.","tr":"1800'lerde yaşadı. Çok çalıştı."},{"s":"Ela","en":"Did he make many mistakes?","tr":"Çok hata yaptı mı?"},{"s":"Dad","en":"Yes, he tried thousands of times before he succeeded.","tr":"Evet, başarmadan önce binlerce kez denedi."},{"s":"Ela","en":"Thousands? That's amazing!","tr":"Binlerce mi? Bu inanılmaz!"}]},{"title":"Science project","setting":"Fen projesi için Can ile Mina, bir kadın bilim insanını konuşuyor.","lines":[{"s":"Can","en":"I'm writing about Marie Curie. Do you know her?","tr":"Marie Curie hakkında yazıyorum. Onu tanıyor musun?"},{"s":"Mina","en":"Yes! She discovered radium. She won two Nobel prizes.","tr":"Evet! Radyumu keşfetti. İki Nobel ödülü kazandı."},{"s":"Can","en":"Two? I didn't know that!","tr":"İki mi? Bunu bilmiyordum!"},{"s":"Mina","en":"She was the first woman to win one.","tr":"Bir tane kazanan ilk kadındı."},{"s":"Can","en":"Good. I'll add that to my slides.","tr":"İyi. Bunu slaytlarıma ekleyeceğim."},{"s":"Mina","en":"Let me check the dates for you.","tr":"Tarihlere senin için bir bakayım."},{"s":"Can","en":"Thanks, Mina. You're a great partner!","tr":"Teşekkürler Mina. Harika bir ortaksın!"}]},{"title":"My invention idea","setting":"Okul bahçesinde Efe ile Selin, Efe'nin icat fikrini konuşuyor.","lines":[{"s":"Efe","en":"I want to invent a robot that cleans my room!","tr":"Odamı temizleyen bir robot icat etmek istiyorum!"},{"s":"Selin","en":"That's a brilliant idea. How will it work?","tr":"Bu harika bir fikir. Nasıl çalışacak?"},{"s":"Efe","en":"It will pick up my clothes and put them away.","tr":"Kıyafetlerimi toplayacak ve yerlerine koyacak."},{"s":"Selin","en":"Did you draw a plan?","tr":"Bir plan çizdin mi?"},{"s":"Efe","en":"Not yet. I'll draw it tonight.","tr":"Henüz değil. Bu gece çizeceğim."},{"s":"Selin","en":"Let me know when it's ready. I want to test it!","tr":"Hazır olunca haber ver. Test etmek istiyorum!"}]}],"reading":{"title":"Inventors who never gave up","paras":[{"en":"Many famous inventors worked hard for years. Thomas Edison was born in 1847. He invented the light bulb in 1879, but he tested thousands of materials first. Marie Curie studied radioactivity and won two Nobel prizes. Alexander Graham Bell invented the telephone in 1876. These people did not give up. They tried, failed and tried again, and that is why we have their ideas today.","tr":"Birçok ünlü mucit yıllarca çok çalıştı. Thomas Edison 1847'de doğdu. 1879'da ampulü icat etti, ama önce binlerce malzemeyi denedi. Marie Curie radyoaktiviteyi inceledi ve iki Nobel ödülü kazandı. Alexander Graham Bell telefonu 1876'da icat etti. Bu insanlar pes etmedi. Denediler, başarısız oldular ve yeniden denediler. Bu yüzden bugün onların fikirlerine sahibiz."}]},"vocab":[{"w":"inventor","ipa":"/ɪnˈventə/","pos":"🧑‍🔬","tr":"mucit","ex":"Edison was a great inventor.","exTr":"Edison harika bir mucitti."},{"w":"invent","ipa":"/ɪnˈvent/","pos":"💡","tr":"icat etmek","ex":"He invented the light bulb.","exTr":"Ampulü icat etti."},{"w":"discover","ipa":"/dɪˈskʌvə/","pos":"🔍","tr":"keşfetmek","ex":"Curie discovered radium.","exTr":"Curie radyumu keşfetti."},{"w":"succeed","ipa":"/səkˈsiːd/","pos":"✅","tr":"başarmak","ex":"He finally succeeded.","exTr":"Sonunda başardı."},{"w":"prize","ipa":"/praɪz/","pos":"🥇","tr":"ödül","ex":"She won a Nobel prize.","exTr":"Bir Nobel ödülü kazandı."},{"w":"give up","ipa":"/ɡɪv ʌp/","pos":"🛑","tr":"pes etmek","ex":"Never give up!","exTr":"Asla pes etme!"},{"w":"brilliant","ipa":"/ˈbrɪliənt/","pos":"🌟","tr":"harika, parlak","ex":"That's a brilliant idea!","exTr":"Bu harika bir fikir!"},{"w":"plan","ipa":"/plæn/","pos":"📐","tr":"plan, çizim","ex":"Did you draw a plan?","exTr":"Bir plan çizdin mi?"}],"chunks":[{"en":"Let me know when it's ready.","tr":"Hazır olunca haber ver."},{"en":"Let me check.","tr":"Bir bakayım."},{"en":"That's amazing!","tr":"Bu inanılmaz!"},{"en":"You're a great partner!","tr":"Harika bir ortaksın!"}],"grammar":{"point":"Past Simple: regular and irregular verbs","tr":"Geçmişte bitmiş olayları anlatmak için Past Simple kullanılır. Düzenli fiillere '-ed' eklenir, örneğin 'tried' ve 'lived'. Düzensiz fiillerin ise kendi özel biçimleri vardır, örneğin 'won' ve 'made'.","examples":["He invented the light bulb.","She won two Nobel prizes.","They tried again and again.","Edison was born in 1847."]},"questions":[{"q":"When was Thomas Edison born?","a":"In 1847."},{"q":"What did Marie Curie win?","a":"Two Nobel prizes."},{"q":"What did the inventors do when they failed?","a":"They tried again."}],"quiz":[{"q":"Which word means 'icat etmek'?","o":["invent","discover","succeed"],"a":0,"why":""},{"q":"Marie Curie ___ two Nobel prizes.","o":["win","won","wins"],"a":1,"why":"Geçmişte 'won' kullanılır, çünkü düzensiz bir fiildir."},{"q":"Which word means 'harika'?","o":["plan","prize","brilliant"],"a":2,"why":""},{"q":"Which word means 'pes etmek'?","o":["succeed","give up","discover"],"a":1,"why":""}],"drills":[{"type":"Yerine koyma","prompt":"He invented the light bulb.","cue":"telephone","answer":"He invented the telephone."},{"type":"Dönüştürme","prompt":"She won two prizes.","cue":"Negative (didn't)","answer":"She didn't win two prizes."},{"type":"Soru yap","prompt":"They tried again.","cue":"Did…?","answer":"Did they try again?"}],"sounds":[{"focus":"/ɪ/ – /iː/","tr":"Türkçede tek 'i' sesi var; İngilizcede kısa /ɪ/ gevşek ve kısa söylenir, uzun /iː/ ise dilini öne çekip uzatılır. Hepsini uzun 'i' gibi söyleme.","pairs":["live / leave","ship / sheep","bit / beat"]}],"mission":{"brief":"Okul projen için ünlü bir mucitle röportaj yapıyorsun. Claude, emekli mucit Dr. Lena Park olarak konuşacak; sen ona 'When', 'What' ve 'Did' ile geçmiş zaman soruları sor. Dr. Park'ın hikâyesindeki gizli zorluğu bulmaya çalış.","persona":"Dr. Lena Park, a friendly retired inventor in her seventies. She speaks slowly, warmly and loves telling stories about her past. Hidden fact: her famous invention, a solar lamp, failed more than 200 times, and she almost gave up until her sister encouraged her. She reveals this only when the learner asks follow-up questions about difficulties.","goal":"Dr. Park'ın gizli zorluğunu öğren ve geçmiş zamanla en az üç soru sor.","opener":"Hello! Welcome to my workshop. What would you like to know about my inventions?"}},"KS3-019":{"objectives":["Uzayla ilgili kelimeleri İngilizce kullanmak","'be going to' ile plan ve tahminleri anlatmak","Bir planı kısa cümlelerle önermek"],"dialogues":[{"title":"Rocket day at space camp","setting":"Uzay kampında Ege ile Nil yarınki roket etkinliğini planlıyor.","lines":[{"s":"Ege","en":"Tomorrow we're going to launch a rocket!","tr":"Yarın bir roket fırlatacağız!"},{"s":"Nil","en":"Are we going to build it ourselves?","tr":"Onu kendimiz mi yapacağız?"},{"s":"Ege","en":"Yes, with our teacher. We're going to use water power.","tr":"Evet, öğretmenimizle. Su gücü kullanacağız."},{"s":"Nil","en":"Cool! What's the mission?","tr":"Harika! Görev ne?"},{"s":"Ege","en":"We're going to measure how high it flies.","tr":"Ne kadar yükseğe uçtuğunu ölçeceğiz."},{"s":"Nil","en":"I'm going to count the seconds!","tr":"Ben saniyeleri sayacağım!"},{"s":"Ege","en":"Great team! Let's start.","tr":"Harika bir takım! Hadi başlayalım."}]},{"title":"Waiting for the astronaut","setting":"Okul kütüphanesinde Mina ile Burak, astronot konuşmasını bekliyor.","lines":[{"s":"Mina","en":"Is the astronaut going to talk about Mars?","tr":"Astronot Mars hakkında konuşacak mı?"},{"s":"Burak","en":"Yes, she's going to show us photos!","tr":"Evet, bize fotoğraflar gösterecek!"},{"s":"Mina","en":"Oh good. I'm going to ask about food in space.","tr":"Ah güzel. Uzayda yemek hakkında soru soracağım."},{"s":"Burak","en":"Don't worry, it's going to be a short talk.","tr":"Endişelenme, kısa bir konuşma olacak."},{"s":"Mina","en":"OK. I'll ask only one question.","tr":"Tamam. Sadece bir soru soracağım."},{"s":"Burak","en":"Good plan. Let's sit near the front.","tr":"İyi plan. Öne yakın oturalım."}]},{"title":"The future of space","setting":"Fen dersinde öğretmen, öğrencilere gelecekteki uzay görevlerini soruyor.","lines":[{"s":"Teacher","en":"What are we going to see in the future?","tr":"Gelecekte neler göreceğiz?"},{"s":"Cem","en":"I think people will visit Mars one day.","tr":"Bence insanlar bir gün Mars'ı ziyaret edecek."},{"s":"Ada","en":"I believe we're going to build homes on the Moon!","tr":"Bence Ay'da evler inşa etmeye başlayacağız!"},{"s":"Teacher","en":"Interesting! What do you need to do first?","tr":"İlginç! İlk önce ne yapman gerekir?"},{"s":"Cem","en":"Study hard. Space needs scientists.","tr":"Çok çalışmak. Uzay bilim insanlarına ihtiyaç duyar."},{"s":"Ada","en":"And we're going to dream big!","tr":"Ve büyük hayaller kuracağız!"}]}],"reading":{"title":"Missions to space","paras":[{"en":"Space missions are going to change our world. Next year, a new spacecraft is going to visit Mars. Scientists are going to look for water there. Astronauts are going to live on the Moon too, in small bases. Some students will become engineers, and they will build the rockets. Who knows? You might be the next astronaut!","tr":"Uzay görevleri dünyamızı değiştirecek. Gelecek yıl, yeni bir uzay aracı Mars'ı ziyaret edecek. Bilim insanları orada su aramaya başlayacak. Astronotlar da Ay'da küçük üslerde yaşayacak. Bazı öğrenciler mühendis olacak ve roketleri onlar yapacak. Kim bilir? Belki bir sonraki astronot sen olursun!"}]},"vocab":[{"w":"astronaut","ipa":"/ˈæstrənɔːt/","pos":"👨‍🚀","tr":"astronot","ex":"The astronaut waves at us.","exTr":"Astronot bize el sallıyor."},{"w":"rocket","ipa":"/ˈrɒkɪt/","pos":"🚀","tr":"roket","ex":"Our rocket is red and tall.","exTr":"Roketimiz kırmızı ve uzun."},{"w":"launch","ipa":"/lɔːntʃ/","pos":"🔥","tr":"fırlatmak","ex":"We will launch it at noon.","exTr":"Onu öğlen fırlatacağız."},{"w":"mission","ipa":"/ˈmɪʃn/","pos":"🎯","tr":"görev","ex":"This mission is going to be fun.","exTr":"Bu görev eğlenceli olacak."},{"w":"spacecraft","ipa":"/ˈspeɪskrɑːft/","pos":"🛸","tr":"uzay aracı","ex":"The spacecraft is very fast.","exTr":"Uzay aracı çok hızlı."},{"w":"engineer","ipa":"/ˌendʒɪˈnɪə/","pos":"🔧","tr":"mühendis","ex":"My cousin is an engineer.","exTr":"Kuzenim bir mühendis."},{"w":"scientist","ipa":"/ˈsaɪəntɪst/","pos":"🔬","tr":"bilim insanı","ex":"Scientists look for water.","exTr":"Bilim insanları su arıyor."},{"w":"dream","ipa":"/driːm/","pos":"✨","tr":"hayal, hayal kurmak","ex":"Dream big!","exTr":"Büyük hayaller kur!"}],"chunks":[{"en":"We're going to launch it!","tr":"Onu fırlatacağız!"},{"en":"Let's start.","tr":"Hadi başlayalım."},{"en":"Good plan!","tr":"İyi plan!"},{"en":"Dream big!","tr":"Büyük hayaller kur!"}],"grammar":{"point":"be going to (plans and predictions)","tr":"Önceden kararlaştırılmış bir planı ya da ileride olacağı düşünülen bir şeyi anlatmak için 'be going to' kullanılır. 'am', 'is' ya da 'are' ile birlikte fiil yalın hâlde gelir. Türkçedeki '-acak / -ecek' ekiyle aynı anlama gelir.","examples":["We're going to launch a rocket.","She's going to show us photos.","I'm going to count the seconds.","They're going to build homes on the Moon."]},"questions":[{"q":"What are Ege and Nil going to measure?","a":"How high the rocket flies."},{"q":"What is the astronaut going to show?","a":"Photos."},{"q":"What will some students become, according to the reading?","a":"Engineers."}],"quiz":[{"q":"Which word means 'uzay aracı'?","o":["rocket","spacecraft","engineer"],"a":1,"why":""},{"q":"We ___ going to build a rocket.","o":["am","is","are"],"a":2,"why":"'We' ile 'are' kullanılır."},{"q":"Which word means 'görev'?","o":["mission","launch","dream"],"a":0,"why":""},{"q":"Which word means 'bilim insanı'?","o":["engineer","astronaut","scientist"],"a":2,"why":""}],"drills":[{"type":"Yerine koyma","prompt":"We're going to launch a rocket.","cue":"spacecraft","answer":"We're going to launch a spacecraft."},{"type":"Dönüştürme","prompt":"She shows us photos.","cue":"future plan with 'going to'","answer":"She's going to show us photos."},{"type":"Soru yap","prompt":"They're going to build homes on the Moon.","cue":"Are…?","answer":"Are they going to build homes on the Moon?"}],"sounds":[{"focus":"/ʃ/","tr":"Türkçedeki 'ş' ile aynı sestir, ama zor olan 'sh' harflerini gördüğünde bunu 's' gibi okumamaktır. Dudaklarını hafifçe öne uzat.","pairs":["ship / sip","wash / was","shine / sign"]}],"mission":{"brief":"Uzay kampında ekip arkadaşın Yusuf, roket planını yetiştirmekte zorlanıyor. Claude, Yusuf olarak konuşacak; sen ona sorular sorarak asıl sorununu bul. Sonra 'going to' kalıbıyla bir sonraki adım için plan yapın.","persona":"Yusuf, a 13-year-old teammate at space camp who seems confident but is behind on the rocket design. Hidden fact: he is afraid to ask for help because he thinks his teammates will laugh at his drawings, and he only admits this if the learner asks kind, open questions. Speaks in short sentences and says 'It's fine' a lot.","goal":"Yusuf'un asıl sorununu bul ve 'going to' ile bir sonraki adım için plan yap.","opener":"Hi. The rocket plan is fine, I think. Everything is going to be OK."}},"KS3-020":{"objectives":["Gönüllülük fırsatlarını İngilizce anlatmak","Bir etkinliğe katılmak için kısa cümleler kurmak","'I can help with…' kalıbıyla yardım teklif etmek"],"dialogues":[{"title":"Sign-up day","setting":"Okul panosunda bir gönüllülük listesi var. Ada ve Mert hangi etkinliğe katılacaklarına karar veriyor.","lines":[{"s":"Ada","en":"Look, Mert! There's a volunteer sheet for the animal shelter.","tr":"Bak Mert! Hayvan barınağı için bir gönüllü listesi var."},{"s":"Mert","en":"Cool. What do they need?","tr":"Harika. Neye ihtiyaçları var?"},{"s":"Ada","en":"People to walk the dogs and clean the cages on Saturdays.","tr":"Cumartesileri köpekleri gezdirecek ve kafesleri temizleyecek insanlar."},{"s":"Mert","en":"I can help with walking the dogs. I love dogs!","tr":"Köpekleri gezdirmeye yardım edebilirim. Köpekleri çok severim!"},{"s":"Ada","en":"Great! Let's sign up together.","tr":"Harika! Birlikte kaydolalım."},{"s":"Mert","en":"Do we need a parent's permission?","tr":"Bir velinin iznine ihtiyacımız var mı?"},{"s":"Ada","en":"Yes, but it's easy. Our parents can sign the form tonight.","tr":"Evet, ama kolay. Anne babalarımız formu bu akşam imzalayabilir."}]},{"title":"Calling the shelter","setting":"Ada, barınağın görevlisi Selin'i telefonda arıyor ve gönüllü olmak istediğini söylüyor.","lines":[{"s":"Ada","en":"Hello, is that the animal shelter?","tr":"Alo, orası hayvan barınağı mı?"},{"s":"Selin","en":"Yes, it is. How can I help you?","tr":"Evet, öyle. Size nasıl yardımcı olabilirim?"},{"s":"Ada","en":"I'd like to volunteer on Saturdays. Is there a form?","tr":"Cumartesileri gönüllü olmak istiyorum. Bir form var mı?"},{"s":"Selin","en":"Yes. Fill in the form online and bring a signed letter from a parent.","tr":"Evet. Formu çevrimiçi doldurun ve bir velinin imzalı mektubunu getirin."},{"s":"Ada","en":"Thanks. Can I start next week?","tr":"Teşekkürler. Gelecek hafta başlayabilir miyim?"},{"s":"Selin","en":"Of course! Our team will be happy to see you.","tr":"Tabii ki! Ekibimiz sizi görmekten mutluluk duyacak."}]},{"title":"First day feedback","setting":"Gönüllülük gününden sonra Mert ve Ada parkta buluşup konuşuyor.","lines":[{"s":"Mert","en":"How was your first shift at the shelter?","tr":"Barınaktaki ilk vardiyan nasıldı?"},{"s":"Ada","en":"It was tiring, but really fun. I helped feed the cats.","tr":"Yorucuydu ama gerçekten eğlenceliydi. Kedilere mama vermeye yardım ettim."},{"s":"Mert","en":"Did you learn anything new?","tr":"Yeni bir şey öğrendin mi?"},{"s":"Ada","en":"Yes. Helping others makes me feel proud.","tr":"Evet. Başkalarına yardım etmek beni gururlandırıyor."},{"s":"Mert","en":"I want to join next Saturday. Can you show me the way?","tr":"Gelecek cumartesi katılmak istiyorum. Bana yolu gösterebilir misin?"},{"s":"Ada","en":"Sure! Meet me at the bus stop at nine.","tr":"Tabii! Dokuzda otobüs durağında buluş."}]}],"reading":{"title":"Helping at the shelter","paras":[{"en":"Ada and Mert are volunteers at the animal shelter in their town. On Saturdays, they walk the dogs and feed the cats. The shelter needs more helpers, so the team is looking for new volunteers. Volunteering helps the community, and it teaches useful skills, such as teamwork and responsibility. Ada says it is the best part of her week.","tr":"Ada ve Mert, kasabalarındaki hayvan barınağında gönüllü olarak çalışıyor. Cumartesileri köpekleri gezdiriyor ve kedilere mama veriyorlar. Barınak daha fazla yardımcıya ihtiyaç duyduğu için ekip yeni gönüllüler arıyor. Gönüllülük topluma yardım eder ve takım çalışması ile sorumluluk gibi işe yarar becerileri öğretir. Ada, bunun haftasının en güzel kısmı olduğunu söylüyor."}]},"vocab":[{"w":"volunteer","ipa":"/ˌvɒlənˈtɪə/","pos":"🙋","tr":"gönüllü","ex":"I want to be a volunteer.","exTr":"Gönüllü olmak istiyorum."},{"w":"shelter","ipa":"/ˈʃeltə/","pos":"🏠","tr":"barınak","ex":"The shelter has ten new dogs.","exTr":"Barınakta on yeni köpek var."},{"w":"feed","ipa":"/fiːd/","pos":"🥣","tr":"beslemek, mama vermek","ex":"I feed the cat every morning.","exTr":"Kediyi her sabah beslerim."},{"w":"team","ipa":"/tiːm/","pos":"🤝","tr":"ekip, takım","ex":"Our team cleans the park.","exTr":"Takımımız parkı temizliyor."},{"w":"proud","ipa":"/praʊd/","pos":"😊","tr":"gururlu","ex":"I feel proud of my brother.","exTr":"Kardeşimle gurur duyuyorum."},{"w":"sign up","ipa":"/ˌsaɪn ˈʌp/","pos":"✍","tr":"kaydolmak","ex":"Please sign up before Friday.","exTr":"Lütfen cumaya kadar kaydol."},{"w":"community","ipa":"/kəˈmjuːnəti/","pos":"🏘","tr":"topluluk","ex":"Our community has a new park.","exTr":"Mahallemizin yeni bir parkı var."},{"w":"useful","ipa":"/ˈjuːsfl/","pos":"🔧","tr":"yararlı, işe yarar","ex":"This book is very useful.","exTr":"Bu kitap çok yararlı."}],"chunks":[{"en":"I can help with…","tr":"…konusunda yardım edebilirim."},{"en":"Let's sign up together.","tr":"Birlikte kaydolalım."},{"en":"Can I start next week?","tr":"Gelecek hafta başlayabilir miyim?"},{"en":"Fill in the form, please.","tr":"Formu doldur, lütfen."}],"grammar":{"point":"Can for ability and offers","tr":"'Can' bir şeyi yapabildiğimizi ya da yardım teklif ettiğimizi anlatır. 'Can' ile fiil her zaman aynı kalır: 'I can help', 'She can swim'. Olumsuzu 'can't' ile yapılır.","examples":["I can help with the cats.","She can walk the dogs.","We can't come on Saturday.","Can you show me the way?"]},"questions":[{"q":"What do Ada and Mert do on Saturdays?","a":"They walk the dogs and feed the cats."},{"q":"What does Mert want to do next Saturday?","a":"He wants to join the volunteers at the shelter."},{"q":"Who must sign the letter for a student volunteer?","a":"A parent must sign it."}],"quiz":[{"q":"Ada helped to feed the ___ at the shelter.","o":["dogs","cats","birds"],"a":1,"why":"Ada kedilere mama vermeye yardım etti."},{"q":"Mert wants to ___ the volunteer team.","o":["join","leave","forget"],"a":0,"why":"Join = katılmak."},{"q":"I can help ___ walking the dogs.","o":["on","to","with"],"a":2,"why":"Help with = bir işte yardım etmek."},{"q":"Ada feels ___ after helping others.","o":["sad","proud","bored"],"a":1,"why":"Proud = gururlu."}],"drills":[{"type":"Yerine koyma","prompt":"I can help with walking the dogs.","cue":"cleaning the cages","answer":"I can help with cleaning the cages."},{"type":"Dönüştürme","prompt":"We can come on Saturday.","cue":"olumsuz yap (can't)","answer":"We can't come on Saturday."},{"type":"Soru yap","prompt":"You can show me the way.","cue":"Can…?","answer":"Can you show me the way?"}],"sounds":[{"focus":"/ɪ/ – /iː/","tr":"Türkçede 'i' sesi hep aynı uzunlukta çıkar, bu yüzden İngilizcedeki kısa ve uzun 'i' karışır. Kısa /ɪ/ için dilini gevşek tut ve sesi kısa bırak; uzun /iː/ için dudaklarını yana çekip sesi uzat.","pairs":["ship / sheep","sit / seat","live / leave"]}],"mission":{"brief":"Bir hayvan barınağında gönüllü olmak istiyorsun. Claude, barınağın gönüllü koordinatörü Selin'i oynayacak; ona hangi günlerde ve hangi işte yardım edebileceğini anlatıp açık vardiyaları öğrenmelisin.","persona":"Selin, the volunteer coordinator at a city animal shelter. Warm, organised and a bit busy; she speaks in short, clear sentences. Hidden fact: the shelter urgently needs someone on Sunday mornings for dog walks, but she only mentions this if the learner asks about open shifts or free days.","goal":"Selin'e hangi günlerde ve hangi işte yardım edebileceğini söyle ve açık bir vardiya öğren.","opener":"Hello! Thanks for calling the shelter. Are you interested in volunteering with us?"}},"KS3-021":{"objectives":["Bir tarifin malzemelerini ve adımlarını İngilizce anlatmak","Yemek hakkında arkadaşınla kısa konuşmalar yapmak","Talimat veren cümleleri (imperative) doğru kurmak"],"dialogues":[{"title":"Choosing a recipe","setting":"Pazar sabahı mutfakta Zara ve annesi kahvaltı için bir tarif seçiyor.","lines":[{"s":"Zara","en":"Mum, can we cook something fun on Sunday?","tr":"Anne, pazar günü eğlenceli bir şey pişirebilir miyiz?"},{"s":"Mum","en":"Sure! Let's try this recipe for pancakes.","tr":"Tabii! Şu pankek tarifini deneyelim."},{"s":"Zara","en":"What are the ingredients?","tr":"Malzemeler neler?"},{"s":"Mum","en":"Flour, eggs, milk and a little sugar.","tr":"Un, yumurta, süt ve biraz şeker."},{"s":"Zara","en":"Easy! Let's mix everything in a big bowl.","tr":"Kolay! Her şeyi büyük bir kâsede karıştıralım."},{"s":"Mum","en":"Good idea. Use the small pan, not the big one.","tr":"İyi fikir. Büyük tavayı değil, küçük tavayı kullan."}]},{"title":"Asking a friend for help","setting":"Kerem mutfakta tarifi takip ederken arkadaşı Zara'yı telefonda arıyor.","lines":[{"s":"Kerem","en":"Zara, how much flour do I need?","tr":"Zara, ne kadar una ihtiyacım var?"},{"s":"Zara","en":"One cup, I think. Read the recipe again.","tr":"Sanırım bir bardak. Tarifi bir daha oku."},{"s":"Kerem","en":"Oh, it says one and a half cups! Thanks.","tr":"Ah, bir buçuk bardak yazıyor! Teşekkürler."},{"s":"Zara","en":"No problem. Don't forget to heat the pan first.","tr":"Sorun değil. Önce tavayı ısıtmayı unutma."},{"s":"Kerem","en":"Got it. Should the milk be warm or cold?","tr":"Anladım. Süt ılık mı olmalı yoksa soğuk mu?"},{"s":"Zara","en":"Room temperature is best. And don't make the mix too thick.","tr":"Oda sıcaklığı en iyisi. Bir de karışımı çok koyu yapma."}]},{"title":"Sharing at the cooking club","setting":"Okulun yemek kulübünde arkadaşlar Kerem'in pankeklerini tadıyor.","lines":[{"s":"Zara","en":"How do they taste, Kerem?","tr":"Nasıl tadı var, Kerem?"},{"s":"Kerem","en":"One side is a bit burnt, sorry.","tr":"Bir tarafı biraz yanmış, özür dilerim."},{"s":"Zara","en":"Don't worry. They're delicious!","tr":"Endişelenme. Çok lezzetliler!"},{"s":"Kerem","en":"Really? Next time I'll watch the pan more carefully.","tr":"Gerçekten mi? Bir dahaki sefere tavayı daha dikkatli izlerim."},{"s":"Zara","en":"Maybe we can have a pancake contest at school.","tr":"Belki okulda bir pankek yarışması yapabiliriz."},{"s":"Kerem","en":"Great idea! Let's ask our teacher.","tr":"Harika fikir! Öğretmenimize soralım."}]}],"reading":{"title":"Kerem's pancakes","paras":[{"en":"Last Sunday, Kerem decided to cook pancakes for his family. First, he read the recipe carefully. He needed flour, two eggs, milk and a little sugar. He mixed everything in a big bowl, then cooked the pancakes in a hot pan. They were a bit burnt, but everybody ate them all, and Kerem smiled.","tr":"Geçen pazar Kerem ailesi için pankek pişirmeye karar verdi. Önce tarifi dikkatlice okudu. Un, iki yumurta, süt ve biraz şeker lazımdı. Her şeyi büyük bir kâsede karıştırdı, sonra pankekleri sıcak tavada pişirdi. Biraz yanmışlardı ama herkes hepsini yedi ve Kerem gülümsedi."}]},"vocab":[{"w":"recipe","ipa":"/ˈresɪpi/","pos":"📖","tr":"tarif","ex":"Read the recipe first.","exTr":"Önce tarifi oku."},{"w":"ingredient","ipa":"/ɪnˈɡriːdiənt/","pos":"🥕","tr":"malzeme","ex":"Flour is an important ingredient.","exTr":"Un önemli bir malzemedir."},{"w":"flour","ipa":"/ˈflaʊə/","pos":"🌾","tr":"un","ex":"We need more flour.","exTr":"Daha fazla una ihtiyacımız var."},{"w":"mix","ipa":"/mɪks/","pos":"🥄","tr":"karıştırmak","ex":"Mix the eggs and milk.","exTr":"Yumurtaları ve sütü karıştır."},{"w":"bowl","ipa":"/bəʊl/","pos":"🥣","tr":"kâse","ex":"Put the sugar in a bowl.","exTr":"Şekeri bir kâseye koy."},{"w":"pan","ipa":"/pæn/","pos":"🍳","tr":"tava","ex":"Heat the pan first.","exTr":"Önce tavayı ısıt."},{"w":"delicious","ipa":"/dɪˈlɪʃəs/","pos":"😋","tr":"çok lezzetli","ex":"This cake is delicious!","exTr":"Bu kek çok lezzetli!"},{"w":"burnt","ipa":"/bɜːnt/","pos":"🔥","tr":"yanmış","ex":"The toast is burnt.","exTr":"Tost yanmış."}],"chunks":[{"en":"Let's cook something fun!","tr":"Eğlenceli bir şey pişirelim!"},{"en":"Read the recipe again.","tr":"Tarifi bir daha oku."},{"en":"Don't forget to…","tr":"…unutma."},{"en":"It's delicious!","tr":"Çok lezzetli!"}],"grammar":{"point":"Imperatives for instructions","tr":"Talimat verirken cümleyi doğrudan fiille başlatırız: 'Mix', 'Heat', 'Read'. Uyarı ya da yasak için başına 'Don't' gelir, 'Don't forget' gibi. Türkçedeki emir kipine benzer.","examples":["Mix the eggs and milk.","Heat the pan first.","Read the recipe again.","Don't forget the sugar."]},"questions":[{"q":"What did Kerem cook for his family?","a":"Pancakes."},{"q":"What was wrong with the pancakes?","a":"They were a bit burnt."},{"q":"What does Zara suggest at the end?","a":"A pancake contest at school."}],"quiz":[{"q":"Mix the eggs in a ___.","o":["pan","bowl","flour"],"a":1,"why":"Yumurtayı kâsede karıştırırsın."},{"q":"'Don't ___ the sugar.'","o":["forget","forgets","forgot"],"a":0,"why":"Don't'tan sonra fiilin yalın hâli gelir."},{"q":"This soup is really ___!","o":["flour","burnt","delicious"],"a":2,"why":"Delicious = çok lezzetli."},{"q":"What do you cook food in?","o":["recipe","pan","milk"],"a":1,"why":"Yemeği tavada pişirirsin."}],"drills":[{"type":"Yerine koyma","prompt":"Mix the flour and the eggs.","cue":"the milk","answer":"Mix the milk and the eggs."},{"type":"Dönüştürme","prompt":"Don't forget the sugar.","cue":"Remember to…","answer":"Remember to add the sugar."},{"type":"Soru yap","prompt":"Read the recipe first.","cue":"Should we…?","answer":"Should we read the recipe first?"}],"sounds":[{"focus":"/ʌ/ – /ɒ/","tr":"Türkçede /ʌ/ sesi yok; 'a' gibi ama ağzı daha gevşek ve orta yükseklikte söyle. /ɒ/ için dudaklarını hafifçe yuvarla ve kısa bir 'o' gibi söyle.","pairs":["cup / cop","cut / cot","luck / lock"]}],"mission":{"brief":"Yemek kulübü için bir tarif seçtin ve arkadaşın Ben'e malzemeleri ve adımları İngilizce anlatacaksın. Claude, Ben'i oynayacak; ona doğru sorular sorarak gizli bir bilgiyi öğrenmelisin.","persona":"Ben, a classmate in the cooking club. Friendly, a little dramatic, and loves cake. Hidden fact: he is allergic to nuts, but he only mentions it if the learner asks whether there is anything he must avoid in the recipe.","goal":"Ben'in dikkat etmesi gereken bir malzemeyi öğren ve bir tarif adımını İngilizce anlat.","opener":"Hi! Are you making something for the cooking club? I'm so hungry already!"}},"KS3-022":{"objectives":["Müzik trendlerini ve sevdiğin şarkıları İngilizce anlatmak","Bir çalma listesi hakkında arkadaşınla konuşmak","Sevme fiillerinden sonra '-ing' hâlini kullanmak"],"dialogues":[{"title":"Favourite songs","setting":"Müzik dersinde öğretmen, öğrencilere şu an hangi şarkıları dinlediklerini soruyor.","lines":[{"s":"Teacher","en":"What's trending in your playlists right now?","tr":"Çalma listelerinizde şu anda hangi trendler var?"},{"s":"Ali","en":"I'm really into a catchy pop song. The chorus is amazing!","tr":"Akılda kalıcı bir pop şarkısına çok kafayı taktım. Nakarat harika!"},{"s":"Lily","en":"Mine is a song from a new singer. Everyone shares it online.","tr":"Benimki yeni bir sanatçının şarkısı. Herkes internette paylaşıyor."},{"s":"Teacher","en":"Why do you think it's so popular?","tr":"Sence neden bu kadar popüler?"},{"s":"Ali","en":"It's short, and the chorus is easy to sing along to.","tr":"Kısa ve nakaratı birlikte söylemek çok kolay."},{"s":"Lily","en":"And it works really well in short videos.","tr":"Ayrıca kısa videolarda gerçekten çok iyi çalışıyor."}]},{"title":"Making a playlist","setting":"Lily, arkadaşı Ali'ye okul gezisi için yeni bir çalma listesi hazırlamasında yardım ediyor.","lines":[{"s":"Ali","en":"Can you help me make a playlist for the school trip?","tr":"Okul gezisi için bir çalma listesi yapmama yardım eder misin?"},{"s":"Lily","en":"Sure! What kind of music do you like?","tr":"Tabii! Ne tür müzik seviyorsun?"},{"s":"Ali","en":"I like upbeat songs, but I also love slow ones.","tr":"Hareketli şarkıları severim ama yavaş olanları da çok severim."},{"s":"Lily","en":"Then add a mix of both. I'll add some old songs from my vinyl collection too.","tr":"O zaman ikisinden de karışık ekle. Plak koleksiyonumdan bazı eski şarkıları da koyacağım."},{"s":"Ali","en":"Vinyl? Wow, I didn't know you had records!","tr":"Plak mı? Vay, plağın olduğunu bilmiyordum!"},{"s":"Lily","en":"They sound warm. You should try them one day.","tr":"Sesleri sıcak. Bir gün denemelisin."}]},{"title":"Concert plans","setting":"Ali ve Lily, mayıs ayındaki okul konseriyle ilgili planlarını konuşuyor.","lines":[{"s":"Lily","en":"Have you heard about the school concert in May?","tr":"Mayıs ayındaki okul konserini duydun mu?"},{"s":"Ali","en":"Yes! Our band will play a popular song there.","tr":"Evet! Bizim grup orada popüler bir şarkı çalacak."},{"s":"Lily","en":"Maybe we can sing the chorus together.","tr":"Belki nakaratı birlikte söyleyebiliriz."},{"s":"Ali","en":"Good idea. Let's practise it at lunch.","tr":"İyi fikir. Öğle yemeğinde çalışalım."},{"s":"Lily","en":"And I'll share the playlist with the whole class.","tr":"Ben de çalma listesini tüm sınıfla paylaşırım."},{"s":"Ali","en":"Perfect! Thanks, Lily.","tr":"Mükemmel! Teşekkürler, Lily."}]}],"reading":{"title":"Music trends","paras":[{"en":"Music trends change quickly. A few years ago, very long songs were popular, but now short songs with a catchy chorus win the most fans. Many teens listen to playlists on their phones and share their favourite tracks with friends. Some people still love vinyl records, which have a warm sound. Trends come and go, but good music always finds its audience.","tr":"Müzik trendleri hızla değişir. Birkaç yıl önce çok uzun şarkılar popülerdi, ama şimdi akılda kalıcı bir nakarata sahip kısa şarkılar en çok hayranı kazanıyor. Birçok genç çalma listelerini telefonlarından dinler ve sevdikleri parçaları arkadaşlarıyla paylaşır. Bazı insanlar hâlâ sıcak bir sesi olan vinil plakları seviyor. Trendler gelip geçer, ama iyi müzik her zaman dinleyicisini bulur."}]},"vocab":[{"w":"trend","ipa":"/trend/","pos":"📈","tr":"trend, moda eğilim","ex":"Short songs are a big trend now.","exTr":"Kısa şarkılar şu an büyük bir trend."},{"w":"catchy","ipa":"/ˈkætʃi/","pos":"🎶","tr":"akılda kalıcı","ex":"This song has a catchy tune.","exTr":"Bu şarkının akılda kalıcı bir melodisi var."},{"w":"chorus","ipa":"/ˈkɔːrəs/","pos":"🎤","tr":"nakarat","ex":"Everyone sings the chorus.","exTr":"Herkes nakaratı söylüyor."},{"w":"playlist","ipa":"/ˈpleɪlɪst/","pos":"🎧","tr":"çalma listesi","ex":"I made a new playlist.","exTr":"Yeni bir çalma listesi yaptım."},{"w":"popular","ipa":"/ˈpɒpjələ/","pos":"⭐","tr":"popüler","ex":"That band is very popular.","exTr":"O grup çok popüler."},{"w":"share","ipa":"/ʃeə/","pos":"📤","tr":"paylaşmak","ex":"Can you share your playlist?","exTr":"Çalma listeni paylaşabilir misin?"},{"w":"vinyl","ipa":"/ˈvaɪnl/","pos":"💿","tr":"vinil plak","ex":"My dad has old vinyl records.","exTr":"Babamın eski vinil plakları var."},{"w":"concert","ipa":"/ˈkɒnsət/","pos":"🎟","tr":"konser","ex":"The concert starts at seven.","exTr":"Konser yedide başlıyor."}],"chunks":[{"en":"What's trending right now?","tr":"Şu anda ne trend?"},{"en":"I'm really into…","tr":"…a gerçekten kafayı taktım."},{"en":"Have you heard about…?","tr":"…hakkında bir şey duydun mu?"},{"en":"Let's practise it at lunch.","tr":"Öğle yemeğinde çalışalım."}],"grammar":{"point":"Verbs of liking followed by -ing","tr":"Like, love, enjoy ve hate gibi fiillerden sonra başka bir fiil gelecekse genellikle '-ing' hâli kullanılır. Bu, Türkçedeki '-mayı, -meyi' ekine karşılık gelir: 'I like singing' yani 'şarkı söylemeyi severim'.","examples":["I like listening to pop songs.","She loves singing in the choir.","We enjoy dancing at parties.","He hates waiting for the bus."]},"questions":[{"q":"Why are short songs popular now?","a":"They have a catchy chorus and win the most fans."},{"q":"How do many teens listen to music?","a":"On their phones, with playlists."},{"q":"What does Lily ask Ali to try?","a":"Vinyl records."}],"quiz":[{"q":"The part of a song that people sing again and again is the ___.","o":["trend","concert","chorus"],"a":2,"why":"Nakarat, şarkının tekrar eden kısmıdır."},{"q":"Lily will ___ the playlist with the class.","o":["share","shares","sharing"],"a":0,"why":"'Will'den sonra fiilin yalın hâli gelir."},{"q":"Ali really enjoys ___ at parties.","o":["dance","dancing","danced"],"a":1,"why":"Enjoy'dan sonra -ing gelir."},{"q":"Vinyl records have a ___ sound.","o":["cold","loud","warm"],"a":2,"why":"Lily, plakların sıcak sesi olduğunu söylüyor."}],"drills":[{"type":"Yerine koyma","prompt":"I like listening to pop songs.","cue":"rap","answer":"I like listening to rap."},{"type":"Dönüştürme","prompt":"We enjoy dancing at parties.","cue":"olumsuz yap (don't enjoy)","answer":"We don't enjoy dancing at parties."},{"type":"Soru yap","prompt":"Lily shares the playlist with the class.","cue":"Does…?","answer":"Does Lily share the playlist with the class?"}],"sounds":[{"focus":"/ŋ/","tr":"Türkçede 'n' sesi genelde ön damakta çıkar. /ŋ/ için dilinin arka kısmını yumuşak damağa kaldır ve sesi burundan çıkar. Sonuna 'g' sesi ekleme: 'sing' 'sing-g' gibi değil.","pairs":["sing / sin","ring / rim","bang / ban"]}],"mission":{"brief":"Okul radyosu için müzik trendleri hakkında kısa bir konuşma yapacaksın. Claude, radyo sunucusu Maya'yı oynayacak; ona sevdiğin şarkıyı ve nedenini anlat, bir yandan da yaklaşan bir etkinliği öğrenmeye çalış.","persona":"Maya, a school radio host. Enthusiastic and asks lots of follow-up questions. Hidden fact: she needs one volunteer to set up the sound system for the school concert, but she only mentions this if the learner asks about upcoming events or how they can help.","goal":"Maya'ya sevdiğin bir şarkıyı ve nedenini anlat; yaklaşan bir etkinlikle ilgili bir bilgi öğren.","opener":"Hi! Welcome to the school radio. What's trending in your playlist right now?"}},"KS3-023":{"objectives":["Video yapımcılığının adımlarını İngilizce anlatmak","Birine tavsiye vermek için 'should' kullanmak","Ekran süresi ve çevrimiçi yorumlar hakkında fikrini söylemek"],"dialogues":[{"title":"Filming in the park","setting":"Deniz, arkadaşı Ella'nın yardımıyla parkta kısa bir video çekiyor.","lines":[{"s":"Deniz","en":"Ella, can you hold the camera? I want to film a short clip.","tr":"Ella, kamerayı tutar mısın? Kısa bir klip çekmek istiyorum."},{"s":"Ella","en":"Sure! Ready? Action!","tr":"Tabii! Hazır mısın? Kamera, başla!"},{"s":"Deniz","en":"Hi everyone! Today I'm reviewing a new app.","tr":"Herkese merhaba! Bugün yeni bir uygulamayı inceliyorum."},{"s":"Ella","en":"Oops, the sound is too quiet. Let's film it again.","tr":"Ups, ses çok kısık. Bir daha çekelim."},{"s":"Deniz","en":"Okay, but this time let's stand in the shade.","tr":"Tamam, ama bu sefer gölgede duralım."},{"s":"Ella","en":"Good idea. The light is much better there.","tr":"İyi fikir. Işık orada çok daha iyi."}]},{"title":"Editing at home","setting":"Akşam, Deniz bilgisayarında videoyu düzenlerken annesi onu uyarıyor.","lines":[{"s":"Mum","en":"Deniz, you've been editing for three hours. You should take a break.","tr":"Deniz, üç saattir video düzenliyorsun. Biraz mola vermelisin."},{"s":"Deniz","en":"Just a minute, Mum. I need to edit this last part.","tr":"Bir dakika anne. Bu son kısmı düzenlemem lazım."},{"s":"Mum","en":"Your eyes need rest. Upload the video tomorrow.","tr":"Gözlerinin dinlenmeye ihtiyacı var. Videoyu yarın yükle."},{"s":"Deniz","en":"But my audience is waiting for it!","tr":"Ama izleyicilerim onu bekliyor!"},{"s":"Mum","en":"Your audience can wait a few hours. You should take a walk.","tr":"İzleyicilerin birkaç saat bekleyebilir. Biraz yürüyüşe çıkmalısın."},{"s":"Deniz","en":"Okay, you're right. I'll take a break now.","tr":"Tamam, haklısın. Şimdi mola vereceğim."}]},{"title":"Reading the comments","setting":"Ella, Deniz'in son videosuna gelen yorumları birlikte okuyor.","lines":[{"s":"Ella","en":"Look, your video has lots of new views!","tr":"Bak, videonun birçok yeni izlenmesi var!"},{"s":"Deniz","en":"Really? Let me see the comments.","tr":"Gerçekten mi? Yorumlara bakayım."},{"s":"Ella","en":"Most of them are kind. But this one is really mean.","tr":"Çoğu nazik. Ama bu gerçekten kırıcı."},{"s":"Deniz","en":"I'll ignore that one. Let's read the kind ones.","tr":"Onu görmezden geleceğim. Nazik olanları okuyalım."},{"s":"Ella","en":"Great! This one says the editing is amazing.","tr":"Harika! Bu yorum düzenlemenin çok iyi olduğunu söylüyor."},{"s":"Deniz","en":"That makes me smile. Thanks, Ella.","tr":"Bu beni gülümsetti. Teşekkürler, Ella."}]}],"reading":{"title":"Life as a video creator","paras":[{"en":"Many teenagers dream of becoming video creators. A creator films, edits and uploads short clips for an online audience. The work looks fun, but it takes a lot of time. You need a good idea, a clear voice and a simple editing app. Creators also read comments, both kind and unkind. Successful creators plan their week, take regular breaks and remember that friends matter more than views.","tr":"Birçok genç video yapımcısı olmayı hayal eder. Bir yapımcı, çevrimiçi bir kitle için kısa klipler çeker, düzenler ve yükler. İş eğlenceli görünür ama çok zaman alır. İyi bir fikre, net bir sese ve basit bir düzenleme uygulamasına ihtiyacın var. Yapımcılar nazik ve kırıcı yorumları da okur. Başarılı yapımcılar haftalarını planlar, düzenli mola verir ve arkadaşların izlenmelerden daha önemli olduğunu unutmaz."}]},"vocab":[{"w":"creator","ipa":"/kriˈeɪtə/","pos":"🎬","tr":"içerik üreticisi","ex":"She is a video creator.","exTr":"O bir video üreticisi."},{"w":"upload","ipa":"/ʌpˈləʊd/","pos":"📤","tr":"yüklemek","ex":"I will upload the video tonight.","exTr":"Videoyu bu gece yükleyeceğim."},{"w":"edit","ipa":"/ˈedɪt/","pos":"✂","tr":"düzenlemek","ex":"I edit my clips on my phone.","exTr":"Kliplerimi telefonumda düzenliyorum."},{"w":"audience","ipa":"/ˈɔːdiəns/","pos":"👥","tr":"izleyici kitlesi","ex":"The audience loved the clip.","exTr":"İzleyiciler klibi çok sevdi."},{"w":"clip","ipa":"/klɪp/","pos":"🎞","tr":"kısa klip","ex":"This clip is only one minute long.","exTr":"Bu klip sadece bir dakika uzunluğunda."},{"w":"comment","ipa":"/ˈkɒment/","pos":"💬","tr":"yorum","ex":"Please leave a kind comment.","exTr":"Lütfen nazik bir yorum bırak."},{"w":"break","ipa":"/breɪk/","pos":"☕","tr":"mola","ex":"Let's take a break.","exTr":"Biraz mola verelim."},{"w":"views","ipa":"/vjuːz/","pos":"👀","tr":"izlenme","ex":"The video has a thousand views.","exTr":"Videonun bin izlenmesi var."}],"chunks":[{"en":"Let's film it again.","tr":"Bir daha çekelim."},{"en":"Just a minute.","tr":"Bir dakika."},{"en":"You should take a break.","tr":"Biraz mola vermelisin."},{"en":"Don't read the mean comments.","tr":"Kırıcı yorumları okuma."}],"grammar":{"point":"Should and shouldn't for advice","tr":"Birine tavsiye vermek için 'should' kullanılır: 'You should rest.' Türkçedeki '-malı, -meli' ekine karşılık gelir. Olumsuzu 'shouldn't' olur ve 'should' her özne için aynı kalır.","examples":["You should take a break.","You shouldn't read mean comments.","She should upload the video today.","We should film it again."]},"questions":[{"q":"What does a video creator do?","a":"They film, edit and upload short clips."},{"q":"Why does Mum tell Deniz to take a break?","a":"Because Deniz has been editing for three hours."},{"q":"What do successful creators remember?","a":"That friends matter more than views."}],"quiz":[{"q":"Deniz wants to ___ the video tonight.","o":["upload","forget","break"],"a":0,"why":"Upload = videoyu yüklemek."},{"q":"Mum says: You ___ take a walk.","o":["shoulds","should","to should"],"a":1,"why":"Should'dan sonra fiil yalın gelir, -s veya to almaz."},{"q":"The people who watch a video are the ___.","o":["editor","audience","creator"],"a":1,"why":"Audience = izleyici kitlesi."},{"q":"Ella says the light is much ___ in the shade.","o":["gooder","more good","better"],"a":2,"why":"Better = daha iyi."}],"drills":[{"type":"Yerine koyma","prompt":"You should take a break.","cue":"a walk","answer":"You should take a walk."},{"type":"Dönüştürme","prompt":"We should film it again.","cue":"olumsuz yap (shouldn't)","answer":"We shouldn't film it again."},{"type":"Soru yap","prompt":"She should upload the video today.","cue":"Should…?","answer":"Should she upload the video today?"}],"sounds":[{"focus":"/ɜː/","tr":"Türkçede bu ses yok. Dilini ağzının ortasında tut, dudakların hafif gerilmiş olsun ve sesi 'e' gibi kısa bırakmadan uzat.","pairs":["bird / bed","heard / head","word / wed"]}],"mission":{"brief":"Video yapımcısı olmayı düşünüyorsun. Claude, eskiden kısa videolar çekmiş olan Mert'i oynayacak; ona neden video yapmak istediğini anlat ve onun deneyimleri hakkında sorular sor.","persona":"Mert, a former video creator who made short clips for five thousand followers. Chatty and honest. Hidden fact: he stopped making videos last summer because of cruel comments, and he still misses it; he only admits this if the learner asks how he felt about the comments or why he stopped.","goal":"Mert'e neden video yapmak istediğini anlat ve onun deneyimiyle ilgili en az bir bilgi öğren.","opener":"Hey! I used to make videos too. What kind of clips would you like to create?"}},"KS3-024":{"objectives":["Kural ve zorunluluk anlatan cümleler kurmak","Bir kuralla ilgili görüşünü İngilizce savunmak","Özgürlük ile sorumluluk arasındaki farkı açıklamak"],"dialogues":[{"title":"Bedtime talk","setting":"Akşam yemeğinden sonra Eren, annesiyle hafta sonu yatma saati hakkında konuşuyor.","lines":[{"s":"Eren","en":"Mum, can I stay up until eleven on weekends?","tr":"Anne, hafta sonları on bire kadar uyanık kalabilir miyim?"},{"s":"Mum","en":"That's late. What's your plan for tomorrow?","tr":"Bu geç. Yarın için planın ne?"},{"s":"Eren","en":"I have to finish my science project, and then I want to relax.","tr":"Fen projemi bitirmem gerek ve sonra dinlenmek istiyorum."},{"s":"Mum","en":"Good. You must finish your homework first. Then we can talk.","tr":"Güzel. Önce ödevlerini bitirmelisin. Sonra konuşuruz."},{"s":"Eren","en":"That's not fair! My friends stay up later than me.","tr":"Bu adil değil! Arkadaşlarım benden daha geç yatıyor."},{"s":"Mum","en":"Fairness is about responsibility, Eren. Show me you can keep your promises.","tr":"Adalet sorumlulukla ilgilidir, Eren. Sözlerini tutabildiğini göster."}]},{"title":"Class debate","setting":"Sınıfta öğretmen, öğrencilerden ödev saatiyle ilgili bir tartışma yapmalarını istiyor.","lines":[{"s":"Teacher","en":"Today's debate: should students choose their own homework time?","tr":"Bugünkü tartışma: öğrenciler ödev saatini kendileri seçmeli mi?"},{"s":"Lara","en":"Yes! Freedom is important, and I can manage my own time.","tr":"Evet! Özgürlük önemli ve zamanımı kendim yönetebilirim."},{"s":"Eren","en":"I'm not sure. Some students need a clear rule to stay focused.","tr":"Emin değilim. Bazı öğrencilerin odaklanmak için net bir kurala ihtiyacı var."},{"s":"Teacher","en":"Good point. Can a rule also be fair?","tr":"İyi bir nokta. Bir kural aynı zamanda adil olabilir mi?"},{"s":"Lara","en":"Yes, if everyone agrees on it together.","tr":"Evet, herkes birlikte kabul ederse."},{"s":"Eren","en":"So we need to agree on this rule before we vote.","tr":"O zaman oy vermeden önce bu kurala birlikte karar vermemiz gerekiyor."}]},{"title":"A deal at home","setting":"Lara ve Eren parkta, ev kuralları için bir anlaşma yapmanın yollarını konuşuyor.","lines":[{"s":"Lara","en":"My parents said I have to be home by nine.","tr":"Ailem dokuzda evde olmam gerektiğini söyledi."},{"s":"Eren","en":"That's early. Did you ask for a later time?","tr":"Bu erken. Daha geç bir saat istedin mi?"},{"s":"Lara","en":"Yes, but they want me to show I'm responsible first.","tr":"Evet, ama önce sorumlu olduğumu göstermemi istiyorlar."},{"s":"Eren","en":"Let's make a deal. You finish your chores, and they give you an extra hour.","tr":"Bir anlaşma yapalım. Ev işlerini bitirirsen sana bir saat daha verirler."},{"s":"Lara","en":"I like that idea. I don't have to ask for much.","tr":"Bu fikri beğendim. Çok bir şey istemem gerekmiyor."},{"s":"Eren","en":"Exactly. Small steps first, then more freedom.","tr":"Aynen. Önce küçük adımlar, sonra daha fazla özgürlük."}]}],"reading":{"title":"Rules and freedom","paras":[{"en":"Rules can feel annoying, but they help us live together. At home, rules may be about bedtime, homework or screen time. At school, rules protect everyone's safety and give us time to learn. Freedom means making your own choices. As you grow up, you get more freedom, but responsible teens show they can keep their promises first. Then parents usually learn to trust them more.","tr":"Kurallar sinir bozucu hissettirebilir ama birlikte yaşamamıza yardımcı olurlar. Evde kurallar yatma saati, ödev ya da ekran süresi ile ilgili olabilir. Okulda kurallar herkesin güvenliğini korur ve öğrenmek için bize zaman tanır. Özgürlük, kendi seçimlerini yapmak demektir. Büyüdükçe daha fazla özgürlük kazanırsın, ama sorumlu gençler önce sözlerini tuttuklarını gösterir. Sonra anne babalar genellikle onlara daha çok güvenmeyi öğrenir."}]},"vocab":[{"w":"rule","ipa":"/ruːl/","pos":"📏","tr":"kural","ex":"Here is the rule: no phones in class.","exTr":"Kural şu: derste telefon yok."},{"w":"freedom","ipa":"/ˈfriːdəm/","pos":"🕊","tr":"özgürlük","ex":"We want more freedom.","exTr":"Daha fazla özgürlük istiyoruz."},{"w":"responsible","ipa":"/rɪˈspɒnsəbl/","pos":"✅","tr":"sorumlu","ex":"You are responsible for your room.","exTr":"Odandan sen sorumlusun."},{"w":"bedtime","ipa":"/ˈbedtaɪm/","pos":"🌙","tr":"yatma saati","ex":"My bedtime is nine o'clock.","exTr":"Yatma saatim dokuz."},{"w":"screen time","ipa":"/skriːn taɪm/","pos":"📱","tr":"ekran süresi","ex":"Screen time is limited on school days.","exTr":"Okul günlerinde ekran süresi sınırlı."},{"w":"debate","ipa":"/dɪˈbeɪt/","pos":"🗣","tr":"tartışma","ex":"The debate was very interesting.","exTr":"Tartışma çok ilginçti."},{"w":"trust","ipa":"/trʌst/","pos":"🤝","tr":"güven","ex":"Trust is important in friendship.","exTr":"Arkadaşlıkta güven önemlidir."},{"w":"choice","ipa":"/tʃɔɪs/","pos":"🔀","tr":"seçim","ex":"It's your choice.","exTr":"Seçim senin."}],"chunks":[{"en":"That's not fair!","tr":"Bu adil değil!"},{"en":"We need to agree on this.","tr":"Bu konuda anlaşmamız gerek."},{"en":"I'm old enough to decide.","tr":"Karar verecek yaştayım."},{"en":"Let's make a deal.","tr":"Bir anlaşma yapalım."}],"grammar":{"point":"Must, have to and mustn't","tr":"Kural ve zorunluluk anlatırken 'must' ve 'have to' kullanılır; Türkçedeki '-malı, -meli' ya da '-mak zorunda' gibi. 'Mustn't' yasak anlamına gelir; 'don't have to' ise bir şeyin zorunlu olmadığını söyler.","examples":["You must be home by nine.","We have to finish our homework first.","You mustn't use your phone in class.","You don't have to cook tonight."]},"questions":[{"q":"What do school rules protect?","a":"Everyone's safety and time to learn."},{"q":"How can teens get more freedom?","a":"By showing they are responsible and keeping their promises."},{"q":"What does Lara's family ask her to show first?","a":"That she is responsible."}],"quiz":[{"q":"You ___ use your phone in class.","o":["mustn't","don't have to","have to"],"a":0,"why":"Mustn't = yasak."},{"q":"We ___ finish our homework first.","o":["don't have to","must","mustn't"],"a":1,"why":"Must = zorunluluk."},{"q":"You ___ cook tonight. Mum will do it.","o":["must","don't have to","mustn't"],"a":1,"why":"Zorunlu değil, annen yapacak."},{"q":"What does 'responsible' mean?","o":["tired","funny","responsible"],"a":2,"why":"Responsible = sorumlu."}],"drills":[{"type":"Yerine koyma","prompt":"You must be home by nine.","cue":"ten","answer":"You must be home by ten."},{"type":"Dönüştürme","prompt":"You have to clean your room.","cue":"don't have to","answer":"You don't have to clean your room."},{"type":"Soru yap","prompt":"We have to finish the project.","cue":"Do we…?","answer":"Do we have to finish the project?"}],"sounds":[{"focus":"/s/ – /z/","tr":"Türkçede /z/ sesi var, ama İngilizcede bu sesi sesli söylemek kolay görünmez. /z/ için dilini ve dudaklarını /s/ ile aynı tut, sadece ses tellerini titret.","pairs":["rice / rise","lose / loose","ice / eyes"]}],"mission":{"brief":"Ailenle yeni bir ev kuralı hakkında konuşacaksın. Claude, annen olarak rol yapacak; ona özgürlük için ikna edici bir teklif sun ve annenin hangi koşulda kabul edeceğini öğren.","persona":"Mum, a fair but cautious parent. Speaks calmly and asks for responsibility before giving freedom. Hidden fact: she would agree to a later bedtime on weekends if the learner shows finished homework and a clear plan, but she only reveals this if asked what would change her mind.","goal":"Annenin hangi koşulu kabul edeceğini öğren ve ona uygun bir kuralı İngilizce öner.","opener":"Hi sweetheart. You wanted to talk about the bedtime rule. What's on your mind?"}},"KS3-025":{"objectives":["Bir olayı geçmiş zamanla kısaca haber olarak anlatmak","Birine röportaj sorusu sormak","Düzensiz geçmiş zaman fiillerini doğru kullanmak"],"dialogues":[{"title":"Planning the news","setting":"Okul gazetesi ekibi, bu haftaki ana haberi seçmek için toplanıyor.","lines":[{"s":"Selin","en":"Let's decide our main story for this week.","tr":"Bu haftaki ana haberimize karar verelim."},{"s":"Noah","en":"How about the science fair? It was great.","tr":"Bilim fuarı nasıl olur? Harikaydı."},{"s":"Selin","en":"Good idea. Did you get any interviews?","tr":"İyi fikir. Hiç röportaj aldın mı?"},{"s":"Noah","en":"Yes, I talked to the winner, Ege, yesterday.","tr":"Evet, dün kazanan Ege ile konuştum."},{"s":"Selin","en":"Perfect. Please check the facts before we write.","tr":"Mükemmel. Yazmadan önce bilgileri kontrol et lütfen."},{"s":"Noah","en":"Of course. I'll write the first draft tonight.","tr":"Tabii. İlk taslağı bu akşam yazacağım."}]},{"title":"Interviewing the head teacher","setting":"Selin, okul müdürü ile kısa bir röportaj yapıyor.","lines":[{"s":"Selin","en":"Thanks for meeting me. Can I ask you a few questions?","tr":"Benimle görüştüğünüz için teşekkürler. Birkaç soru sorabilir miyim?"},{"s":"Teacher","en":"Of course. Go ahead.","tr":"Tabii. Buyur."},{"s":"Selin","en":"What happened at the science fair?","tr":"Bilim fuarında ne oldu?"},{"s":"Teacher","en":"More than two hundred students showed their projects. The judges were really impressed.","tr":"İki yüzden fazla öğrenci projelerini sergiledi. Jüri gerçekten etkilendi."},{"s":"Selin","en":"Which project surprised you the most?","tr":"Hangi proje sizi en çok şaşırttı?"},{"s":"Teacher","en":"A small robot that could sort recycling. It was amazing.","tr":"Geri dönüşümü ayırabilen küçük bir robot. İnanılmazdı."}]},{"title":"Checking the draft","setting":"Öğretmen, Noah'ın haber taslağını okuyor ve geri bildirim veriyor.","lines":[{"s":"Teacher","en":"Noah, your headline is clear. Good work!","tr":"Noah, başlığın net. Güzel iş!"},{"s":"Noah","en":"Thanks. Is the first paragraph too long?","tr":"Teşekkürler. İlk paragraf çok uzun mu?"},{"s":"Teacher","en":"A little. Start with the winner, then give the details.","tr":"Biraz. Kazananla başla, sonra ayrıntıları ver."},{"s":"Noah","en":"Got it. I'll also add a quote from the judges.","tr":"Anladım. Jürinin bir sözünü de ekleyeceğim."},{"s":"Teacher","en":"Excellent. Let's check the facts together.","tr":"Mükemmel. Bilgileri birlikte kontrol edelim."},{"s":"Noah","en":"Yes! I want the report to be perfect.","tr":"Evet! Haberin mükemmel olmasını istiyorum."}]}],"reading":{"title":"The science fair","paras":[{"en":"Last Friday, our school held a science fair. More than two hundred students showed their projects in the sports hall. The best project was a small robot that could sort recycling. The judges were surprised by its design. The winner, Ege, said he was very happy. The fair ended with a music show, and many parents came to watch.","tr":"Geçen cuma okulumuz bir bilim fuarı düzenledi. İki yüzden fazla öğrenci projelerini spor salonunda sergiledi. En iyi proje, geri dönüşüm malzemelerini ayırabilen küçük bir robottu. Jüri tasarımından etkilendi. Birinci olan Ege çok mutlu olduğunu söyledi. Fuar bir müzik gösterisiyle sona erdi ve birçok veli izlemeye geldi."}]},"vocab":[{"w":"report","ipa":"/rɪˈpɔːt/","pos":"📰","tr":"haber, rapor","ex":"Noah wrote a report about the fair.","exTr":"Noah fuar hakkında bir haber yazdı."},{"w":"project","ipa":"/ˈprɒdʒekt/","pos":"🧪","tr":"proje","ex":"My project is about plants.","exTr":"Projem bitkiler hakkında."},{"w":"judge","ipa":"/dʒʌdʒ/","pos":"⚖","tr":"jüri üyesi, hakem","ex":"The judge liked my robot.","exTr":"Jüri üyesi robotumu sevdi."},{"w":"winner","ipa":"/ˈwɪnə/","pos":"🏆","tr":"kazanan","ex":"The winner got a gold medal.","exTr":"Kazanan altın madalya aldı."},{"w":"surprised","ipa":"/səˈpraɪzd/","pos":"😮","tr":"şaşırmış","ex":"I was surprised by the news.","exTr":"Haberden şaşırdım."},{"w":"recycling","ipa":"/riːˈsaɪklɪŋ/","pos":"♻","tr":"geri dönüşüm","ex":"Recycling is good for the planet.","exTr":"Geri dönüşüm gezegen için iyidir."},{"w":"interview","ipa":"/ˈɪntəvjuː/","pos":"🎤","tr":"röportaj","ex":"I have an interview with the coach.","exTr":"Antrenörle bir röportajım var."},{"w":"hall","ipa":"/hɔːl/","pos":"🏫","tr":"salon","ex":"The concert is in the hall.","exTr":"Konser salonda."}],"chunks":[{"en":"Did you hear the news?","tr":"Haberi duydun mu?"},{"en":"Can I ask you a few questions?","tr":"Birkaç soru sorabilir miyim?"},{"en":"Let's check the facts.","tr":"Bilgileri kontrol edelim."},{"en":"That's a great quote.","tr":"Bu harika bir söz."}],"grammar":{"point":"Past simple in news reports","tr":"Bir olayı haber olarak anlatırken geçmiş zaman (past simple) kullanılır. Düzenli fiillere '-ed' eklenir: 'played', 'asked'. Düzensiz fiillerde ise biçim değişir: 'won', 'made', 'came'.","examples":["The students won the match yesterday.","The judges liked the robot.","Ege made a small robot.","Many parents came to watch the show."]},"questions":[{"q":"What was the best project at the science fair?","a":"A small robot that could sort recycling."},{"q":"Who was the winner of the fair?","a":"Ege."},{"q":"How did the fair end?","a":"With a music show."}],"quiz":[{"q":"Ege ___ a small robot.","o":["made","make","makes"],"a":0,"why":"Geçmiş zaman: made."},{"q":"The judges ___ very impressed yesterday.","o":["was","were","are"],"a":1,"why":"Judges çoğul olduğu için were."},{"q":"Many parents ___ to watch the show.","o":["come","comes","came"],"a":2,"why":"Come'ın geçmiş zamanı came."},{"q":"A text that tells the news is a ___.","o":["recipe","report","project"],"a":1,"why":"Report = haber, rapor."}],"drills":[{"type":"Yerine koyma","prompt":"Ege made a small robot.","cue":"a big boat","answer":"Ege made a big boat."},{"type":"Dönüştürme","prompt":"The judges liked the robot.","cue":"Did…?","answer":"Did the judges like the robot?"},{"type":"Genişletme","prompt":"The fair ended with a show.","cue":"+ in the hall","answer":"The fair ended with a show in the hall."}],"sounds":[{"focus":"/æ/ – /e/","tr":"Türkçede /æ/ sesi yok. 'E' gibi söyleme; ağzını geniş aç, çenen aşağı insin ve sesi 'a' ile 'e' arasında tut. /e/ ise daha dar ve kısa bir 'e'dir.","pairs":["bad / bed","man / men","bat / bet"]}],"mission":{"brief":"Okul gazetesi için bilim fuarı hakkında bir haber yazacaksın. Claude, okul müdür yardımcısı Bay Lee'yi oynayacak; ona doğru sorular sorarak olayın ne zaman, nerede ve kimler tarafından yapıldığını öğren.","persona":"Mr Lee, the school's deputy head. Calm, a bit busy, and answers in short sentences. Hidden fact: the new school library opens next Monday, but he only mentions it if the learner asks about upcoming events or other news at school.","goal":"Haberin ne zaman, nerede ve kimler tarafından olduğunu öğren ve en az iki cümleyi geçmiş zamanla İngilizce yaz.","opener":"Hello! You're from the school newspaper, right? What would you like to know?"}},"KS3-026":{"objectives":["Bir tarihi gizemi basit İngilizceyle anlatmak","Geçmiş zaman 'was / were' kalıbını kullanmak","Bir cevabı bulmak için iyi sorular sormak"],"dialogues":[{"title":"A strange old coin","setting":"Müzede iki arkadaş eski bir madeni parayı inceliyor.","lines":[{"s":"Elif","en":"Look at this old coin! It was found near a castle.","tr":"Şu eski madeni paraya bak! Bir kalenin yakınında bulunmuş."},{"s":"Can","en":"Wow! Who was the king on it?","tr":"Vay! Üstündeki kral kimdi?"},{"s":"Elif","en":"Nobody knows. The name is missing.","tr":"Kimse bilmiyor. Adı silinmiş."},{"s":"Can","en":"That's a real mystery! Was the castle near our town?","tr":"Bu gerçek bir gizem! Kale bizim kasabanın yakınında mıydı?"},{"s":"Elif","en":"Yes, it was. It is about five hundred years old.","tr":"Evet, öyleydi. Yaklaşık beş yüz yıllık."},{"s":"Can","en":"Let's ask our teacher. He loves history!","tr":"Öğretmenimize soralım. Tarihi çok sever!"}]},{"title":"The worn-out letter","setting":"Sınıfta öğretmen tarih gizemini açıklıyor.","lines":[{"s":"Teacher","en":"I have a clue. The coin had a letter, but it is worn out.","tr":"Bir ipucum var. Paranın üzerinde bir harf vardı ama aşınmış."},{"s":"Elif","en":"Was it an M or a W?","tr":"M miydi yoksa W mi?"},{"s":"Teacher","en":"Good question! Scientists think it was an M.","tr":"İyi soru! Bilim insanları M olduğunu düşünüyor."},{"s":"Can","en":"So the king's name starts with M?","tr":"Yani kralın adı M harfiyle mi başlıyor?"},{"s":"Teacher","en":"Maybe. We are not sure, so we need more clues.","tr":"Belki. Emin değiliz, o yüzden daha fazla ipucuna ihtiyacımız var."},{"s":"Elif","en":"Then let's go to the library!","tr":"O zaman kütüphaneye gidelim!"}]},{"title":"The map in the book","setting":"Kütüphanede Can eski bir kitap buluyor.","lines":[{"s":"Can","en":"Look! I found an old book under a table.","tr":"Bak! Bir masanın altında eski bir kitap buldum."},{"s":"Elif","en":"Open it carefully! Are there any pictures?","tr":"Dikkatli aç! Hiç resim var mı?"},{"s":"Can","en":"Yes, there is a map. It shows a castle on a hill.","tr":"Evet, bir harita var. Bir tepedeki bir kaleyi gösteriyor."},{"s":"Elif","en":"Is it the same castle? That's amazing!","tr":"Aynı kale mi? Bu harika!"},{"s":"Can","en":"Yes! The map says the king hid his treasure there.","tr":"Evet! Haritaya göre kral hazinesini orada saklamış."},{"s":"Elif","en":"Our history project will be the best!","tr":"Tarih projemiz en iyisi olacak!"}]}],"reading":{"title":"The mystery coin","paras":[{"en":"Last summer, a girl named Elif found an old coin near a castle. The coin was dirty and very old. Nobody could read the king's name because one letter was worn out. Elif showed the coin to her teacher. They looked at books and maps for many days. Now they think the coin is from a very old time. Maybe one day they will find the answer!","tr":"Geçen yaz Elif adında bir kız kale yakınında eski bir madeni para buldu. Para kirliydi ve çok eskiydi. Bir harf aşındığı için kimse kralın adını okuyamadı. Elif parayı öğretmenine gösterdi. Birçok gün boyunca kitaplara ve haritalara baktılar. Şimdi paranın çok eski bir döneme ait olduğunu düşünüyorlar. Belki bir gün cevabı bulacaklar!"}]},"vocab":[{"w":"coin","ipa":"/kɔɪn/","pos":"🪙","tr":"madeni para","ex":"This coin is very old.","exTr":"Bu madeni para çok eski."},{"w":"castle","ipa":"/ˈkɑːsl/","pos":"🏰","tr":"kale","ex":"The castle is on a hill.","exTr":"Kale bir tepenin üstünde."},{"w":"king","ipa":"/kɪŋ/","pos":"🤴","tr":"kral","ex":"The king lived in the castle.","exTr":"Kral kalede yaşadı."},{"w":"map","ipa":"/mæp/","pos":"🗺️","tr":"harita","ex":"The map shows the river.","exTr":"Harita nehri gösteriyor."},{"w":"treasure","ipa":"/ˈtreʒə/","pos":"💰","tr":"hazine","ex":"The treasure was in a box.","exTr":"Hazine bir kutunun içindeydi."},{"w":"clue","ipa":"/kluː/","pos":"🔍","tr":"ipucu","ex":"I have a clue!","exTr":"Bir ipucum var!"},{"w":"mystery","ipa":"/ˈmɪstri/","pos":"❓","tr":"gizem","ex":"This is a big mystery.","exTr":"Bu büyük bir gizem."},{"w":"book","ipa":"/bʊk/","pos":"📖","tr":"kitap","ex":"I found an old book.","exTr":"Eski bir kitap buldum."}],"chunks":[{"en":"Look at this…!","tr":"Şuna bak…!"},{"en":"Who was it?","tr":"Kimdi?"},{"en":"Let's ask…","tr":"…soralım."},{"en":"That's a real mystery!","tr":"Bu gerçek bir gizem!"}],"grammar":{"point":"Past simple: was / were","tr":"Geçmişte olan bir durumu anlatmak için 'was' ve 'were' kullanılır. Tek bir şey için 'was', birden çok şey için 'were' gelir. Türkçedeki '-di' ekine benzer.","examples":["The coin was very old.","The castle was on a hill.","The books were under the table.","The maps were in the library."]},"questions":[{"q":"Where was the coin found?","a":"Near a castle."},{"q":"Why can't they read the king's name?","a":"Because one letter is worn out."},{"q":"What did Can find in the library?","a":"An old book with a map."}],"quiz":[{"q":"The coin ___ very old.","o":["were","was","are"],"a":1,"why":"Tek bir şey için 'was' kullanılır."},{"q":"The books ___ under the table.","o":["was","is","were"],"a":2,"why":"Birden çok kitap için 'were' gelir."},{"q":"A word that means 'gizem' is…","o":["clue","mystery","castle"],"a":1,"why":""},{"q":"The map shows a ___ on a hill.","o":["castle","coin","king"],"a":0,"why":""}],"drills":[{"type":"Yerine koyma","prompt":"The coin was very old.","cue":"book","answer":"The book was very old."},{"type":"Dönüştürme","prompt":"The books were under the table.","cue":"one book (singular)","answer":"The book was under the table."},{"type":"Soru yap","prompt":"The map shows a castle on a hill.","cue":"Does…?","answer":"Does the map show a castle on a hill?"}],"sounds":[{"focus":"/w/ – /v/","tr":"Türkçede 'v' var ama 'w' yok. 'W' için dudaklarını yuvarlayıp hemen aç; dudağın dişlere değmesin.","pairs":["was / vas","west / vest"]}],"mission":{"brief":"Müzedeki bir gizemi İngilizce anlatacaksın. Claude, meraklı bir tarih rehberi olacak; sen de doğru sorularla gizemi çözmeye çalışacaksın.","persona":"Professor Ada, a cheerful history guide. Speaks slowly with short sentences. Hidden fact: the treasure is hidden under the old well in the castle garden. She only reveals it after the learner asks good questions about the castle, the coin or the map.","goal":"Hazinenin nerede olduğunu İngilizce sorularla öğren.","opener":"Hello! I am Professor Ada. I have a big history mystery for you. Do you want to solve it?"}},"KS3-027":{"objectives":["Çevreyi korumak için basit bir eylem planı anlatmak","'will' ve 'can' ile ne yapacağımızı ve yapabileceğimizi söylemek","Bir öneriye kısa ve doğal cevaplar vermek"],"dialogues":[{"title":"Our green club","setting":"Okul çevre kulübünün ilk toplantısı. Öğretmen, Selin ve Mert konuşuyor.","lines":[{"s":"Teacher","en":"Good afternoon, club! Today we make an action plan for our school.","tr":"İyi öğleden sonralar kulüp! Bugün okulumuz için bir eylem planı yapacağız."},{"s":"Selin","en":"Great! What will we do first?","tr":"Harika! İlk ne yapacağız?"},{"s":"Mert","en":"We will collect paper in new bins.","tr":"Yeni kutularda kâğıt toplayacağız."},{"s":"Teacher","en":"Good idea. What else can we do?","tr":"İyi fikir. Başka neler yapabiliriz?"},{"s":"Selin","en":"We can turn off the lights when we leave a room.","tr":"Bir odadan çıktığımızda ışıkları kapatabiliriz."},{"s":"Mert","en":"And we can plant trees in the garden!","tr":"Bir de bahçeye ağaç dikebiliriz!"},{"s":"Teacher","en":"Wonderful! Let's write it down.","tr":"Harika! Yazıp kaydedelim."}]},{"title":"Bins for paper","setting":"Sınıfta geri dönüşüm kutularının yerini konuşuyorlar.","lines":[{"s":"Mert","en":"Where should we put the paper bin?","tr":"Kâğıt kutusunu nereye koymalıyız?"},{"s":"Selin","en":"Near the door. Everyone will see it.","tr":"Kapının yanına. Herkes görecek."},{"s":"Ece","en":"Can we make a bin for plastic too?","tr":"Plastik için de bir kutu yapabilir miyiz?"},{"s":"Mert","en":"Yes, we can! I will bring a box from home.","tr":"Evet, yapabiliriz! Evden bir kutu getireceğim."},{"s":"Selin","en":"Thank you, Mert. Ece, you can make the labels.","tr":"Teşekkürler Mert. Ece, etiketleri sen yapabilirsin."},{"s":"Ece","en":"Okay! I will draw a bottle and a sheet of paper.","tr":"Tamam! Bir şişe ve bir kâğıt çizeceğim."}]},{"title":"Our promise","setting":"Okul bahçesinde plan panosunu gösteriyorlar.","lines":[{"s":"Principal","en":"Hello, students! Show me your plan.","tr":"Merhaba öğrenciler! Planınızı bana gösterin."},{"s":"Selin","en":"Every Friday, one student will check the bins.","tr":"Her Cuma bir öğrenci kutuları kontrol edecek."},{"s":"Principal","en":"That's a good promise. Will you check the lights too?","tr":"Bu iyi bir söz. Işıkları da kontrol edecek misiniz?"},{"s":"Mert","en":"Yes, we will. We can make our school cleaner and greener!","tr":"Evet, edeceğiz. Okulumuzu daha temiz ve daha yeşil yapabiliriz!"},{"s":"Principal","en":"I am proud of you. Keep going!","tr":"Sizinle gurur duyuyorum. Devam edin!"}]}],"reading":{"title":"Our school action plan","paras":[{"en":"Our class made an action plan to protect the environment. First, we will collect paper and plastic in new bins. Second, we will turn off lights when we leave a room. Third, we will plant trees in the school garden. Every Friday, one student will check the plan. We hope our school will be cleaner and greener!","tr":"Sınıfımız çevreyi korumak için bir eylem planı hazırladı. İlk olarak yeni kutularda kâğıt ve plastik toplayacağız. İkinci olarak odadan çıktığımızda ışıkları kapatacağız. Üçüncü olarak okul bahçesine ağaç dikeceğiz. Her Cuma bir öğrenci planı kontrol edecek. Okulumuzun daha temiz ve daha yeşil olmasını umuyoruz!"}]},"vocab":[{"w":"plan","ipa":"/plæn/","pos":"📝","tr":"plan","ex":"Our plan is simple.","exTr":"Planımız basit."},{"w":"collect","ipa":"/kəˈlekt/","pos":"🧺","tr":"toplamak","ex":"We collect old bottles.","exTr":"Eski şişeleri topluyoruz."},{"w":"bin","ipa":"/bɪn/","pos":"🗑️","tr":"kutu, çöp kutusu","ex":"Put the paper in the bin.","exTr":"Kâğıdı kutuya koy."},{"w":"plant","ipa":"/plɑːnt/","pos":"🌱","tr":"dikmek","ex":"We will plant a tree.","exTr":"Bir ağaç dikeceğiz."},{"w":"tree","ipa":"/triː/","pos":"🌳","tr":"ağaç","ex":"The tree is big and green.","exTr":"Ağaç büyük ve yeşil."},{"w":"lights","ipa":"/laɪts/","pos":"💡","tr":"ışıklar","ex":"Turn off the lights.","exTr":"Işıkları kapat."},{"w":"clean","ipa":"/kliːn/","pos":"🧹","tr":"temiz","ex":"Our school is clean.","exTr":"Okulumuz temiz."},{"w":"check","ipa":"/tʃek/","pos":"✅","tr":"kontrol etmek","ex":"Who will check the bins?","exTr":"Kutuları kim kontrol edecek?"}],"chunks":[{"en":"Let's make a plan!","tr":"Bir plan yapalım!"},{"en":"We can…","tr":"…yapabiliriz."},{"en":"Good idea!","tr":"İyi fikir!"},{"en":"Let's write it down.","tr":"Yazıp kaydedelim."}],"grammar":{"point":"will and can","tr":"'Will' gelecekte ne yapacağımızı söylemek için kullanılır. 'Can' ise bir şeyi yapabileceğimizi anlatır. İkisinden sonra fiil 'to' olmadan gelir.","examples":["We will plant trees.","We can turn off the lights.","I will bring a box.","She can make the labels."]},"questions":[{"q":"What will the class plant?","a":"Trees in the school garden."},{"q":"When will they turn off the lights?","a":"When they leave a room."},{"q":"Who will check the plan every Friday?","a":"One student."}],"quiz":[{"q":"We ___ turn off the lights.","o":["bin","can","clean"],"a":1,"why":""},{"q":"🗑️ is a…","o":["tree","plan","bin"],"a":2,"why":""},{"q":"'Collect' means…","o":["toplamak","dikmek","kontrol etmek"],"a":0,"why":"Collect = toplamak."},{"q":"We ___ plant trees in the garden.","o":["bin","clean","will"],"a":2,"why":""}],"drills":[{"type":"Yerine koyma","prompt":"We will collect paper.","cue":"plastic","answer":"We will collect plastic."},{"type":"Dönüştürme","prompt":"We can turn off the lights.","cue":"question form","answer":"Can we turn off the lights?"},{"type":"Genişletme","prompt":"We will plant trees.","cue":"+ in the school garden","answer":"We will plant trees in the school garden."}],"sounds":[{"focus":"/ɪ/ – /iː/","tr":"Kısa /ɪ/ sesi gevşek ve kısadır; uzun /iː/ sesinde ise dudaklar yana gerilir. Türkçede bu fark yok, o yüzden iki kelimeyi yan yana dinleyerek ayır.","pairs":["bin / bean","ship / sheep","lives / leaves"]}],"mission":{"brief":"Okulunuz için basit bir çevre planı hazırla ve okul müdürüne İngilizce sun. Claude, müdür Bay Kaya olacak; ona üç öneri sun ve birini onaylatmaya çalış.","persona":"Mr. Kaya, a kind school principal who speaks slowly. Hidden fact: the school has a small budget, so he can only afford one set of bins this year and prefers ideas that cost nothing. He only mentions this if the learner asks about costs or budget.","goal":"Üç öneriyi İngilizce sun ve Bay Kaya'dan bir onay al.","opener":"Hello! I hear you have a plan for a greener school. Tell me your ideas!"}},"KS3-028":{"objectives":["Bir projeyi sınıfa kısaca sunmak","Üçüncü tekil kişi için fiile -s eklemek","Dinleyicileri soru sormaya davet etmek"],"dialogues":[{"title":"Practice before the show","setting":"Sunumdan önce Ella ve arkadaşı Leo prova yapıyor.","lines":[{"s":"Ella","en":"Can you listen to my presentation? It's about bees.","tr":"Sunumumu dinler misin? Arılarla ilgili."},{"s":"Leo","en":"Of course! Start when you're ready.","tr":"Tabii! Hazır olduğunda başla."},{"s":"Ella","en":"Hello, everyone. My name is Ella. My project is about bees.","tr":"Merhaba herkese. Benim adım Ella. Projem arılarla ilgili."},{"s":"Leo","en":"Good! Speak more slowly, please.","tr":"İyi! Lütfen daha yavaş konuş."},{"s":"Ella","en":"Okay. Bees help plants grow. They make honey too.","tr":"Tamam. Arılar bitkilerin büyümesine yardım eder. Bal da yaparlar."},{"s":"Leo","en":"Nice! Now show the poster.","tr":"Harika! Şimdi posteri göster."}]},{"title":"Showing the poster","setting":"Sınıfta Ella posterini gösteriyor, öğretmen dinliyor.","lines":[{"s":"Ella","en":"Here is my poster. It shows a bee hive.","tr":"İşte posterim. Bir arı kovanı gösteriyor."},{"s":"Teacher","en":"Wow, that's a big poster! Who is your audience?","tr":"Vay, bu büyük bir poster! Dinleyicileriniz kim?"},{"s":"Ella","en":"My classmates and you, of course!","tr":"Sınıf arkadaşlarım ve tabii ki siz!"},{"s":"Leo","en":"The slide is clear. Thank you, Ella.","tr":"Slayt çok net. Teşekkürler Ella."},{"s":"Teacher","en":"Good job. Now, ask the audience a question.","tr":"Aferin. Şimdi dinleyicilere bir soru sor."},{"s":"Ella","en":"Any questions? Please raise your hand.","tr":"Sorunuz var mı? Lütfen elinizi kaldırın."}]},{"title":"Questions from the audience","setting":"Sunumun sonunda bir öğrenci soru soruyor.","lines":[{"s":"Leo","en":"How many bees live in one hive?","tr":"Bir kovanda kaç arı yaşar?"},{"s":"Ella","en":"Thanks for the question, Leo! Around 40,000 bees.","tr":"Soru için teşekkürler Leo! Yaklaşık 40.000 arı."},{"s":"Teacher","en":"Great answer! You spoke clearly.","tr":"Harika cevap! Net konuştun."},{"s":"Ella","en":"Thank you all for listening!","tr":"Hepinize dinlediğiniz için teşekkürler!"},{"s":"Leo","en":"That was a fantastic presentation.","tr":"Muhteşem bir sunumdu."}]}],"reading":{"title":"Ella's bee project","paras":[{"en":"Ella presents her science project about bees. First, she says hello and smiles. Then she shows a big poster with bright pictures. She speaks slowly and looks at the audience. Bees help plants grow, Ella says. At the end, she thanks everyone and asks, 'Any questions?' A boy raises his hand and asks a good question.","tr":"Ella bilim projesini arılar hakkında sunuyor. Önce merhaba diyor ve gülümsüyor. Sonra parlak resimlerle dolu büyük bir poster gösteriyor. Yavaş konuşuyor ve dinleyicilere bakıyor. Ella, arıların bitkilerin büyümesine yardım ettiğini söylüyor. Sonunda herkese teşekkür ediyor ve 'Sorunuz var mı?' diye soruyor. Bir çocuk elini kaldırıyor ve iyi bir soru soruyor."}]},"vocab":[{"w":"project","ipa":"/ˈprɒdʒekt/","pos":"📁","tr":"proje","ex":"My project is about bees.","exTr":"Projem arılarla ilgili."},{"w":"present","ipa":"/prɪˈzent/","pos":"🎤","tr":"sunmak","ex":"She presents her project.","exTr":"Projesini sunuyor."},{"w":"poster","ipa":"/ˈpəʊstə/","pos":"🖼️","tr":"poster","ex":"The poster has bright pictures.","exTr":"Posterde parlak resimler var."},{"w":"audience","ipa":"/ˈɔːdiəns/","pos":"👥","tr":"dinleyiciler","ex":"The audience is listening.","exTr":"Dinleyiciler dinliyor."},{"w":"bee","ipa":"/biː/","pos":"🐝","tr":"arı","ex":"The bee is on a flower.","exTr":"Arı bir çiçeğin üstünde."},{"w":"slide","ipa":"/slaɪd/","pos":"📑","tr":"slayt","ex":"This slide is clear.","exTr":"Bu slayt net."},{"w":"question","ipa":"/ˈkwestʃən/","pos":"❓","tr":"soru","ex":"I have a question.","exTr":"Bir sorum var."},{"w":"thank","ipa":"/θæŋk/","pos":"🙏","tr":"teşekkür etmek","ex":"I thank you all.","exTr":"Hepinize teşekkür ederim."}],"chunks":[{"en":"Here is my…","tr":"İşte benim…"},{"en":"Any questions?","tr":"Sorunuz var mı?"},{"en":"Speak more slowly, please.","tr":"Lütfen daha yavaş konuş."},{"en":"Thank you for listening!","tr":"Dinlediğiniz için teşekkürler!"}],"grammar":{"point":"Present simple: he / she / it + -s","tr":"Üçüncü tekil kişi (he, she, it) için fiilin sonuna -s ya da -es eklenir. I, you, we ve they ile eklenmez. Bu farka dikkat etmek cümleleri doğru kurmanı sağlar.","examples":["She presents her project.","He shows a poster.","It helps the plants grow.","She thanks the audience."]},"questions":[{"q":"What does Ella show the audience?","a":"A big poster with bright pictures."},{"q":"How does Ella speak?","a":"Slowly."},{"q":"What question does Leo ask?","a":"How many bees live in one hive?"}],"quiz":[{"q":"She ___ her project.","o":["present","presents","presenting"],"a":1,"why":"Üçüncü tekil kişide fiile -s eklenir."},{"q":"We ___ our project.","o":["presents","presenting","present"],"a":2,"why":"We ile -s eklenmez."},{"q":"'Audience' means…","o":["dinleyiciler","sunum","soru"],"a":0,"why":""},{"q":"Which is the best way to end a talk?","o":["Slow, please!","Thank you for listening!","Bees, please!"],"a":1,"why":""}],"drills":[{"type":"Yerine koyma","prompt":"She presents her project.","cue":"he","answer":"He presents his project."},{"type":"Dönüştürme","prompt":"We present our poster.","cue":"She","answer":"She presents her poster."},{"type":"Genişletme","prompt":"The bee helps plants.","cue":"+ grow","answer":"The bee helps plants grow."}],"sounds":[{"focus":"/θ/","tr":"Dilinin ucunu dişlerinin arasına koy ve hafifçe üfle. 's' ya da 't' gibi okumadan, sadece nefes sesi çıkar.","pairs":["thank / tank","three / free","think / sink"]}],"mission":{"brief":"Projeni İngilizce kısaca sun. Claude, meraklı bir sınıf arkadaşı olan Leo olacak; sunumun sonunda sana sorular soracak.","persona":"Leo, a curious classmate who asks one short question at a time. Hidden fact: he has to present his own project next week and is nervous about it, but he only admits this if the learner asks how he feels about presenting.","goal":"Projeni üç cümleyle İngilizce anlat ve Leo'dan bir soru al.","opener":"Hi! Are you ready to show me your project? I'm all ears!"}},"KS3-029":{"objectives":["Bir arkadaşına İngilizce röportaj sorusu sormak","'Do' ve 'does' ile soru oluşturmak","Öğrendiklerini kısa notlarla yazmak"],"dialogues":[{"title":"Getting ready","setting":"Öğretmen sınıfa röportaj ödevini anlatıyor.","lines":[{"s":"Teacher","en":"Today's homework is an interview. Find a partner and ask five questions.","tr":"Bugünkü ödev bir röportaj. Bir arkadaş bul ve beş soru sor."},{"s":"Ece","en":"Can I interview Kerem? He's fun!","tr":"Kerem'le röportaj yapabilir miyim? Çok eğlenceli!"},{"s":"Kerem","en":"Sure, Ece! Let's start.","tr":"Tabii Ece! Başlayalım."},{"s":"Ece","en":"Do you like sports?","tr":"Spor yapmayı sever misin?"},{"s":"Kerem","en":"Yes, I do! I play basketball every Friday.","tr":"Evet severim! Her Cuma basketbol oynarım."},{"s":"Teacher","en":"Good! Write your questions on paper first.","tr":"Güzel! Önce sorularını kâğıda yaz."},{"s":"Ece","en":"I'm writing now. Thanks, Teacher!","tr":"Şimdi yazıyorum. Teşekkürler öğretmenim!"}]},{"title":"The interview","setting":"Ece, Kerem'e sorularını soruyor ve notlarını alıyor.","lines":[{"s":"Ece","en":"Does your family have pets?","tr":"Ailenin evcil hayvanı var mı?"},{"s":"Kerem","en":"Yes, we have a cat. Her name is Pamuk.","tr":"Evet, bir kedimiz var. Adı Pamuk."},{"s":"Ece","en":"Where do you live?","tr":"Nerede yaşıyorsun?"},{"s":"Kerem","en":"I live near the park, in İzmir.","tr":"İzmir'de, parkın yakınında yaşıyorum."},{"s":"Ece","en":"What does your dad like to cook?","tr":"Baban ne pişirmeyi sever?"},{"s":"Kerem","en":"He makes pizza every Sunday. It's delicious!","tr":"Her Pazar pizza yapar. Çok lezzetli!"},{"s":"Ece","en":"What do you want to be when you grow up?","tr":"Büyüyünce ne olmak istiyorsun?"},{"s":"Kerem","en":"I want to be a pilot. I love planes!","tr":"Pilot olmak istiyorum. Uçakları seviyorum!"}]},{"title":"Writing the notes","setting":"Ece notlarını kontrol ediyor ve Kerem'le konuşuyor.","lines":[{"s":"Ece","en":"Let me check my notes. Kerem likes basketball.","tr":"Notlarıma bakayım. Kerem basketbolu seviyor."},{"s":"Kerem","en":"Yes, and I draw too. Write that down!","tr":"Evet, bir de resim yaparım. Onu da yaz!"},{"s":"Ece","en":"Do you draw every day?","tr":"Her gün resim yapar mısın?"},{"s":"Kerem","en":"Almost every day! Drawing helps me relax.","tr":"Hemen hemen her gün! Resim yapmak beni rahatlatıyor."},{"s":"Ece","en":"Great. Now I can write about you.","tr":"Harika. Artık senin hakkında yazabilirim."},{"s":"Kerem","en":"Good luck! Please make me look cool.","tr":"Bol şans! Beni havalı göster lütfen."},{"s":"Ece","en":"Don't worry, I will!","tr":"Merak etme, öyle yapacağım!"}]}],"reading":{"title":"A great interview","paras":[{"en":"Ece has a big task: interview a classmate and write about him. She prepares five questions before class. Her partner is Kerem. Kerem's hobbies are basketball and drawing. His favourite food is pizza, and his dream is to become a pilot. Ece writes short notes about his answers. Later, she will read them to the class. She is excited!","tr":"Ece'nin büyük bir görevi var: bir sınıf arkadaşıyla röportaj yapmak ve onun hakkında yazmak. Derse başlamadan önce beş soru hazırlıyor. Röportaj ortağı Kerem. Kerem'in hobileri basketbol ve resim. En sevdiği yemek pizza ve hayali pilot olmak. Ece, yanıtları hakkında kısa notlar alıyor. Daha sonra notlarını sınıfa okuyacak. Çok heyecanlı!"}]},"vocab":[{"w":"interview","ipa":"/ˈɪntəvjuː/","pos":"🎙️","tr":"röportaj","ex":"The interview is on Monday.","exTr":"Röportaj pazartesi."},{"w":"classmate","ipa":"/ˈklɑːsmeɪt/","pos":"👫","tr":"sınıf arkadaşı","ex":"My classmate likes football.","exTr":"Sınıf arkadaşım futbolu sever."},{"w":"favourite","ipa":"/ˈfeɪvərɪt/","pos":"⭐","tr":"en sevilen","ex":"Pizza is my favourite food.","exTr":"Pizza en sevdiğim yemek."},{"w":"hobby","ipa":"/ˈhɒbi/","pos":"🎨","tr":"hobi","ex":"Drawing is my hobby.","exTr":"Resim yapmak benim hobim."},{"w":"answer","ipa":"/ˈɑːnsə/","pos":"💬","tr":"cevap","ex":"Her answer was short.","exTr":"Cevabı kısaydı."},{"w":"notes","ipa":"/nəʊts/","pos":"📝","tr":"notlar","ex":"I write notes in class.","exTr":"Derste not alırım."},{"w":"pilot","ipa":"/ˈpaɪlət/","pos":"✈️","tr":"pilot","ex":"My uncle is a pilot.","exTr":"Amcam pilot."},{"w":"dream","ipa":"/driːm/","pos":"💭","tr":"hayal","ex":"My dream is to fly.","exTr":"Hayalim uçmak."}],"chunks":[{"en":"Can I interview you?","tr":"Seninle röportaj yapabilir miyim?"},{"en":"What do you want to be?","tr":"Ne olmak istiyorsun?"},{"en":"Let me check my notes.","tr":"Notlarıma bakayım."},{"en":"Good luck!","tr":"Bol şans!"}],"grammar":{"point":"Questions with do and does","tr":"Soru yaparken I, you, we ve they ile 'do', he, she ve it ile 'does' kullanılır. Soru cümlesinde fiil artık -s almaz. Soru kelimesi varsa önce o gelir, sonra 'do' ya da 'does'.","examples":["Do you like sports?","Does your dad like cooking?","Where do you live?","What does she want to be?"]},"questions":[{"q":"What does Ece prepare before class?","a":"Five questions."},{"q":"What are Kerem's hobbies?","a":"Basketball and drawing."},{"q":"Why does Ece write notes?","a":"To remember Kerem's answers."}],"quiz":[{"q":"___ you like sports?","o":["Does","Do","Is"],"a":1,"why":"You ile 'do' kullanılır."},{"q":"___ she live near the park?","o":["Does","Do","Is"],"a":0,"why":"She ile 'does' kullanılır."},{"q":"Where ___ Kerem live?","o":["do","does","is"],"a":1,"why":"Kerem he gibidir, o yüzden 'does'."},{"q":"'Notlar' in English is…","o":["notes","answer","favourite"],"a":0,"why":""}],"drills":[{"type":"Soru yap","prompt":"You want to be a pilot.","cue":"Do…?","answer":"Do you want to be a pilot?"},{"type":"Yerine koyma","prompt":"Do you like sports?","cue":"he","answer":"Does he like sports?"},{"type":"Genişletme","prompt":"Kerem likes basketball.","cue":"+ very much","answer":"Kerem likes basketball very much."}],"sounds":[{"focus":"/ɔː/ – /ɒ/","tr":"Türkçede bu iki sesi ayırmayız. /ɔː/ dudakları yuvarlayıp uzun bir 'o' gibi söylenir; /ɒ/ ise daha kısa ve açık bir 'o'dur.","pairs":["port / pot","law / lot","fork / fox"]}],"mission":{"brief":"Sınıf arkadaşın Kerem'i İngilizce röportaj yap ve üç bilgi öğren. Claude, Kerem'i oynayacak; sen sorular sorarak onu tanıyacaksın.","persona":"Kerem, a cheerful classmate who loves basketball and drawing. Hidden fact: he has a secret plan to learn to fly a small plane next summer and has not told anyone yet. He only shares it if the learner asks about his plans or his dream.","goal":"Üç farklı soru sor ve Kerem'in gizli hayalini öğren.","opener":"Hi! Are you ready for the interview? Ask me anything you like!"}},"KS3-030":{"objectives":["Hayalindeki okulu İngilizce tarif etmek","'I'd like' kalıbıyla isteklerini nazikçe söylemek","Bir okul müdürüne fikir sunmak"],"dialogues":[{"title":"Designing my dream school","setting":"Deniz ve Ali sınıfta hayalî okullarını tasarlıyorlar.","lines":[{"s":"Deniz","en":"What is your ideal school like?","tr":"Senin hayalindeki okul nasıl?"},{"s":"Ali","en":"I'd like a huge library with comfy chairs.","tr":"Rahat koltuklu büyük bir kütüphane isterim."},{"s":"Deniz","en":"Nice! I'd like a swimming pool.","tr":"Harika! Ben bir yüzme havuzu isterim."},{"s":"Ali","en":"A pool? That's cool! And a big playground?","tr":"Havuz mu? Harika! Peki büyük bir oyun alanı?"},{"s":"Deniz","en":"Yes, and longer breaks too!","tr":"Evet, bir de daha uzun teneffüsler!"},{"s":"Ali","en":"I agree. Shorter lessons would be nice too.","tr":"Katılıyorum. Daha kısa dersler de güzel olurdu."},{"s":"Deniz","en":"Let's write the list now.","tr":"Şimdi listeyi yazalım."}]},{"title":"Rules and uniforms","setting":"Sınıfta okul kurallarını ve hayalî okuldaki ödevleri konuşuyorlar.","lines":[{"s":"Teacher","en":"In your ideal school, what about homework?","tr":"Hayalindeki okulda ödevler nasıl olur?"},{"s":"Ali","en":"I'd like less homework on weekends.","tr":"Hafta sonları daha az ödev isterim."},{"s":"Deniz","en":"I'd prefer not to wear a uniform. Wearing your own clothes is fun!","tr":"Üniforma giymemeyi tercih ederim. Kendi kıyafetlerini giymek eğlenceli!"},{"s":"Teacher","en":"Interesting. Why do you want that?","tr":"İlginç. Neden böyle istiyorsun?"},{"s":"Deniz","en":"We can show our personality with our clothes.","tr":"Kıyafetlerimizle kişiliğimizi gösterebiliriz."},{"s":"Ali","en":"I'd like a short break every hour, too.","tr":"Ayrıca her saat kısa bir teneffüs isterim."},{"s":"Teacher","en":"Great ideas! Write one sentence about each.","tr":"Harika fikirler! Her biri için bir cümle yaz."}]},{"title":"Presenting to the principal","setting":"Deniz hayalindeki okul fikrini müdüre sunuyor.","lines":[{"s":"Principal","en":"Hello, Deniz. Tell me about your ideal school.","tr":"Merhaba Deniz. Bana hayalindeki okuldan bahset."},{"s":"Deniz","en":"I'd like a library, a pool and a garden.","tr":"Bir kütüphane, bir havuz ve bir bahçe isterim."},{"s":"Principal","en":"A garden? That's an interesting idea.","tr":"Bahçe mi? İlginç bir fikir."},{"s":"Deniz","en":"Yes, we could grow our own vegetables!","tr":"Evet, kendi sebzelerimizi yetiştirebiliriz!"},{"s":"Principal","en":"I like that. Let's talk more next week.","tr":"Bunu beğendim. Gelecek hafta daha çok konuşalım."},{"s":"Deniz","en":"Thank you. I'd love that!","tr":"Teşekkürler. Bunu çok isterim!"}]}],"reading":{"title":"A school of my dreams","paras":[{"en":"My ideal school has a big library with soft chairs and a swimming pool. Classes start at nine and finish at two. There is a long break at noon, and a huge playground for games. We wear our own clothes, not uniforms. Homework is short, so we have time to read and draw. I think this school would make everybody happy!","tr":"Hayalimdeki okulda yumuşak koltuklu büyük bir kütüphane ve bir yüzme havuzu var. Dersler dokuzda başlayıp ikide bitiyor. Öğlen uzun bir teneffüs ve oyunlar için geniş bir oyun alanı var. Üniforma değil, kendi kıyafetlerimizi giyiyoruz. Ödevler kısa, bu yüzden okumaya ve resim yapmaya vaktimiz var. Bence bu okul herkesi mutlu eder!"}]},"vocab":[{"w":"ideal","ipa":"/aɪˈdiːəl/","pos":"⭐","tr":"hayalindeki, ideal","ex":"My ideal school has a garden.","exTr":"Hayalimdeki okulda bir bahçe var."},{"w":"library","ipa":"/ˈlaɪbrəri/","pos":"📚","tr":"kütüphane","ex":"The library is quiet.","exTr":"Kütüphane sessiz."},{"w":"pool","ipa":"/puːl/","pos":"🏊","tr":"havuz","ex":"The pool is big.","exTr":"Havuz büyük."},{"w":"lesson","ipa":"/ˈlesn/","pos":"📖","tr":"ders","ex":"Our lessons start at nine.","exTr":"Derslerimiz dokuzda başlıyor."},{"w":"homework","ipa":"/ˈhəʊmwɜːk/","pos":"📝","tr":"ödev","ex":"I do my homework at night.","exTr":"Ödevimi geceleri yaparım."},{"w":"playground","ipa":"/ˈpleɪɡraʊnd/","pos":"🛝","tr":"oyun alanı","ex":"The playground is near the trees.","exTr":"Oyun alanı ağaçların yanında."},{"w":"break","ipa":"/breɪk/","pos":"⏰","tr":"teneffüs","ex":"We have a long break at noon.","exTr":"Öğlen uzun bir teneffüsümüz var."},{"w":"uniform","ipa":"/ˈjuːnɪfɔːm/","pos":"👔","tr":"üniforma","ex":"We don't wear a uniform.","exTr":"Üniforma giymiyoruz."}],"chunks":[{"en":"I'd like a…","tr":"… isterim."},{"en":"Tell me about your…","tr":"Bana … hakkında anlat."},{"en":"I'd prefer not to…","tr":"… yapmamayı tercih ederim."},{"en":"That's an interesting idea.","tr":"Bu ilginç bir fikir."}],"grammar":{"point":"I'd like (would like)","tr":"Bir isteğimizi nazikçe söylemek için 'I'd like' kalıbını kullanırız. 'I'd' kısaltması 'I would' demektir ve Türkçedeki 'isterim' ile aynı anlama gelir. Bir fiil söyleyeceksek araya 'to' ekleriz.","examples":["I'd like a big library.","She'd like a swimming pool.","We would like shorter lessons.","I'd like to draw in the garden."]},"questions":[{"q":"What does the ideal school have?","a":"A big library with soft chairs and a swimming pool."},{"q":"When do classes finish?","a":"At two."},{"q":"Do the students in the ideal school wear uniforms?","a":"No, they wear their own clothes."}],"quiz":[{"q":"I'd ___ a big library.","o":["like","likes","liking"],"a":0,"why":"I'd like = isterim."},{"q":"The ideal school has a ___ with soft chairs.","o":["pool","library","break"],"a":1,"why":""},{"q":"Classes ___ at nine.","o":["finish","start","wear"],"a":1,"why":"Dersler dokuzda başlar."},{"q":"What is a 'break' in school?","o":["a lesson","a uniform","a rest time"],"a":2,"why":"Teneffüs bir dinlenme zamanıdır."}],"drills":[{"type":"Yerine koyma","prompt":"I'd like a big library.","cue":"swimming pool","answer":"I'd like a swimming pool."},{"type":"Dönüştürme","prompt":"We would like shorter lessons.","cue":"short form","answer":"We'd like shorter lessons."},{"type":"Genişletme","prompt":"I'd like to draw.","cue":"+ in the garden","answer":"I'd like to draw in the garden."}],"sounds":[{"focus":"/ʃ/ – /tʃ/","tr":"Türkçedeki 'ş' sesi /ʃ/ ile aynıdır. /tʃ/ ise önce 't' sonra 'ş' gibi, Türkçedeki 'ç' sesine benzer. Dilini damağına yaklaştırıp sesi ayır.","pairs":["shop / chop","sheep / cheap","wish / witch"]}],"mission":{"brief":"Hayalindeki okulu İngilizce tarif et ve okul müdürüne bir fikir sun. Claude, müdür Ms. Gül olacak; sana sorular soracak ve fikirlerini değerlendirecek.","persona":"Ms. Gül, a friendly school principal who speaks clearly and warmly. Hidden fact: she has wanted to start a school garden club for years, but nobody has ever asked her about it. She only shares this if the learner asks about her own ideas for the school.","goal":"Hayalindeki okul için üç özellik İngilizce söyle ve müdürün gizli fikrini öğren.","opener":"Hello! I'm Ms. Gül, the principal. What would your ideal school look like?"}}};